INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398736063', 'Carrinho Multiuso Wagon Até 65kg Cinza Safety 1St', 'Imagine ter um carrinho que facilita a sua vida em qualquer situação, seja na praia, no parque ou até mesmo em casa. O Carrinho Wagon Multiuso da Safety 1st é exatamente isso. Com capacidade para até 65 kg, ele é perfeito para carregar tudo o que você precisa, de forma segura e prática. - Manopla com alturas reguláveis em ambos os lados para 2 modos de uso: puxar ou empurrar - Capota removível e dobrável para armazenar, com proteção UV50+ - Grande capacidade de carga: até 65 kg - Capa completamente removível para limpeza - Lateral com abertura por zíperes e velcros para facilitar o acesso - Fechamento compacto para armazenar ou transportar - Rodas frontais fáceis de instalar e com giro 360° - Freio de pé - Muitos bolsos: porta-copos e porta-objetos Especificações: -Cor: Grey -Material: Estrutura: Ferro, PP | Tecido: 100% Poliéster -Dimensões AxLxP: 89,5 x 49,5 x 67,5 -Dimensões Fechado AxLxP: 32 x 49,5 x 67,5 -Peso: 13,300kg -Peso suportado 65kg -Garantia: 12 meses (Garantia Padrão) + 12 meses (Garantia Estendida*) -Conteúdo da embalagem: 1 carrinho multiuso', 1599.0, 1599.0, NULL, 'Mom & Baby > Baby Travel Essentials > Strollers & Travel Systems', 'https://cf.shopee.com.br/file/sg-11134201-7rdw3-mchuzutegw9g98', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1207408200%2F23398736063', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598325053', 'Caixa Térmica SUV 8 L Rosa Balé', 'A família SUV cresceu! Chegou a SUV 8 L, a nova caixa térmica da Termolar, que une design funcional, praticidade e inovação em um formato compacto. Disponível nas novas cores da coleção 25/26 — Cinza Plus com Verde Litoral, Rosa Balé e Marrom café da Tarde — ela tem capacidade para até 12 latas de 350 mL, 9 garrafas de 330 mL ou 8 latões de 473 mL. Sua tampa reversível vira uma mesinha com porta-copos e porta-celular, e o estojo para utensílios traz ainda mais praticidade. Com conservação térmica diferenciada, mantém até 9 horas de frio sem uso de gelo para alimentos e até 20 horas de frio com uso de gelo para bebidas. A tecnologia AirFlow permite a circulação de ar pela base sem contato com o piso, garantindo eficiência térmica. A alça retrátil com trava de segurança facilita o transporte e proporciona mais estabilidade, tornando a SUV 8 L a companheira perfeita para seus passeios, viagens e aventuras do dia a dia. SUV 8 L, seus momentos cabem aqui.', 99.9, 99.9, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/sg-11134201-7rd61-m7d6j80weyxkf4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1391525192%2F23598325053', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
