INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793327102', 'Odorizante Couro Novo 700ml Spray Finisher', 'Produto desenvolvido para aromatizar veículos após o processo de higienização. Aumenta a sensação de limpeza na entrega de um serviço. Fragrância elaborada para não diminuir a atenção do motorista. Cheiro nobre, que valoriza o serviço de limpeza em bancos de couro. O mais novo produto da linha de couro da Finisher referência no mercado. Nível de fixação: Até 2 dias. Nível de percepção Ao primeiro contato: Elevado. Após 5 minutos: Natural e Discreto. Categoria do Produto: Odorizantes Instruções de Uso Diluição: Produto Pronto Uso Borrife 3 ou 4 vezes em direção a cada tapete.', 51.9, 51.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Fragrances', 'https://cf.shopee.com.br/file/br-11134207-820m6-mosc9vusnvnn26', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F369458625%2F23793327102', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
