INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23503254381', 'Lixeira Dupla Abertura 8 L Cinza Plasútil', 'Lixeira Dupla Abertura 8 L Cinza Plasútil Dimensao: (Comp x Larg x Alt): 24,8 x 16,5 x 33,5 cm Capacidade: 8,0 L - Você conhece o novo conceito em lixeiras da Plasútil? - A lixeira com dupla abertura possui dos tipos de abertura na tampa através de um sistema basculante: total ou parcial. - Para abertura total, você deve pressionar com firmeza uma das abas. - Para abertura parcial, você deve pressionar levemente uma das abas. - Indicada para sacos de lixo de 15 L. - Fabricado em polipropileno (PP). - Livre de bisfenol-A (BPA FREE)..', 48.9, 48.9, NULL, 'Home & Living > Home Care Supplies > Trash & Recycling Bins', 'https://cf.shopee.com.br/file/sg-11134201-82609-mmgcqbz983cy0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F648928964%2F23503254381', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
