INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13246294698', 'Fralda Descartável Super Secão Cães Machos 12 Unidades Tam G', '- Indicado para cães machos; - Com cintura de 60 a 80cm; - Possui barreira anti-vazamento; - Proporciona super absorção; - Embalagem com 12 unidades. Fralda Descartável Super Secão Cães Machos Tam G - 12un As Fraldas Descartáveis Super Secão Cães Machos possuem design especial e matérias primas de alta qualidade, a fralda para cães é indicada para as mais diversas modalidades, sendo algumas delas: passeios e viagens, cães com incontinência urinária, em período de cio, operados ou em reabilitação. Tem Comfort fit Design de última geração, com cinta ajustável que se adapta melhor no corpo do seu cão. Maior conforto e máxima higiene. Com tecido suave e revestimento com toque macio que proporciona mais conforto para o seu cão. Sistema abre e fecha com fitas adesivas com tecnologia estilo velcro. Não sai a cola e não gruda no pelo. Fraldas Super Secão tem super absorção, camada dupla e extragel que garantem mais horas de proteção. Medidas aproximadas Tamanho P: Circunferência da Barriga: de 30 a 46 cm Tamanho M: Circunferência da Barriga: de 46 a 60 cm Tamanho G: Circunferência da Barriga: de 60 a 80 cm Modo de usar - Abra a fralda e, com as fitas adesivas por baixo, passe a cauda pela abertura especial; - Adesive de um lado e passe a fralda pela barriga do animal, certificando-se de que ela esteja confortável - Com ajuda da fita em velcro, feche a fralda com um pouco de pressão sem apertar a barriga da sua cadela. IMPORTANTE: a fralda é funcional apenas para xixi, e a abertura para a cauda tem que permitir que o animal faça as fezes normalmente. Composição Celulose, polietileno, polipropileno, papel, polímeros superabsorventes, fita adesiva.', 42.99, 42.99, NULL, 'Pets > Litter & Toilet > Diapers', 'https://cf.shopee.com.br/file/99f038956488d3cfd0eb0c3d798f8783', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F398944029%2F13246294698', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697579774', 'Kit 2 Esmalte Risqué Cor Granulado Rosé Glitter com 8ml', 'ESMALTE RISQUÉ COR GRANULADO ROSÈ Nessa edição nada é o que parece. As cores dos esmaltes se transformam nas unhas e refletem novos tons com a luz. Color Effect traz esmaltes inovadores com elemento Color Effect, que proporciona efeito flake e holográfico, além dos cinco novos esmaltes com glitters concentrados. São nove tonalidades desenvolvidas com glitters, pérolas e pigmentos especiais e exclusivos para deixas as unhas com visual encantador, misterioso e surpreendente.', 14.72, 14.72, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/sg-11134201-8259u-mqmc3k8h340e44', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F23697579774', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18398692669', 'Kit 3 Condicionador Dove Baby Hidratação Enriquecida Cabelos Claros com 200ml', 'CONDICIONADORDOVE BABY HIDRATAÇÃO ENRIQUECIDA CABELOS CLAROS Com Camomila. Ele vai além da suavidade, pois ajuda a repor a hidratação do couro cabeludo, enquanto condiciona suavemente os cachinhos do seu bebê. Deixa o cabelo claro macio, delicadamente perfumado e fácil de pentear. Modo de usar: Após lavar o cabelo com shampoo, aplique uma pequena quantidade do produto nas mãos, massageie o cabelo úmido. Enxágue.', 52.77, 52.77, NULL, 'Mom & Baby > Bath & Body Care > Hair Care & Body Wash', 'https://cf.shopee.com.br/file/sg-11134201-823oy-mok0yzwot5an35', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F18398692669', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
