INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20897009152', 'Conduite Térmico Fire Sleeve Anti-Chama 15mm x 1m - Cód.6832', 'O Conduite Térmico Anti-Chama Asllan oferece a melhor proteção para o calor intenso do cofre do motor, sendo perfeito para proteger mangueiras de óleo e combustível além de chicotes elétricos e dutos de ar condicionado. O Conduite Anti-Chama é composto de duas camadas, senso a camada externa 100% silicone, que isola a temperatura e a camada interna de fibra de vidro que protege contra chamas. O conduite pode operar em temperatura continua de 260°C e suportando picos de até 1100°C. Dados Técnicos: Diâmetro Interno: 15mm Comprimento: 1 Metro Cor: Preto Material Externo: Silicone Material Interno: Fibra de Vidro Origem: Brasil Temperatura Máxima: 1100ºC Temperatura de Trabalho: 260ºC', 77.37, 77.37, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Electrical System', 'https://cf.shopee.com.br/file/sg-11134201-7rdy4-mcqomyv7zc587c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F634548170%2F20897009152', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
