INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19998844165', 'Pote Plástico Retangular Hermético Açaí 2,4L Flor Sanremo', 'O Pote Plástico Retangular Hermético Açaí 2,4L Flor Sanremo conta com design moderno, borracha de vedação integrada na tampa e válvula em forma de flor que libera a saída do vapor: quando aberta, permite que o pote vá tampado ao micro-ondas. É mais estilo para a sua cozinha e funcionalidade para a rotina do seu dia a dia. - Vai no micro tampado, no freezer e na máquina de lavar. - Tampa com vedação em borracha e válvula para saída do vapor. - Possui fechamento hermético: não vaza nada. - Transparente e com linhas de graduação que indicam as quantidades do conteúdo. - Livre de BPA: não prejudica a saúde da sua família. - Alças para transporte. Medidas: 8 x 17,1 x 28 cm (A x L x C)', 32.9, 32.9, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/sg-11134201-7reqg-m8xikoc2nbfm90', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F816806234%2F19998844165', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
