INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23293861607', 'Kit 3 Adesivos Saveiro Robust Emblema Preto Modelo Original', 'Adesivo Genérico._x000D_ Kit 3 Adesivos Saveiro Robust Emblema Preto_x000D_ Características:1 Par de Adesivos Laterais / Fabricado em Vinil Transparente / Dimensões: 22,9 x 2,9 cm_x000D_ 1 Faixa Traseira / Fabricado em Vinil Transparente / Dimensões: 81,1 x 4,7 cm_x000D_ _x000D_ Observações:_x000D_ Material autocolante._x000D_ Resistente à chuva e raios UV._x000D_ Embalagem segura para o transporte._x000D_ Vinil importado._x000D_ _x000D_ Instruções Para Aplicação:_x000D_ 1 - Limpe e remova qualquer impureza na área de aplicação do produto._x000D_ 2 - Limpe as mãos e remova o protetor do liner._x000D_ Procure ter o mínimo de contato com a face adesiva._x000D_ 3 - Centralize o produto no local da aplicação. Após esse posicionamento,_x000D_ pressione o produto gradativamente, sempre do centro para as bordas._x000D_ Procure retirar todas as bolhas._x000D_ 4 - Após finalizar a instalação, não tente retirar a peça para reposicioná-la,_x000D_ pois isso danificará o produto._x000D_ _x000D_ OBS: Para limpeza e conservação do produto, utilize apenas água e sabão neutro e/ou automotivo._x000D_ Recomendamos que a aplicação seja feita por um profissional._x000D_ _x000D_ Garantia de 1 ano.', 40.9, 37.21, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Tuning', 'https://cf.shopee.com.br/file/sg-11134201-7reqo-m80y4m4uld3r4f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1466989517%2F23293861607', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58210454052', 'Mocassim Feminino Dakota Napa Tratorado Verniz Preto', 'O Mocassim Feminino Dakota Napa Tratorado Verniz Preto é uma escolha certeira para quem busca conforto e elegância na rotina. Com visual clássico repaginado por detalhes modernos, o modelo entrega praticidade para compor produções do trabalho aos momentos casuais com muito mais estilo. Confeccionado em material sintético, o calçado apresenta acabamento envernizado que valoriza o visual com um toque refinado. O detalhe metalizado na parte superior do cabedal acrescenta destaque na medida certa, enquanto o bico redondo reforça a proposta confortável e atemporal do modelo. O forro em tecido com espuma favorece uma sensação mais agradável no uso, e a palmilha fixa contribui para um ajuste firme ao pé. A sola em PVC, em formato anabelado e tratorado, oferece apoio estável e presença marcante para acompanhar o dia a dia com segurança. O Mocassim Dakota combina facilmente com calças de alfaiataria, saias midi e vestidos, criando looks versáteis e sofisticados. Uma opção pensada para mulheres que desejam unir bem-estar, praticidade e um visual atual em cada passo. As Lojas Radan contam com 10 lojas físicas no Rio Grande do Sul, oferecendo esta e uma grande variedade de produtos e marcas de calçados e vestuário feminino, masculino, infantil e esportivo. Compre online com entrega rápida para todo o Brasil ou em uma de nossas lojas físicas, aproveitando nossa experiência e adquirindo produtos de qualidade. Aproveite! Produto de autenticidade garantida vendido pelas Lojas Radan. A cor do produto nas fotos pode sofrer alteração em decorrência do uso do flash ou da configuração do seu monitor. Características: Nome do produto: Mocassim Feminino Dakota Napa Tratorado Verniz Preto Código: D2631-0004 Indicado: Dia a dia Tipo de sapato: Mocassim Material: Napa Material interno: Tecido com espuma Palmilha: Espuma (Fixa) Solado: PVC Dimensões aproximadas: Altura do salto: 5 cm Diferencial: Acabamento envernizado e detalhe metalizado no cabedal Dimensões aproximadas: Tamanho: 33 - 21.8 até 22,3 cm Tamanho: 34 - 22.4 até 23 cm Tamanho: 35 - 23.1 até 23.6 cm Tamanho: 36 - 23,7 até 24.3 cm Tamanho: 37 - 24.4 até 25.0 cm Tamanho: 38 - 25.1 até 25.6 cm Tamanho: 39 - 25.7 até 26.3cm Tamanho: 40 - 26.4 até 27.0 cm Peso do produto: 860g Produto Original: Autenticidade garantida pelas Lojas Radan', 269.89, 269.89, NULL, 'Women Shoes > Flats > Loafers & Boat Shoes', 'https://cf.shopee.com.br/file/sg-11134201-82592-mqyyuxts0e865e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1577790116%2F58210454052', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23893359275', 'Kit Adesivos Coluna Superior Jeep Renegade Preto Decorativo', 'Adesivo Genérico._x000D_ As faixas decorativas além de determinar, em muitos casos, o modelo do veículo, também personalizam o seu carro e protegem a pintura. Os adesivos são produzidas em vinil automotivo autocolante importado, dispensando a utilização de produtos para a fixação. _x000D_ Kit Adesivos Coluna Superior Jeep Renegade Preto DecorativoCARACTERÍSTICAS:2 Adesivos Teto Jeep / Fabricado em Vinil / Dimensões: 175 x 16,3 cmQuantidade: 1 Jogo de Adesivos Jeep Observações:Material autocolante.Resistente à chuva e raios UV.Embalagem segura para o transporte.Vinil importado.Instruções Para Aplicação:1 - Limpe e remova qualquer impureza na área de aplicação do produto.2 - Limpe as mãos e remova o protetor do liner. Procure ter o mínimo de contato com a face adesiva.3 - Centralize o produto no local da aplicação. Após esse posicionamento,pressione o produto gradativamente, sempre do centro para as bordas.Procure retirar todas as bolhas.4 - Após finalizar a instalação, não tente retirar a peça para reposicioná-la,pois isso danificará o produto.OBS: Para limpeza e conservação do produto, utilize apenas água e sabão neutro e/ou automotivo.Recomendamos que a aplicação seja feita por um profissional._x000D_ Garantia de 1 ano.', 56.38, 53.0, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Tuning', 'https://cf.shopee.com.br/file/sg-11134201-7reoi-m83lxan2eai18a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1466989517%2F23893359275', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
