INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28827069941', 'Lança Confetes Metalizado 30cm e 60cm Dourado Prata Colorido Rosa Azul Festas Reveillon Aniversarios', 'O lança confetes é um dispositivo festivo projetado para criar um efeito espetacular de confetes coloridos durante celebrações. Geralmente feita de tubo de plástico ou papelão, a lança é compacta e fácil de manusear. Ao ser pressionada ou ativada, ela dispara uma chuva de confetes multicoloridos no ar, criando um visual vibrante e animado. A lança pode ser usada em casamentos, aniversários, festivais, ou qualquer evento onde se deseja adicionar um toque de diversão e surpresa. As cores dos confetes podem variar, e eles podem ser feitos de papel metálico ou papel normal, proporcionando diferentes efeitos dependendo do tipo de evento. Modelos: MIX COLORIDOS DOLAR CORAÇÃO ESTRELAS', 49.9, 17.01, NULL, 'Home & Living > Party Supplies > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6mmou1gohtz08', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436723291%2F28827069941', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
