INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22397702001', 'Aéreo Ripado Nogal com Prateleiras e Tubo Ouro Velho Carraro', 'Se você busca por qualidade e elegância na sua cozinha, o Aéreo Ripado Nogal com Prateleiras e Tubo Ouro Velho da marca Carraro é a escolha perfeita para você. Com design moderno e funcional, este móvel irá transformar o ambiente, proporcionando praticidade e organização. Atributos do Produto: Marca: Carraro Modelo: 2606 Material: MDP Cor: Cinza Altura do Produto: 80 cm Largura do Produto: 80 cm Profundidade do Produto: 30 cm Peso do Produto: 14.6 kg Produto precisa de Montagem?: Sim Descrição Detalhada: O Aéreo Ripado Nogal com Prateleiras e Tubo Ouro Velho Carraro possui uma estrutura resistente em MDP, garantindo durabilidade e segurança. Sua cor cinza combina facilmente com diversos estilos de decoração, enquanto as prateleiras oferecem espaço para organizar utensílios e objetos de forma prática. Com dimensões de 80 cm de altura, 80 cm de largura e 30 cm de profundidade, este aéreo é compacto e espaçoso ao mesmo tempo, ideal para otimizar o espaço na sua cozinha. Além disso, o produto é de fácil montagem e acompanha instruções para cuidados simples, como limpeza com pano seco. Não perca tempo e leve para casa este móvel de qualidade da marca Carraro. Renove sua cozinha com praticidade e estilo. Aproveite agora mesmo!', 419.99, 357.87, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7rdxf-lygu4wclif8q13', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F952014476%2F22397702001', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
