INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40419445785', 'Caixa 12un Barra Enjoy 42G Proteína Whey Pistache', 'A Barra de Proteína Enjoy Whey Pistache é feita com ingredientes selecionados para proporcionar um sabor singular e delicioso. O pistache, com seu gosto marcante e levemente adocicado, faz dessa barra uma escolha perfeita para quem busca algo diferente e saboroso. A Enjoy Snacks apresenta uma nova forma de se deliciar com as Barras de Proteína ENJOY WHEY. Desenvolvidas para proporcionar a funcionalidade da proteína com sabores surpreendentes, essas barras são uma ótima opção para quem busca um aporte de proteína no dia a dia, através de uma alimentação saudável e saborosa. Disponíveis em quatro versões deliciosas, cada barra contém 30% de proteína (12g por barra), zero açúcar, e são sem glúten. A Barra de Proteína ENJOY Whey é a escolha perfeita para quem deseja combinar saúde e sabor em um só produto. – 4 sabores disponíveis – Sabor incomparável – Feita com castanhas – Não contém glúten – 30% de proteína (12g por barra) – Zero adição de açúcar – Com colágeno Dicas de consumo: Pré ou pós-treino, lanches intermediários, experimente aquecer por 15 segundos no micro-ondas Ingredientes Blend proteico (proteína de soro do leite concentrada, colágeno hidrolisado, proteína de soja isolada, proteína de soro do leite isolada e caseinato de cálcio), cobertura sabor chocolate branco zero adição de açúcar, creme ganache zero adição de açúcar proteico sabor pistache, gordura vegetal de palma, sal refinado, estabilizantes xarope de maltitol, goma arábica e carbonato de cálcio, umectante glicerol, emulsificante lecitina, aromatizantes, conservantes sorbato de potássio e benzoato de sódio e antioxidante extrato de alecrim. ALÉRGICOS: CONTÉM DERIVADOS DE LEITE E DE SOJA. PODE CONTER AVEIA, OVOS, PEIXES, AMENDOIM, AMÊNDOA, AVELÃS, CASTANHA-DE-CAJU, CASTANHA-DO-PARÁ, NOZES, PECÃS E PISTACHES. CONTÉM LACTOSE. NÃO CONTÉM GLÚTEN.', 134.32, 90.32, NULL, 'Food & Beverages > Breakfast Cereals & Spread > Breakfast Bar', 'https://cf.shopee.com.br/file/br-11134207-820lk-mq4t7ph83wn4a1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F590473480%2F40419445785', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
