INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594448186', 'VENTOSA DUPLA DE ALUMINIO, 1 PC // MTX', 'Ventosa Dupla de Alumínio MTX 8752059 – Levantamento e Transporte Seguro de Materiais Lisos A Ventosa Dupla de Alumínio MTX 8752059 é ideal para levantar, transportar e instalar vidros, espelhos, azulejos, chapas de metal e outros materiais lisos de forma segura e eficiente. Equipado com duas ventosas a vácuo, o dispositivo é fixado de forma cuidadosa e firme na superfície com o auxílio de grampos, garantindo alto poder de aderência. Com uma capacidade de carga de até 80 kg, o elevador de vidro é perfeito para trabalhos prolongados sem comprometer a segurança. Será especialmente útil em projetos de construção, reformas e até mesmo em trabalhos domésticos, oferecendo praticidade e segurança na movimentação de materiais pesados e delicados. Vantagens: Durabilidade: O corpo da ventosa é fabricado em liga de alumínio, garantindo resistência e longa vida útil. Longevidade: A ventosa é resistente à corrosão, proporcionando um desempenho constante mesmo em ambientes desafiadores. Ergonomia: A alça conveniente permite um transporte fácil e seguro da carga, melhorando o controle durante o manuseio. A Ventosa Dupla de Alumínio MTX 8752059 é uma ferramenta confiável e robusta, essencial para quem trabalha com materiais pesados e frágeis, garantindo um transporte mais seguro e eficaz, seja em construções, reformas ou até mesmo em tarefas domésticas.', 82.83, 82.83, NULL, 'Home & Living > Tools & Home Improvement > Others', 'https://cf.shopee.com.br/file/sg-11134201-824gc-mf9p10h70op618', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1577891436%2F23594448186', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22598586569', 'Protetor para Porta 2 em 1 - Safety 1st', 'Evita que a criança prenda o dedo ou se tranque em algum ambiente. Feito em borracha, é compatível com portas de 3 a 4 cm de espessura. A curiosidade e o desenvolvimento rápido das crianças faz com que eles se movimentem bastante pela casa, que pode oferecer uma série de riscos aos pequenos se não estiver devidamente protegida. O protetor de porta evita que eles se machuquem pois impede que prendam o dedo nas portas. O protetor também impede que a porta tranque, evitando que a criança se assuste ao ficar trancada em um cômodo. Fácil e rápido de instalar, o protetor é feito em borracha e é compatível com portas de 3 a 4 cm de espessura, de qualquer material e que abram em arco. Evita machucados Evita que a criança se tranque em um cômodo Compatível com portas de 3 a 4 cm de espessura Fácil colocação Feito em borracha', 18.9, 18.9, NULL, 'Mom & Baby > Baby Safety > Bumpers, Rails & Guards', 'https://cf.shopee.com.br/file/sg-11134201-7ravl-masl7mujvyara0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1207408200%2F22598586569', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
