INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22237896465', 'Volante Esportiva Gti Grafite Vw Kombi variant brasila bugre buggy fusca quadrado Parati', '"ESPECIFICAÇÃO TÉCNICA • Diâmetro de 370mm; • Profundidade de 120mm. COMPATIBILIDADES: • Volkswagen Gol Quadrado (G1) Até 1995 • Volkswagen Parati Até 1998 • Volkswagen Saveiro Até 1997 • Volkswagen Santana Até 1995 • Volkswagen Fusca 1977 À 1996 • Volkswagen Brasília 1977 À 1982 • Volkswagen Buggy (Estria Fina) • Volkswagen Bugre (Estria Fina) • Volkswagen Kombi 1950 À 1982 COMPATIBILIDADES: • Volkswagen Fusca 1938 À 1976 • Volkswagen Brasília 1973 À 1976 • Volkswagen Variant 1969 À 1976 • Volkswagen Puma 1964 À 1997 • Volkswagen Buggy (Estria Grossa) • Volskwagen Bugre (Estria Grossa) Caso não tenha encontrado o modelo do seu veículo neste anúncio, nos consulte. IMPORTANTE • Garantia de 3 Meses; • Somos FABRICANTES ESPECIALIZADOS no segmento automotivo, seguimos um processo rigoroso de fabricação e qualidade; • Entrega ágil e rápida após sua compra; • Enviamos todos os nossos volantes com CUBO ADAPTADOR; • Após a instalação, perde-se a função AIRBAG; • RECOMENDAMOS QUE A INSTALAÇÃO SEJA FEITA POR PROFISSIONAL ESPECIALIZADO. • Fabricamos volantes em POLIURETANO RESISTENTE; • Nossos volantes possuem similaridade ao original com acabamento texturizado e acionamento da buzina. Sua satisfação é nossa maior recompensa! Estamos à disposição e teremos o imenso prazer em atendê-lo!"', 212.49, 170.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Internal Parts', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lu85gi7jbw4g06', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F955071389%2F22237896465', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
