INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20199380770', 'Roldana plástica 6cm com parafuso 20kg - Vonder', 'Roldana Plástica 6cm Com Parafuso 20kg - Vonder Descubra a eficiência e praticidade da Roldana Plástica de 6cm da Vonder, uma marca reconhecida pela qualidade e durabilidade de seus produtos. Ideal para uso doméstico e profissional, esta roldana é perfeita para elevação de cargas com auxílio de corda, suportando até 20 kg. Seja em sistemas de polias ou em atividades específicas, a roldana Vonder se destaca pela sua versatilidade e facilidade de instalação. Fabricada em plástico resistente, ela é leve e durável, garantindo um desempenho confiável em diversas aplicações. Com a inclusão de um parafuso para instalação, você terá tudo o que precisa para começar a usar imediatamente. ESPECIFICAÇÕES TÉCNICAS: - Marca: Vonder - Código universal de produto: 7893946364861 - Capacidade máxima de peso: 20 kg - Modelo: 32.33.000.600 - Material da roldana: Plástico - Tipo da roldana: Com parafuso - Diâmetro da roldana: 6,0 cm FUNÇÕES E CARACTERÍSTICAS: - Capacidade máxima de peso de 20 kg - Inclui parafuso para instalação - Ideal para uso doméstico e profissional - Leve e fácil de instalar - Versátil para diferentes aplicações INSTRUÇÕES DE USO: 1. Verifique se a roldana está em boas condições antes de usar. 2. Instale a roldana em uma superfície estável utilizando o parafuso incluso. 3. Passe a corda pelo canal da roldana, garantindo que esteja bem posicionada. 4. Evite exceder a capacidade máxima de 20 kg para garantir a segurança. 5. Realize manutenções periódicas para prolongar a vida útil do produto. ITENS INCLUSOS: - 1 Roldana - 1 Parafuso para instalação', 18.9, 18.9, NULL, 'Home & Living > Tools & Home Improvement > Others', 'https://cf.shopee.com.br/file/sg-11134201-82611-ml5hxguqld6ob6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442555366%2F20199380770', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46103354130', 'Odorizador de Ambiente Glade Gotas Perfumadas Lembranças de Infância Frasco 120ml', 'Glade Gotas Perfumadas contém fragrâncias com óleos essenciais com um perfume intenso e agradável. Pode ser usado em diversas superfícies, diluído em água ou puro.', 18.75, 18.75, NULL, 'Home & Living > Home Fragrance & Aromatherapy > Others', 'https://cf.shopee.com.br/file/sg-11134201-81zw9-mifx3zpvkhdtc5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F46103354130', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18197672128', 'Kit 10 Bacias para Plantas Marrom de Polietileno 32x11cm', 'CONHEÇA NOSSOS PRODUTOS: Bacia de polietileno para plantas Cada planta tem suas características e necessidades específicas, e algumas delas preferem um espacinho menor, então dê a sua planta o espaço que ela gosta Os modelos chamados de bacias são perfeitos para plantas como rosa do deserto, suculentas, folhagens, diversos tipos de flores e até hortas! Além de tudo isso, nossas bacias ainda são: - Recicláveis - Leves - Texturizadas Com design pensado na planta e na estética dos ambientes! Marca: Alpe & Aritana.', 299.9, 299.9, NULL, 'Home & Living > Gardening > Pots & Planters', 'https://cf.shopee.com.br/file/sg-11134201-7rce1-lt2u2nve3doc62', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F306698991%2F18197672128', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21944907642', 'Jardineira para Plantas Floreira de Polietileno p/ Jardim Vertical', 'RENOVANDO O AMBIENTE! -------------- As Jardineiras, também chamadas de Floreiras, são usadas para dar mais vida ao paisagismo. Se você deseja colocá-las nas paredes, lugares estreitos, jardins verticais ou janelas, as mais finas são as ideais. Na linha Havana, há 2 tamanhos de Jardineiras: 37 cm x 15 cm x 10 cm (comprimento x largura x altura) e 80 cm x 15 cm x 10 cm. Além disso, há 5 opções de cores: azul, bege, cinza, marrom e preto. -------------- INFORMAÇÕES DO PRODUTO: - Material: polietileno - Resistente aos diferentes climas', 49.9, 35.99, NULL, 'Home & Living > Gardening > Pots & Planters', 'https://cf.shopee.com.br/file/f1bdc1936b23848207efe571255198e7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F306698991%2F21944907642', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23692839229', 'Kit Teclado Musical Kobe KB-300 5/8 61 Teclas com Sensibilidade ao Toque com Pedal Sustain e Suporte', 'Kit Teclado Musical Digital Kobe KB-300 5/8 61 Teclas com Sensibilidade ao Toque com Pedal Sustain e Suporte Conteúdo do kit: 01 Teclado Kobe Kb300 01 Suporte em X 01 Pedal Sustain 01 Estante Partitura 01 Fonte Bivolt O Teclado musical KB-300 é uma excelente escolha para o público iniciante que busca um teclado com SENSIBILIDADE nas teclas e PEDAL SUSTAIN, recursos que são indispensáveis para o para os estudos e o desenvolvimento das técnicas e criatividade musical. A sensibilidade das teclas permite controlar com precisão a dinâmica do som das teclas, variando o volume, intensidade e velocidade das notas tocadas, isso proporciona um maior realismo nas canções. Além disso, o KB-300 possui uma grande variedade de timbres, incluindo piano, órgão, cordas, metais, sintetizadores. Também possui uma variedade de ritmos proporcionando uma gama de possibilidades musicais. Em resumo, o teclado musical KB-300 da Kobe Music é uma ótima opção para quem procura um instrumento de qualidade e versátil, sem dúvidas tudo que você precisa para iniciar seus estudos com o MELHOR custo-benefício do mercado. Confira todas as especificações técnicas mais abaixo: Especificações: Marca: KOBE MUSIC Cor: Vermelho Modelo: KB-300 61 Teclas 5/8 estilo piano com 2.2cm de largura Teclas com sensibilidade ao toque (resposta ao toque) Entrada para Pedal Sustain p2 (pedal incluso) 200 Timbres 200 Ritmos 80 Musicas Demo 48 Polifonias Display em LCD e painel de fácil acesso Possui 2 alto-falantes de 3W *Não possui memória FUNÇÕES: Sensitive (habilitar ou desabilitar sensibilidade nas teclas) Metrônomo, função aprendizagem (follow), transpose (manipular o tom dos timbres), Sustain (sustentação de notas), gravação e programação de acompanhamentos de percussão, função "Split" (Dual keyboard), que permitem dividir o teclado em duas partes com dois timbres diferentes. CONEXÕES: Entrada para Pedal Sustain p2. Entrada de áudio p2: Você pode conectar um dispositivo e reproduzir o som nos alto-falantes. Entrada para microfone p2: Você pode conectar um microfone para cantar e reproduzir o som nos alto-falantes do teclado. Saída para fone de ouvido: Ideal para fazer seus estudos sem incomodar ninguém, pois o som sairá apenas no fone de ouvido. Essa saída também serve para conectar o teclado em uma mesa de som, caixa de som, placa de gravação, entrada de som do seu computador, etc. Entrada USB: Você pode conectar um pendrive e reproduzir músicas ou acompanhamentos em MP3 enquanto toca ou simplesmente escutar suas músicas. Entrada MIDI: NÃO possui Acompanha: Fonte bivolt 5V 1A Pedal Sustain Suporte para partitura Adesivos para teclas Manual em português. Medidas: Peso 3.7kg Tamanho: 92 x 26 x 7.2 centímetros Alimentação: fonte bivolt 5V 1A, ou também funciona com 4 pilhas tamanho AA 1.5v. Garantia de fábrica: 6 meses', 699.9, 699.9, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Keyboards & Pianos', 'https://cf.shopee.com.br/file/sg-11134201-7rcfa-lrht59snccuce8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F569545665%2F23692839229', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23996962994', 'Kit 8 Roupas Íntima Bigfral Pants Derma Plus G/EX com 16un cada', 'Kit Contém: 8 Pacotes Roupas Íntima Bigfral Pants Derma Plus G/EX com 16un cada A nova roupa íntima Bigfral Derma Plus possui sistema de proteção total da pele, é dermatologicamente testada, absorve até 2x mais para que a pele não fique úmida deixando-a mais seca e protegida e possui toque fresco e macio. Indicada para homens e mulheres com incontinência urinária moderada a intensa. Veste como sua roupa íntima habitual e garante todo conforto e segurança para manter sua rotina.', 644.49, 492.49, NULL, 'Health > Personal Care > Adult Diapers & Incontinence', 'https://cf.shopee.com.br/file/sg-11134201-7rbl2-lm65738b49577e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F23996962994', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23494732831', 'Cotonetes Hastes Flexíveis', 'Cotonetes Hastes Flexíveis são ideais para a higiene pessoal de toda a família. Perfeitos para limpar delicadamente a parte externa da orelha (sem atingir o canal do ouvido), as dobrinhas do pescoço e pernas do bebê, além de serem recomendados para aplicar e remover maquiagem. Feitos com algodão 100% puro e hastes plásticas flexíveis, proporcionam maior suavidade, conforto e segurança para o seu dia a dia.', 9.79, 9.79, NULL, 'Health > Personal Care > Ear Care', 'https://cf.shopee.com.br/file/sg-11134201-8258x-mqnektutqcr3cb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676552986%2F23494732831', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19099907835', 'Camiseta Apex Dry New Lupus Sem Costura Alpha Co', 'Que tal renovar seu visual de treino de uma só vez com a Camiseta Apex Dry New Lupus Sem Costura Alpha? Perfeito para quem treina várias vezes na semana e quer ter sempre uma peça limpa, leve e pronta para usar. Produzidas com 68% Poliéster + 32% Poliamida de alta qualidade, essas camisetas tem o toque macio, caimento confortável e elasticidade na medida certa para acompanhar qualquer movimento, sem prender ou incomodar. O tecido dry fit ajuda a manter o corpo seco: ele afasta o suor da pele e seca rápido, ideal para academia, corrida, funcional ou treinos ao ar livre. Assim, você treina com mais conforto e evita aquela sensação de camiseta pesada e encharcada. Benefícios do produto: - Camiseta modelo APEX: design moderno e funcional. - Tecido dry fit: ajuda a manter o corpo seco e confortável. - Material de alta performance: leveza, resistência e liberdade de movimento. - Ideal para academia, beach tennis, ciclismo, futebol, hiit, hyrox, musculação, spinning, treino ao ar livre, treino funcional, treino intenso, crossfit e corrida. - Fácil de lavar, seca rápido e quase não amassa. Se você quer treinar mais, repetir menos roupa e ainda ter qualidade, essa camiseta foi feita pra você.', 99.9, 99.9, NULL, 'Men Clothes > Tops > T-Shirts', 'https://cf.shopee.com.br/file/sg-11134201-82268-mhjdden5xpfqd1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1337417367%2F19099907835', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12009880029', 'Máscara de Tratamento Pantene Pro-V Nutrição 270ml', 'LONG DESCRIPTION:Precisa de uma solução para cabelos com frizz e pontas duplas? A Máscara Capilar Nutrição Pantene é para você! Complete o seu cronograma capilar com a nova máscara de nutrição Pantene. A nova fórmula Nutri-Pérolas Pro-V é uma infusão reparadora contra o dano*; contém Pérolas Pro-Vitaminas solúveis e Óleo de Amêndoas, para fios até 100% mais fortes** e preenchidos. As Pérolas Pro-V são partículas que liberam milhões de lipídios que se dissolvem no creme, uma tecnologia exclusiva Pantene. Sinta a diferença. *Dano ao brilho e a suavidade.**vs shampoo sem ingredientes condicionadores depois de 4 usos. SHORT DESCRIPTION:Precisa de uma solução para cabelos com frizz e pontas duplas? A Máscara Capilar Nutrição Pantene é para você! Complete o seu cronograma capilar com a nova máscara de nutrição Pantene. A nova fórmula Nutri-Pérolas Pro-V é uma infusão reparadora contra o dano*; contém Pérolas Pro-Vitaminas solúveis e Óleo de Amêndoas, para fios até 100% mais fortes** e preenchidos. *Dano ao brilho e a suavidade.**vs shampoo sem ingredientes condicionadores depois de 4 usos. • Contém Pérolas Pro-Vitaminas solúveis e Óleo de Amêndoas • Para fios até 100% mais fortes* e preenchidos • Ideal para cabelos com frizz e pontas duplas • As Pérolas Pro-Vitaminas são partículas que liberam milhões de lipídios que se dissolvem no creme, uma tecnologia exclusiva Pantene • Ideal para o seu cronograma capilar • *vs shampoo sem ingredientes condicionadores', 34.89, 33.19, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7qvf6-lhyy2d9dyrpp70', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F12009880029', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22597751352', 'Inseticida Aerossol Raid Multi-insetos Base Água Leve Mais Pague Menos 420ml', 'Raid Multi Insetos Base Água possui a eficiência do inseticida com fórmula à base de água que mata a maioria dos insetos comuns, sem deixar cheiro. Mantenha sua casa livre de insetos voadores e rasteiros com Raid.', 30.59, 30.59, NULL, 'Home & Living > Home Care Supplies > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rcca-ltvf9mr29lj03b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F22597751352', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22192192285', 'Kit Trivitt Itallian Shampoo 1l Mascara 1kg Fluido Reparador', 'O Kit Trivitt Itallian é a escolha perfeita para quem busca um cuidado completo e intensivo para cabelos quimicamente tratados e danificados. Composto por quatro produtos essenciais, este conjunto oferece tudo o que você precisa para restaurar, proteger e manter a saúde dos seus fios. O Shampoo Pós-Química Uso Frequente Trivitt 1L é especialmente formulado para cabelos que passaram por processos químicos. Com uma combinação poderosa de Proteína do Trigo, Queratina Vegetal e Óleo de Camelina Dourada, este shampoo limpa suavemente enquanto restaura a vitalidade e o brilho dos cabelos. Ele protege os fios contra o ressecamento e mantém a maleabilidade, sendo ideal para uso diário. A Hidratação Intensiva Trivitt 1KG é indicada para todos os tipos de cabelo, oferecendo uma reparação profunda e hidratação duradoura. Com queratina hidrolisada e óleo de Camelina Dourada, este tratamento penetra na fibra capilar, selando as cutículas e fortalecendo os fios contra a quebra. O resultado são cabelos mais brilhantes, resistentes e condicionados. O Fluído para Escova Trivitt 300ML é um aliado indispensável para quem utiliza secador. Este fluído facilita a escovação e oferece proteção térmica, além de acelerar a secagem dos fios. Com ativos como filtro solar e emulsão de silicone, ele protege os cabelos dos danos solares e previne pontas duplas, mantendo a hidratação e proporcionando um brilho intenso e maciez. Por fim, o Reparador de Pontas Trivitt 30ML é ideal para finalizar o tratamento, garantindo que as pontas duplas sejam reparadas e os fios fiquem protegidos. Com um blend de silicones e filtro solar, ele forma uma película protetora que condiciona os cabelos, conferindo um toque sedoso e um brilho tridimensional sem deixar os fios pesados ou oleosos. Para aplicar, siga as instruções de uso de cada produto. O shampoo deve ser usado nos cabelos úmidos, seguido pela máscara de hidratação para um tratamento intensivo. O fluído deve ser aplicado antes da escova, enquanto o reparador de pontas é usado para finalizar, concentrando-se nas extremidades dos fios. Os benefícios deste kit incluem a restauração completa dos cabelos quimicamente tratados, proteção contra danos externos, e um acabamento de salão com brilho e maciez. Todos os produtos são para uso externo e devem ser mantidos fora do alcance de crianças, respeitando o prazo de validade de 36 meses para garantir a eficácia do tratamento.', 418.72, 364.29, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgpgxyese4udcd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F969993035%2F22192192285', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18498865826', 'Kit Home Care Matizante Com Hidratação Intensiva Trivitt Itallian', 'Kit Itallian Trivitt Matizante para Cabelos Loiros e com Mechas Shampoo + Condicionador + Máscara Descrição Trivitt Home Care Matizante com Hidratação Intensiva oferece hidratação intensa, maciez e resistência ao cabelo quimicamente tratado. Exclusivamente para manutenção dos cabelos loiros ou com mechas, restaura, nutre e neutraliza os tons amarelados e alaranjados causados pelo desgaste dos corantes. Proporciona brilho platinado desde a primeira aplicação. Contém: 01 Shampoo Matizante 01 Condicionador Matizante 01 Hidratação Intensiva Matizante Ativos: Blend de aminoácidos incorporados a uma matriz catiônica Queratina Biomimética: Reestruturação interna e externa com alta afinidade com a fibra capilar Agente de condicionamento altamente eficiente Quatérnio-87: Agente condicionante biodegradável Quatérnio-70: Agente desembaraçante Silicone com tecnologia avançada D-Pantenol ou Pró Vitamina B5: Agente condicionante Queratina: Os cabelos são constituídos principalmente por essa proteína, composta por uma sequência de 18 aminoácidos interligados por pontes de hidrogênio, dissulfeto (enxofre) e salinas. Como é hidrolisada, apresenta baixo peso molecular, o que facilita sua penetração através das cutículas. Deposita-se sobre as regiões que apresentam danos, restaurando os fios Reequilibra o teor de água e a distribuição de cargas elétricas da fibra capilar Após penetrar através das cutículas, mantém as mesmas seladas (pH adequado para o fechamento das escamas) Óleo de Camelina Dourada: Ingrediente de origem 100% vegetal, obtido da planta Camelina sativa. Fornece a proporção ideal de Ômegas 3 e 6 para restaurar o teor lipídico (oleosidade natural) da fibra capilar Combate o toque áspero dos cabelos ressecados e fragilizados Recupera a elasticidade e flexibilidade dos fios Complexo natural de Arroz, Soja e Extrato de Palma: Forte ação antioxidante Mantém a integridade das cutículas Complexo vegetal extraído da Lavanda, Alecrim e Violeta Disfarça a coloração amarelada dos fios com visual mais acinzentado Corantes para coloração progressiva do cabelo Promovem perfeita fixação sobre os fios Evitam o aparecimento de manchas irregulares Modo de Uso: Aplique o Shampoo Matizante no cabelo úmido e massageie os fios de forma suave. Enxágue e repita a operação. Aplique o Condicionador Matizante do comprimento às pontas. Deixe agir por alguns minutos e enxágue. Aplique a Hidratação Intensiva Matizante sobre os cabelos limpos e úmidos, do comprimento às pontas, massageando suavemente mecha por mecha. Após 5 minutos, enxágue e deixe secar naturalmente. Caso queira realizar escova com secador, aplique antes o Fluido para Escova Trivitt. Precauções: Mantenha fora do alcance de crianças Não usar em crianças Uso externo.', 153.64, 133.67, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lopriggqgqj99b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F969993035%2F18498865826', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18376627108', 'KIT HOME CARE TRIVITT COM HIDRATAÇÃO INTENSIVA', 'O Kit Home Care Hidratação da Itallian Trivitt é ideal para quem busca cuidados intensivos para cabelos quimicamente tratados. Este kit oferece hidratação profunda, maciez e resistência, sendo perfeito para reparar danos causados por processos químicos, protegendo contra frizz, ressecamento e pontas duplas. O kit é composto por três produtos essenciais: um Shampoo Pós-Química para uso frequente, um Condicionador Trivitt e uma Hidratação Intensiva. O Shampoo Pós-Química é especialmente formulado para cabelos que passaram por tratamentos químicos, proporcionando limpeza suave e preparando os fios para os próximos passos do cuidado capilar. O Condicionador Trivitt garante um condicionamento profundo, deixando os cabelos macios e fáceis de pentear. A Hidratação Intensiva é responsável por restaurar o brilho e a vitalidade dos fios, oferecendo um tratamento intensivo para cabelos danificados. Entre os principais ativos do kit, destaca-se a Proteína do Trigo, que adere facilmente à fibra capilar, conferindo brilho e maleabilidade. A Queratina Vegetal, com seu baixo peso molecular, penetra nas cutículas dos fios, restaurando e selando as escamas, enquanto o Óleo de Camelina Dourada, rico em Ômegas 3 e 6, recupera a elasticidade e a flexibilidade dos cabelos. A Trealose, um açúcar vegetal, proporciona hidratação profunda e proteção contra agentes externos. Para usar, aplique o Shampoo nos cabelos úmidos, massageando suavemente e enxaguando em seguida. Repita a operação se necessário. Em seguida, aplique o Condicionador do comprimento às pontas, deixe agir por alguns minutos e enxágue. Para uma hidratação mais intensa, substitua o condicionador pela Hidratação Intensiva, aplicando-a nos cabelos limpos e úmidos, massageando mecha por mecha. Após cinco minutos, enxágue e deixe secar naturalmente ou finalize como desejar. Os benefícios deste kit incluem cabelos mais resistentes à quebra, com brilho e maciez intensos, além de proteção contra o frizz e ressecamento. É um tratamento completo que reequilibra o teor de água e a distribuição de cargas elétricas da fibra capilar, proporcionando um cuidado profissional no conforto de sua casa.', 153.64, 133.67, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ll9p5c2na7246f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F969993035%2F18376627108', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50350737355', 'Almofada de Pescoço Para Viajem Bagaggio Viscoelástica Original', 'A almofada para pescoço é ideal para viagens longas e garante seu maior conforto e praticidade para onde você quiser levar. Garanta já a sua!', 99.9, 54.9, NULL, 'Travel & Luggage > Travel Accessories > Travel Pillows & Eye Covers', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgm51f72bcw496', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1178125772%2F50350737355', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12491841907', 'Base De Disco Lixa Velcro 125x M14 Esmerilhadeira Furradeira', 'Suporte Politriz Lixadeira Furadeira Boina Velcro 125mm O que você irá receber: SUPORTE DE BOINA COM VELCRO - 125 mm - 01 UNIDADE. Benefícios: - Utilização com Boina e com Lixa com Velcro. - Utilização em Lixadeiras ou Furadeiras. - Agilidade no Trabalho. - Qualidade no Acabamento. - Alta flexibilidade e alto rendimento no lixamento. Aplicação; - Lataria. - Metais. - Madeiras. - Facas. - Outros. Especificações: - Suporte de Boina/Lixa com Velcro. - Diamentro: 125 mm. - Rosca M14 - Haste com 8mm. - Serve para Lixadeiras, politrizes e Esmerilhadeiras. - Pode ser Usado para Lixar e Polir. - Marca: Tssaper - Modelo: TSAD125 Itens inclusos: - 01 Base disco de lixa - 01 Adaptador M14 para Esmerilhadeira e Furadeira Garantia: 3 meses, conforme Lei 8.078/1990 Art. 26 do CDC.', 28.92, 24.59, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/a62738a629a99a42d63c508321c4204f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F296114884%2F12491841907', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13808974149', 'Limpador Diluível Ajax Fresh 1l', 'Furação de Limpeza Profunda e Sem Agressão - Brilho intenso sem resíduos Ajax Fresh Limpeza Pesada é indicado para limpeza geral de pisos, azulejos, vidros, cerâmicas e superfícies laváveis. Proporciona uma limpeza profunda sem agredir as superfícies e deixa sua casa com um agradável cheirinho de limpeza. Tem um rendimento incrível pois é diluível em água. Quer saber como usar? É fácil: Dilua 2 tampas e meia do produto em 5 litros de água. Umedeça o pano e passe sobre as superfícies a serem limpas. Se a limpeza é pesada, pode-se utilizar puro com um pano úmido na remoção de manchas e sujeiras mais difíceis. 1L – Rende até 60 litros.', 25.79, 25.79, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-7rbl6-lopq3tu7m7uu8f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F13808974149', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
