INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21999382039', 'Boina Laranja Refino Médio 6 Polegadas Hyper Colmeia Kers', 'Boina de Espuma Laranja Média Refino Hyper 6 polegadas Kers A tecnologia das boinas Hyper também reduz o calor superficial durante o polimento. O padrão de estilo hexagonal ou colmeia na superfície da boina distribui uniformemente o ar com fluxo livre sobre a boina , proporcionando um polimento mais seguro, suave e frio.', 89.9, 76.48, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Pads', 'https://cf.shopee.com.br/file/sg-11134201-7rdw2-lzrsh84p2rl82d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1228411998%2F21999382039', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598374084', 'Kit Limpa Couro 500ml Hidrata Couro 500ml Expert Proficional', 'Descrição: Protectant Leather - Hidrata CouroO PROTECTANT LEATHER hidratada as partes compostas por couro natural do interior do carro, trazendo vitalidade e brilho, protege contra o desgaste diário, deixando um aspecto limpo e renovado.Características- Hidratação do couro- Proteção do couro- Limpeza e RenovaçãoComo Aplicar?- Antes de iniciar a aplicação deste produto, certifique-se que a superfície não esteja quente e não aplique o produto com o veículo exposto ao sol. Aplicar sobre a superfície a ser limpa com o auxílio de um pano microfibra, espalhando o produto fazendo movimentos circulares. Utilizar outro lado do pano microfibra para fazer o acabamento.Dicas:- Antes de iniciar a aplicação deste produto, certifique-se que a superfície não esteja quente e não aplique o produto com o veículo exposto ao sol. Aplicar sobre a superfície a ser limpa com o auxílio de um pano microfibra, espalhando o produto fazendo movimentos circulares. Utilizar outro lado do pano microfibra para fazer o acabamento.--- Descrição: Blast Leather - Limpa CouroO BLAST LEATHER oferece uma limpeza profunda para todas as partes de couro, sejam elas naturais ou sintéticas. Sua fórmula, desenvolvida com alto rigor técnico, proporciona uma limpeza eficaz sem agredir ou manchar o couro, mantendo o aspecto original dos bancos e superfícies de couro do veículo.Características:- Limpeza Profunda- Não agride e não macha o couro do seu carro- Revitaliza as superfícies de couro- Hidrata o couroComo Aplicar?- Antes de iniciar a aplicação deste produto, certifique-se que a superfície não esteja quente e não aplique o produto com o veículo exposto ao sol. Aplicar sobre a superfície a ser limpa com o auxílio de um pano microfibra, espalhando o produto fazendo movimentos circulares. Utilizar outro lado do pano microfibra para fazer o acabamento.Dicas:- Antes de iniciar a aplicação deste produto, certifique-se que a superfície não esteja quente e não aplique o produto com o veículo exposto ao sol. Aplicar sobre a superfície a ser limpa com o auxílio de um pano microfibra, espalhando o produto fazendo movimentos circulares. Utilizar outro lado do pano microfibra para fazer o acabamento.Conteúdo da Embalagem- 01 Protectant Leather - Hidrata Couro- 01 Blast Leather - Limpa Couro', 85.9, 70.74, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Treatments', 'https://cf.shopee.com.br/file/sg-11134201-7repu-m86mte3vah8gdf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1228411998%2F23598374084', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
