INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898067247', 'Manete Esportivo Freio Titan 150/ FAN 125/150 Disco C/ Regulagem - CB TWISTER', 'MANETE ESPORTIVO PARA CG 160 CG 150 FREIOS A DISCO / TWISTER CB250F / TWISTER 300F Aplicável apenas a motos com freio a disco dianteiro. - Material: Alumínio 6061-T6 Anodizado; - Processo de fabricação: Usinagem com máquina CNC para precisão; - Parafusos em aço inoxidável; - Modelo: Curto (14 cm); - 6 Regulagens; Medidas: Comprimento: 14,5cm Largura: 2,0 Altura; 2,0 Peso: 250g Atenção! Para assegurar o pleno funcionamento do produto e manter sua garantia válida, recomendamos enfaticamente que a instalação seja conduzida por um profissional habilitado. Isso não apenas preserva a garantia, mas também garante que o produto opere conforme projetado, oferecendo o máximo desempenho e durabilidade.', 189.9, 67.2, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcqsg3i01tma68', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1188055013%2F23898067247', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597010192', 'Capa Protetora de Colchão Solteiro Impermeável 100% Silencioso Malha Premium 78X188X36cm BF Colchões', 'A capa protetora impermeável de colchão é confeccionado com tecido de malha de alta tecnologia que não faz barulho ao se deitar e não esquenta, isso porque não é feito em plástico como outros produtos do mesmo tipo, deixando suas noites mais tranquilas e protegidas. Por ser impermeável, evita acidentes com líquidos durante a noite, facilita a limpeza e aumenta a durabilidade do seu colchão. Além disso, seu tecido especial possui toque delicado com sensação de extrema maciez. Pode ser lavado em máquina. Características da Protetor: Marca: BF Colchões Tecido Impermeável Tecido de Malha Belga Ultra Macia 100 silenciosa - Não faz ruídos Não esquenta Lavável à máquina Revestimento Inferior: 100% Poliuretano Revestimento Superior: 100% Poliéster Dimensões: Altura: 188 cm Largura: 78 cm Profundidade: 36 cm', 162.37, 129.0, NULL, 'Home & Living > Bedding > Mattress Protectors & Toppers', 'https://cf.shopee.com.br/file/br-11134201-7r98o-m1e4ictnhvpc39', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F412482669%2F23597010192', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
