INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18578307425', 'Batom Matte Rayssa Lipstick Longa Duração Ana Hickmann', 'Sinta-se poderosa e confiante com a linha de maquiagens de Ana Hickmann. Produtos para rosto, olhos, boca e acessórios como esponjas, curvex, pincéis profissionais e kits. Produtos de alta performance. Seja a protagonista do seu próprio beauty show! Batom matte de longa durabilidade e alta pigmentação. Fácil de aplicar, desliza bem sobre os lábios sem craquelar. Modo de uso: Aplique diretamente nos lábios. Ingredientes: Isononyl Isononanoate, Dimethicone/Phenyl Vinyl Dimethicone Crosspolymer, Diisostearyl Malate, Silica, Ceresin, Octyldodecanol, Microcrystalline Wax, Polyethylene, Glycine Soja Sterols, VP/Hexadecene Copolymer, Aloe Arborescens Leaf Extract, Sodium Ascorbate, Tocopherol, Parfum, Hexyl Cinnamal, Linalool, Butylphenyl Methylpropional, Citronellol, Hydroxyisohexyl 3-Cyclohexene Carboxaldehyde. May Contain (+/-): CI 77491 (Iron Oxide Red), Ci 77492 (Iron Oxide Yellow), CI 77499 (Iron Oxide Black), CI 77891 (Titanium Dioxide), CI 15850 (Pigment Red 57). * Produto Vegano *', 29.9, 29.9, NULL, 'Beauty > Makeup > Lips', 'https://cf.shopee.com.br/file/br-11134207-820m0-mosoadps5q8594', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F984347359%2F18578307425', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
