INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22997608140', 'Grelha Ralo Quadrada Inox Lorenzetti 15cm', 'SOBRE O PRODUTO A Grelha Ralo Quadrada Inox Lorenzetti de 15cm é a solução perfeita para unir funcionalidade e elegância em sua casa. Com um design moderno em aço inoxidável de alta qualidade, esta grelha não apenas oferece durabilidade excepcional, mas também adiciona um toque de estilo ao seu espaço. Seu tamanho compacto de 15cm a torna versátil para diversas aplicações, garantindo uma drenagem eficiente e fácil limpeza. Transforme seu banheiro ou área externa com esta grelha que alia beleza e praticidade. VANTAGENS - Abre e fecha automaticamente - Impede a entrada de insetos - Elimina a proliferação de mosquitos - Evita retorno de espuma SOBRE A FABRICANTE Com mais de 95 anos e trajetória marcada pela constante inovação, ética e pioneirismo, a Lorenzetti é líder no segmento de duchas, chuveiros, torneiras elétricas e aquecedores de água a gás. A empresa se destaca por colocar à disposição dos consumidores o que há de melhor em louças, assentos, metais e plásticos sanitários, purificadores de água, pressurizadores e lâmpadas, refletores, painéis e spots. objetivo é oferecer produtos de qualidade e com design inovador, desenvolvidos com a mais alta tecnologia e consciência ambiental.', 73.9, 73.9, NULL, 'Home & Living > Tools & Home Improvement > Construction Materials', 'https://cf.shopee.com.br/file/sg-11134201-7rd57-lx170c93rjre6e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1225401015%2F22997608140', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
