INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11988173896', 'Jogo De Pisca Seta Mini Cg 125 150/titan/ Fan/cargo (2 Unid)', 'ATENÇÃO CONTÉM 02 PISCAS Par de Mini Piscas Conteúdo da Embalagem: 01 Pisca Dianteiro Direito / Traseiro Esquerdo 01 Pisca Dianteiro Esquerdo / Traseiro Direito JOGO DE MINI PISCAS *SEM METALIZAR *Fixação através de parafuso (Adaptável em varias motos) Compatível com Modelo Original Honda Bros 125 2013 A 2015 Bros 150 2013 A 2015 Bros 160 2015 A 2021 Modelos Adaptáveis: CG 125CG 150CG FANCG TITANCG TODAYCG ML 125CG CARGOCBX 250 TWISTERCB 300CB 500XRE 300XRE 190NX 400 FALCON Especificação Técnica: - Pisca completo com coxim e chicote; - Compatibilidade de 12V - Marca: GVS Sport - Tipo de lâmpada: Base metalica - Alta resistência e durabilidade - Carcaça em plástico resistente - Material Leve e Resistente - Fácil instalação - Ótima qualidade e acabamento - Não acompanha lâmpada - Produto disponível a pronta entrega Instalação: Este produto possuí fácil instalação, não exige que mude a estrutura de sua moto, pois foi confeccionado seguindo as especificações do produto original, para encaixe e funcionamento perfeito. Vantagem: Agora você pode desfrutar de um produto com qualidade do original, para uma melhor reposição em sua moto e com baixo custo. Importante: Para que a instalação e funcionamento da peça ocorra perfeitamente, recomendamos que o produto seja instalado por um profissional especializado.', 69.9, 59.42, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Lighting', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mhhqhzzb8rgm25', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F11988173896', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
