INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697470899', 'Loção Hidramais Cereja e Avela 500ml', '#html-body [data-pb-style=QFF8YNC]{justify-content:Flex-start;display:Flex;flex-direction:Column;background-position:Left top;background-size:Cover;background-repeat:No-repeat;background-attachment:Scroll}A Loção Desodorante Cereja e Avelã possui formulação leve, não oleosa e é enriquecida com Colágeno Vegetal, tem ação desodorante e hidratante. Melhora a elasticidade e deixa a pele levemente perfumada. O que ele tem? Água, Glicerol, Álcool Cetearílico, Parafina Líquida, Hidróxido de Sódio, Manteiga de Karité, Óleo de Canola, Decametilciclopentasiloxano, Dimeticona, Palmitato de Isopropila, Petrolato, Fenoxietanol, Cetearete-20, Dimetilidantoína, Perfume, Amil Cinamal, Linalol, Butilfenil Metilpropional, Limoneno, Cumarina, Salicilato de Benzila, Geraniol, Citronelol, Carbômer, Poliacrilato de Sódio, Extrato de Semente de Avelã, Extrato de Ginja, Goma Xantana, Edetato Dissódico, Butil-Hidroxitolueno, Extrato da Goma de Acacia Senegal, Gliconolactona, Extrato de Spirulina Maxima, Extrato de Alga Fucus Vesiculosus, Extrato de Alga Cavalinha, Extrato de Alga Parda, Extrato de Porphyra Umbilicalis, Sorbato de Potássio, Benzoato de Sódio, Gliconato de Cálcio, Sesquicaprilato de Xilitila, Anidroxilitol. O que é ? Loção Desodorante Corporal Envolvente Fórmula com Colágeno Vegetal PlantCol® Como usar? Aplique o produto diretamente sobre a pele e massageie até sua completa absorção. Pode ser utilizado diariamente e reaplicado sempre que necessário. Protocolo: Mantenha fora do alcance de crianças e animais domésticos. Evite contato com os olhos. Caso o produto entre em contato com os olhos, lavar com água corrente em abundância e procurar um médico. Não usar na pele irritada ou lesionada. Caso apareça alguma irritação suspenda o uso imediatamente. Conservar em local fresco, ao abrigo da luz e calor excessivos. Tamanho: 200ml', 21.31, 21.31, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/sg-11134201-7rd4y-lujgvxz4k0s927', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F23697470899', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22192875005', 'Chinelo Olympikus 921 Tradicional Masculino - Marrom', 'OChinelo Olympikus 921 Tradicional Masculino tem o cabedal em borracha. Possui palmilha em EVA para maior conforto. Seu solado em borracha antiderrapante garante mais estabilidade durante o caminhar. Os tamanhos são conjugados: 35/36; 37/38; 39/40; 41/42 e 43/44.', 149.9, 139.9, NULL, 'Men Shoes > Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/sg-11134201-7rdxt-lyl6b75nih1368', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1178125772%2F22192875005', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
