INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26382576885', 'Organizador Gaveta com Divisória Mesa Porta Caneta Porta Treco Armazenamento Multiuso Escritório', 'Organizador de Gaveta com Divisória 12x10x12cm Solução versátil para quem busca praticidade e organização no dia a dia, o Organizador de Gaveta com Divisória é ideal para manter sua mesa limpa e funcional. Com uma gaveta e compartimentos internos, permite armazenar canetas, lápis, clips, notas, e diversos pequenos objetos de forma acessível e segura. Seu design compacto é perfeito para mesas de escritório, home offices, ambientes de estudo ou qualquer espaço que necessite de otimização. Pode ser utilizado também como: Organizador de remédios e primeiros socorros Caixa para kits de costura e pequenos acessórios Armazenamento de itens de papelaria Porta trecos para uso geral em diferentes ambientes MEDIDAS: 12x10x12cm Imagens e vídeos são meramente ilustrativos. A tonalidade da cor pode variar conforme o monitor.', 44.9, 37.9, NULL, 'Home & Living > Home Organizers > Desk Organizers', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcj901zj0u0xc1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436723291%2F26382576885', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22691642487', 'Kit Presente Para Dia Das Mães Almofada + Caneca Lembrancinha Dia Das Mães', 'A Almofada DecorativaDia Das Mães é o presente perfeito para homenagear e surpreender no Dia das Mães. Com um design exclusivo e encantador, essa almofada é ideal para decorar qualquer ambiente, trazendo um toque de carinho e aconchego. Seu enchimento proporciona conforto e maciez, permitindo que sua Mãe desfrute de momentos relaxantes e agradáveis. Surpreenda-a com esse gesto de carinho e faça com que ela se sinta amada e valorizada. Características: - Material Caneca: 100% acrílico (Lavavel); - Material interno: 100% poliéster; - Dimensões da almofada 25cm x 19cm - Dimensões da caneca (AxD): 9,5cm x 8cm;', 39.9, 28.24, NULL, 'Home & Living > Dinnerware > Cups, Mugs & Glasses', 'https://cf.shopee.com.br/file/br-11134207-820ma-mlrr7avmckcg4b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436723291%2F22691642487', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
