INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22697558430', 'Kit 4 Plafon Embutir Led Elgin Infinity Redondo 15w Sem Bordas Branco Quente LUZ AMARELA', 'KIT 4 PAINEL LED INFINITY REDONDO 15W BIVOLT ELGIN A combinação perfeita de iluminação e design. Esta luminária dará vida aos seus espaços para que você possa aproveitá-los ao máximo. Além disso, você pode personalizar seus cantinhos favoritos e dar-lhes detalhes diferenciados. Graças ao seu design especial, você pode instalar esta luminária em ambientes fechados e decorar todos os espaços da sua casa ou escritório de acordo com suas necessidades e gostos. Excelente acabamento, com luz difusa e efeito de borda infinita, pronta para instalação, bivolt, vida útil de 30.000h, design único, luz uniforme, driver integrado e molas de fixação inclusos. CARACTERÍSTICAS: Luminária sem bordas Luz Difusa e uniforme Driver e mola de fixação Potência: 15w Tensão: 110 - 220V (Bivolt) Frequência: 50/60Hz Fluxo Luminoso: 1500lm Eficiência Luminosa: 100lm/W Temperatura de Cor: 3000K (Branco Quente) Branco Quente LUZ AMARELA Ângulo de Facho 160° Vida Útil: 30.000h IP: 20 IRC: >80 ITENS INCLUSOS: 04 - PAINEL LED INFINITY REDONDO 15W BIVOLT ELGIN', 94.9, 74.9, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lwmvawnnehyu1c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1257849357%2F22697558430', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26583062110', 'Coisas que o Seminário Não Pôde me Ensinar - Collin Hansen', '📝 Descrição: 15 Coisas que o Seminário Não Pôde me Ensinar, escrito por Collin Hansen e Jeff Robinson, é uma obra que preenche a lacuna entre a formação acadêmica e a prática ministerial. Embora o seminário ofereça uma base teológica sólida, muitos pastores recém-formados enfrentam desafios inesperados ao liderar igrejas reais — como lidar com conflitos, sofrimento, transições e expectativas frustradas. Este livro reúne conselhos de líderes experientes que compartilham lições aprendidas no campo, com honestidade, empatia e sabedoria bíblica. Ideal para quem está começando no ministério ou deseja se preparar melhor para os aspectos humanos e espirituais da liderança pastoral. 📄 Ficha técnica: Título: 15 Coisas que o Seminário Não Pôde me Ensinar Autores: Collin Hansen e Jeff Robinson Editora: Vida Nova Ano de publicação: 2020 ISBN: 9788527509930 Idioma: Português Número de páginas: 176 Formato: Brochura Dimensões: 21 cm x 14 cm Peso: 220 g Categoria: Liderança cristã, ministério pastoral, vida cristã Indicação etária: A partir de 16 anos 🔍 Palavras-chave: seminário, liderança pastoral, collins hansen, jeff robinson, vida nova, ministério cristão, livro para pastores, desafios do ministério, formação teológica, igreja local', 44.89, 44.89, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8g6lhlgfq4xc6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380531074%2F26583062110', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
