INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23094228018', 'Paneleiro Smart 100% MDF 2 Portas Branco/Rustic Madesa', 'Paneleiro Smart 100% MDF 2 Portas Branco/Rustic MadesaEste é o módulo de paneleiro avulso da cozinha da linha Smart. Ele pode ser utilizado separadamente ou agregado a qualquer um dos modelos de cozinha da linha Smart. Principais características: 100% MDF, material ecologicamente correto que confere a boa resistência e durabilidade à peça. Possui puxadores em alumínio, dobradiças metálicas e rodapé encaixado com pés em PVC com regulagem de altura. Oferece excelente distribuição interna do espaço para que você organize toda a sua louça e armazene alimentos e eletro portáteis. O acabamento interno e externo é branco. As portas são no padrão amadeirado Rustic. Todos os acabamentos são em Pintura Poliéster de alta resistência e fácil limpeza que confere beleza e praticidade. Especificações Técnicas: - Marca: Madesa - Cor: Branco/Rustic - Portas: 2 - Prateleiras Internas: 4 - Dimensões (AxLxP): 195 x 50 x 47 cm - Garantia: 3 Meses Obs.: A Madesa não disponibiliza serviço de montagem. Imagem meramente ilustrativa. Os eletros e a decoração não acompanham o produto.', 489.99, 489.99, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7rdvk-mc9m9paxwck961', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F23094228018', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
