INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693252886', 'Panela Elétrica De Arroz Mondial Pe-42-10x 700w 10 Xícaras', 'DESCRIÇÃO RESUMIDA Com a Panela Elétrica Pratic 10i Premium Mondial você ganha tempo e eficiência no preparo das suas refeições. Possui capacidade para preparar até 10 xícaras de arroz e acompanha cesto que cozinha alimentos no vapor, preservando todos os nutrientes. Possui função aquecer, que mantém suas receitas quentinhas mesmo após terminar o preparo. Além disso, o design em inox garante sofisticação para sua cozinha. Características: Marca: Mondial Modelo: PE-42-10X Especificações: Voltagem: 127V Tensão: 700W Capacidade: 10 xícaras Material: PP e Inox Revestimento interno Acompanha acessório para cozimento no vapor Função aquecer Cuba antiaderente e removível Coletor de vapor Tipo de tomada: 10A Comprimento do cabo: 1,50m Dimensões: 25x28x26 cm (AxLxP) Garantia: 12 meses Conteúdo da embalagem: 1 x Panela Elétrica 1 x Acessório para Vapor 1 x Colher 1 x Copo medidor 1 x Manual de instruções Peso: 2,2 kg', 467.99, 229.99, NULL, 'Home Appliances > Kitchen Appliances > Rice Cookers', 'https://cf.shopee.com.br/file/sg-11134201-7rdyq-lzt20dl5vqbr3c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F359168917%2F23693252886', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798837531', 'Shorts Feminino Plus Size em Linho Secret Glam Preto', 'O Shorts Plus Size Secret Glam é confeccionado em Linho Strong, tecido encorpado, leve e respirável, ideal para os dias mais quentes. Com modelagem que valoriza a silhueta, oferece conforto e caimento sofisticado. Versátil e estiloso, é perfeito para compor looks casuais ou mais elegantes, adaptando-se a diferentes ocasiões com praticidade e charme. Uma peça essencial no guarda-roupa da mulher plus size.', 219.99, 219.99, NULL, 'Women Clothes > Shorts > Shorts', 'https://cf.shopee.com.br/file/sg-11134201-825ao-mr05jac1fvutf6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F778895824%2F22798837531', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393478349', 'Coleção Minha Primeira Infância - Box com 4 Livrinhos', 'A coleção de livros "Minha Primeira Infância" é um encantador conjunto de 4 livrinhos especialmente projetados para introduzir os pequenos leitores ao mundo ao seu redor. Cada livro, abrangendo temas como "Animais", "Frutas e Vegetais", "Números" e "Veículos", cativa crianças com ilustrações vibrantes e texto simples, incentivando o aprendizado e a curiosidade desde a mais tenra idade. Essa coleção é uma ferramenta essencial para pais e cuidadores que desejam estimular o desenvolvimento cognitivo e o amor pela leitura desde o berço.', 79.0, 59.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rdwx-m1fu5qiay5a76d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F482840775%2F23393478349', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10434059813', 'O Diário de Anne Frank - Capa Especial', 'Imagine um confinamento de mais de dois anos, num tempo em que não havia celular, internet e nem mesmo televisão. Foi essa a saída que um grupo de oito judeus buscou, no auge da Segunda Guerra Mundial, para escapar dos nazistas. Tempos difíceis, porém, cheios de esperança. Os detalhes de como passavam o dia, o que comiam, como faziam sua higiene e até se divertiam, foram registrados por uma garota em seu diário. Ela não sobreviveu ao Holocausto. Porém o Diário de Anne Frank sobreviveu ao tempo. Foi publicado pela primeira vez em 1947 e se tornou um dos livros mais lidos do mundo, traduzido para mais de 60 idiomas. SOBRE O AUTOR Annelies Marie Frank nasceu no dia 12 de junho de 1929 em Frankfurt, na Alemanha. Seus pais eram Otto e Edith. Tinha uma irmã mais velha chamada Margot. Em 1934, a família se mudou para Amsterdã, na Holanda. No dia 6 de julho de 1942, foram todos para o esconderijo no anexo secreto, onde foram descobertos em agosto de 1944. Anne Frank morreu no campo de concentração de Bergen-Belsen, na cidade de Celle, perto de Hanover, na Alemanha, provavelmente em 12 de março de 1945. DESCRIÇÃO DO PRODUTO: ISBN13 :9786580921027 Páginas : 212 Publicação: 1ª Edição - 2021 Encadernação: Brochura Formato: 15,5 x 23,0 cm', 29.9, 16.9, NULL, 'Books & Magazines > Books > Biography & Memoirs', 'https://cf.shopee.com.br/file/ed5758a3411b530aeaabee579f001dfd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F482840775%2F10434059813', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22797458204', 'Os Flintstones Revista em Quadrinhos Edição 03', 'Viaje de volta à Idade da Pedra com as aventuras divertidas de Os Flintstones em uma emocionante edição de histórias em quadrinhos. Prepare-se para rir e se encantar com essa adorável família pré-histórica.', 7.99, 7.9, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-7rd5c-lu6k07s851w4a6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F482840775%2F22797458204', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23799232371', 'Kit Fan Com 3 Unidades Gamer Ninja Fuuton, ARGB, 120mm, White', 'KIT FAN COM 3 UNIDADES GAMER NINJA FUUTON 120MM ARGB BRANCO: ESTILO, SILÊNCIO E CUSTO-BENEFÍCIO O Kit de Ventoinhas Gamer Ninja Fuuton (composto por 3 unidades de 120 mm na cor branca) é a solução ideal para quem busca adicionar um toque de estilo ao setup com um excelente custo-benefício. Equipado com iluminação ARGB sincronizável, pás curvas para maior pressão e um rolamento de alta qualidade, ele maximiza a refrigeração do seu gabinete enquanto mantém o ruído operacional em níveis extremamente baixos. ................................................................... DESTAQUES DO PRODUTO Custo-Benefício e Estilo: Destacando-se como uma das opções mais acessíveis do mercado, ele entrega um visual elegante (na cor branca) e alto desempenho para o seu computador. Iluminação ARGB Sincronizável: Exiba a combinação de cores da sua preferência. O sistema possui cabeçalho RGB endereçável de 5V e é compatível com os softwares de controle das principais placas-mãe do mercado (ASUS, GIGABYTE, MSI e ASRock). Operação Super Silenciosa: Graças à sua tecnologia de refrigeração otimizada e rolamento de precisão, o nível de ruído máximo atinge apenas 22,5 dB(A), garantindo um ambiente de uso tranquilo mesmo em momentos de maior exigência. Pás Curvadas de Alta Eficiência: O design exclusivo das pás direciona o fluxo de ar de maneira efetiva, aumentando a pressão estática, minimizando a resistência do ar e garantindo o máximo desempenho de resfriamento. ................................................................... ESPECIFICAÇÕES TÉCNICAS GERAIS Marca: Gamer Ninja Modelo: Kit Fan Gamer Ninja Fuuton Branco (3 Unidades) Cor: Branco Dimensões Físicas (Por Ventoinha): 120 mm (C) x 120 mm (L) x 25 mm (A) Tempo Médio Entre Falhas (MTBF): 20.000 horas ................................................................... DESEMPENHO DE REFRIGERAÇÃO Velocidade de Rotação: 1200 RPM (± 10%) Fluxo de Ar Máximo: 32,4 CFM Pressão Estática Máxima: 1,09 mmH2O Nível de Ruído Máximo: 22,5 dB(A) Tipo de Rolamento: Rolamento Fluidodinâmico / FDB (Fluid Dynamic Bearing) ................................................................... ENERGIA E ALIMENTAÇÃO Tensão Nominal de Operação: 12 V Faixa de Tensão Operacional (DC): 9,0 V a 13,2 V Tensão Inicial (Partida): 9 V (ou menos) Corrente Nominal: 0,28 A (± 0,02 A) ................................................................................................ TERABYTE SHOP OFICIAL: 20 ANOS DE LEGADO TECH A loja preferida de Gamers e Entusiastas é referência em qualidade e excelência. Montamos seu setup dos sonhos com produtos de alta performance e suporte excepcional. Sua melhor experiência em tecnologia começa aqui!', 149.9, 109.04, NULL, 'Computers & Accessories > Desktop & Laptop Components > Fans & Heatsinks', 'https://cf.shopee.com.br/file/sg-11134201-81zu6-miku8nou64207f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1552226494%2F23799232371', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393353860', '‎Parafusadeira e Furadeira Impacto Makita 12V Hp333 2 Bataterias Bivolt', 'Com o objetivo de oferecer uma solução completa e profissional para as demandas de nossos clientes, apresentamos a. Este equipamento é a escolha estratégica para quem busca a máxima eficiência da tecnologia 12V CXT, combinando um design ultra compacto com a robustez necessária para aplicações industriais e de montagem. Desenvolvida para profissionais que necessitam de mobilidade sem abrir mão do torque, destaca-se pela sua versatilidade multimaterial, permitindo furos precisos em aço, madeira e alvenaria com agilidade impressionante. A engenharia por trás deste modelo foca na produtividade contínua. Equipada com duas baterias de 1.5Ah, ela garante que o fluxo de trabalho não seja interrompido. Diferenciais de Alta Performance:Tecnologia CXT (Compact eXtreme Technology): Maior potência em um corpo reduzido e baterias com indicador de carga. Sistema de Impacto: Função martelete para perfurações eficientes em tijolos e concreto leve. Controle de Torque: 20 níveis de ajuste para parafusamentos delicados até os mais pesados, evitando danos ao material. Duas Velocidades Mecânicas: Opção de alto torque para parafusar ou alta velocidade para perfurações rápidas. Segurança e Conforto: Punho emborrachado com desenho ergonômico e freio elétrico para parada instantânea. Especificações Técnicas Detalhadas:Tensão da Bateria: 12V (Íons de Lítio Linha CXT). Amperagem: 1.5 Ah (acompanha 2 unidades). Mandril: Aperto rápido de 3/8” (10 mm). Peso: 1,1 kg (extremamente equilibrada). Itens Inclusos: 2 baterias 12V 1.5Ah, carregador bivolt, ponta bit Phillips e maleta rígida original.', 928.9, 635.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-81ztl-mig2plgts0sh79', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F965617276%2F22393353860', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22525395587', 'Cloche Brinox Arienzo - 24 cm Em Aço Inox', 'Seja Bem-Vindo(a) à Mimorada! O "Cloche Brinox Arienzo" é um elegante utensílio de serviço feito em aço inoxidável, projetado para aprimorar a apresentação e a experiência de servir. Abaixo estão algumas características e informações sobre este cloche: - Material: - Fabricado em Aço Inox, um material conhecido por sua durabilidade, resistência e facilidade de limpeza. - Função: - O cloche tem a função de cobrir e proteger os alimentos, proporcionando uma apresentação mais sofisticada e contribuindo para a manutenção da temperatura dos pratos. - Tamanho: - Possui um diâmetro de 24 cm, oferecendo uma cobertura adequada para uma variedade de pratos. - Versatilidade: - Pode ser utilizado para servir uma variedade de pratos, desde entradas até pratos principais, mantendo os alimentos aquecidos e protegidos até o momento de servir. - Resistência e Fácil Limpeza: - O aço inoxidável confere resistência ao cloche, tornando-o adequado para uso frequente. Além disso, o material é fácil de limpar e não interfere no sabor ou aroma dos alimentos. - Estilo Sofisticado: - Além de sua funcionalidade, o cloche adiciona um toque de elegância à apresentação dos pratos, criando uma atmosfera mais refinada durante o serviço. Ao utilizar o cloche, você não apenas protege os alimentos, mas também aprimora a experiência visual e sensorial dos seus convidados durante as refeições.', 219.99, 177.65, NULL, 'Home & Living > Kitchenware > Others', 'https://cf.shopee.com.br/file/sg-11134201-23020-ttpioo7rwnnv2e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842996464%2F22525395587', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498801205', 'Casaco Infantil Tweed Shine Trick Nick Branco', 'O Casaco Infantil Tweed Shine Trick Nick é a escolha ideal para deixar os pequenos aquecidos com muito estilo. Confeccionado em malha tweed shine, oferece um toque suave e elegante, com brilho discreto que dá um charme extra à peça. Seu design clássico conta com botões que proporcionam um ajuste perfeito, além de facilitar o uso. Versátil e sofisticado, é perfeito para compor looks modernos e confortáveis, garantindo praticidade e estilo para o dia a dia das crianças.', 189.99, 151.99, NULL, 'Baby & Kids Fashion > Girl Clothes > Outerwear', 'https://cf.shopee.com.br/file/sg-11134201-825ad-mr0h26bonwg2c4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F778895824%2F22498801205', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21257577434', 'Lixeira Com Tampa Basculante Brinox Decorline 3,2 Litros Aço Inox', 'Seja Bem-Vindo(a) à Mimorada! A Lixeira com Tampa Basculante Brinox Decorline, com capacidade de 3,2 litros, oferece a solução perfeita para a gestão de resíduos em ambientes residenciais e comerciais. A linha Decorline, conhecida por sua elegância e praticidade, apresenta lixeiras discretas, resistentes e de fácil manuseio. A estrutura em aço inox, com acabamento alto brilho, não possui porosidades, o que facilita a limpeza e impede o acúmulo de resíduos. A tampa basculante, além de resistente, é fácil de usar, proporcionando praticidade ao descartar resíduos. O fundo plástico protege a lixeira e garante sua longa vida útil. Disponível em oito tamanhos diferentes, a lixeira Decorline com tampa basculante se adapta perfeitamente aos diversos ambientes da sua casa ou empresa. Escolha entre as opções de 3,2L, 5,4L, 7,8L, 21,2L, 28,17L, 40,5L, 47L e 64L, combinando funcionalidade e estilo. Material: Aço Inox', 169.99, 127.5, NULL, 'Home & Living > Home Care Supplies > Trash & Recycling Bins', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lpgt7spp9iuq04', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842996464%2F21257577434', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253654825', 'Encontro diário com Deus 2026', 'Encontro diário com Deus 2026 Por meio da Meditação e da Oração, este livro nos convida a um encontro diário com Deus. Além de Mensagens, esta obra traz pensamentos, santos do Dia, datas comemorativas, leituras bíblicas e as mudanças da Lua. Informações Adicionais Autor: PASINI, EDRIAN JOSUÉ Data Publicação: 01/12/2025 Tipo de capa: BROCHURA Condição do Item: Novo Idioma: INDEFINIDO Páginas: 216 Edição: 2025 ISBN-13: 7898563142984 ISBN-10: 8563142984', 18.7, 18.7, NULL, 'Stationery > Notebooks & Papers > Notebooks & Notepads', 'https://cf.shopee.com.br/file/sg-11134201-8262v-mjppislbn1tuec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F58253654825', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597448699', 'Wok com Tampa e Indução Brinox Antiaderente Ceramic Life Sirius - 28cm 3,4L Vanilla', 'Seja Bem-Vindo(a) à Mimorada! *Possui fundo de indução e serve em todos os tipos de fogões. Ter uma Wok em casa facilita e traz mais praticidade. Ideal para grelhar e saltear os alimentos, engrossar molhos e fritar com pouco óleo, a Wok com Tampa e Indução da Linha Ceramic Life Sirius/Brinox une a versatilidade do modelo com tecnologia e praticidade. A Panela Wok Sirius conta com revestimento antiaderente Mineral Resist, o que torna o preparo de pratos mais saudável, pois cozinha com menos óleo, e a limpeza mais prática. Com 28 cm de diâmetro por 7,5 cm de altura e 3,4 L de capacidade, a Wok Ceramic Life Sirius é perfeita para preparar pratos da culinária oriental, entre eles o yakisoba. O alumínio da estrutura da panela aquece os alimentos de maneira uniforme e acelera o processo de cocção, possibilitando que você fique menos tempo na cozinha. Com pintura externa siliconada, a cor Vanilla desta panela Wok traz elegância e sobriedade à decoração. O cabo e o pomel são em baquelite com acabamento soft-touch e efeito amadeirado. Com design contemporâneo, a peça tem tampa flat em vidro temperado com bordas de silicone e saída de vapor, o que facilita para acompanhar o cozimento dos alimentos. O modelo ainda conta com a certificação PFOA free, ou seja, é uma Wok livre de liberação de toxinas. Produto de alta durabilidade, que ao final do ciclo ainda pode retornar para se tornar uma nova peça, pois o alumínio da panela é 100% reciclável. A Linha Ceramic Life Sirius é compatível com fogões de indução e disponibiliza diferentes opções de panelas. Aproveite para adquirir a linha completa para sua casa e deixar sua cozinha ainda mais charmosa. A Brinox oferece um grande conjunto de utilidades domésticas para o seu dia a dia e para ocasiões especiais. Tudo produzido com os mais rigorosos padrões de qualidade técnica e responsabilidade ambiental. Os produtos Brinox agregam tecnologia, sofisticação e sustentabilidade.', 284.99, 284.99, NULL, 'Home & Living > Kitchenware > Pans', 'https://cf.shopee.com.br/file/sg-11134201-7rd3m-ltza498eizhu55', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842996464%2F23597448699', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898065391', 'Trava Elétrica Tampa Traseira Caçamba Tragial L200 Triton Outdoor 2011 A 2020', 'Kit Trava Elétrica Tampa Traseira Caçamba Tragial Mitsubishi L200 Outdoor 2013 a 2020 L200 Triton 2011 a 2020 Aplicação: Compatível com: • L200 Outdoor 2013 em diante • L200 Triton 2011 em diante Especificação Técnica: • Modelo dedicado para o veículo. • Tensão de trabalho 12 volts. • Não necessita de adaptações. • Fácil instalação. • Ao Acionar a Trava Elétrica ou o Alarme, a Tampa Traseira irá Travar ou Destravar Conteúdo da Embalagem: • Trava Elétrica Específica para o Veículo. • Chicote • Manual de Instalação. • Parafusos e Fixações. • Embalagem.', 136.9, 136.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Safety > Locks', 'https://cf.shopee.com.br/file/sg-11134201-7qvdf-lf77wcjsbwdrc7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1273324128%2F23898065391', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20597806150', 'APRENDIZ DO VILÃO', 'APRENDIZ DO VILÃO O segundo volume da trilogia Assistente do Vilão, a fantasia divertida fenômeno do TikTokAVISO À EQUIPE Ultimamente tem havido um aumento perturbador nos comportamentos de felicidade, alegria e otimismo de maneira geral. Por favor, retome seus hábitos sombrios e ameaçadores o mais rápido possível A gerênciaEvie Sage nunca esteve tão feliz de ser a assistente do Vilão. Quem poderia imaginar que trabalhar para um senhor do mal ridiculamente bonito (shhh, é ruim pra imagem dele) seria tão gratificante? Ainda assim, os negócios do mal são muito cansativos, as forças do bem são irritantemente persistentes, e o chefe antes mencionado está hm fora do escritório.Mas Rennedawn está afundado em problemas e tudo até o Reinaldo aponta para uma catástrofe. Algo peculiar está acontecendo com a magia do reino e fez o castelo do Vilão vulnerável aos inimigos inclusive seu maior rival, o rei.Em Aprendiz do Vilão, Evie precisará aprender novas habilidades para confrontar seu maior desafio proteger o lar do Vilão, todos os seus trabalhos nefastos e, talvez (desde que ninguém descubra), o reino inteiro. Sem pressão, Evie!Traição. Manusear uma adaga. Conspirar com o inimigo. Tudo isso é tão tão maravilhosamente divertido. Mas o que acontece quando a assistente do Vilão está pronta para se tornar sua aprendiz?. Informações Adicionais Autor: NICOLE MAEHRER, HANNAH Data Publicação: 28/09/2024 Tipo de capa: BROCHURA Condição do Item: Novo Subtitulo: APRENDIZ DO VILÃO Idioma: INDEFINIDO Páginas: 544 Edição: 1 ISBN-13: 9786585348782 ISBN-10: 6585348788', 69.9, 63.61, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rdyq-lzypmwgrtvw7d6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F20597806150', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398891396', 'Colchão King D45 Alfa + Base 193X203X62', 'Colchão Bom Pastor Alfa D45 O Colchão Alfa é a proposta ideal para quem busca um colchão com um design inovador e de extrema qualidade. O Alfa Possui uma camada de Pillow interno, espuma de altíssima qualidade, que ''abraça'' seu corpo ao deitar, além disso, contém tecido de multifilamentos de poliéster que proporciona resistência. Um tecido de última geração e alta tecnologia. O Colchão Alfa é produzido de espuma 100% poliuretano D45 e EPS. O EPS é uma estrutura Ortopédica em forma de uma placa rígida como a madeira, porém muito mais leve em comparação aos colchões tradicionais ortopédicos de madeira, além de ser bem mais durável. Este produto oferece firmeza com o conforto adequado. Com duas camadas de conforto compostas de Espuma D45 e Espuma Hipersoft, proporciona maior durabilidade e estabilidade ao seu colchão. Especificações: • Tecido 100% Poliéster com multifilamentos de alta resistência aumentando a durabilidade do seu colchão. • Espuma 100% Poliuretano D45 e Espuma Hipersoft. Espuma de Alta performance apresentando excelente desempenho e sensação de aconchego. • Camada de EPS • Bordado em Matelassê. Proporcionando maior maciez e mais volume ao colchão. • Altura: 62 cm (Base + Colchão: 50cm, Pés: 12cm) Observações importantes: Produtos podem apresentar diferenças de tonalidades entre a foto na tela e o produto real, devido a calibração de cor da tela. O aspecto ou proporção do colchão vai variar de acordo com o tamanho escolhido (Solteiro, Casal, Queen, King). A foto serve apenas de referência para visualização de acabamento e detalhes estéticos do produto. O serviço de transporte não se responsabiliza por produtos que precisem subir escadas, ou ser içados a algum andar superior.Este serviço fica a cargo do cliente. Verifique as dimensões do produto antes de finalizar a compra. Certifique-se que o produto passa por escadas, vãos, portas ou janelas antes de finalizar a compra. A Loja Bom Pastor não faz montagem de produtos. Não nos responsabilizamos por erros de montagem. Manuais e peças para a montagem são fornecidos com o produto.', 1799.0, 1699.0, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/br-11134207-820m7-mpzc2j7qg4ch72', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1563516628%2F23398891396', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253930863', 'Combo Batom Duo Glam Micro Plump: Malva Essencial 1,8g + Rosado Nobre 1,8g', 'Seu visual merece ganhar um destaque glamuroso! O Combo Batom Duo Glam Micro Plump traz duas opções de cores para você escolher qual usar em cada momento da vida. Dê aos seus lábios esse efeito marcante, que deixa sua boca volumosa e hidratada, além de valorizada com acabamento variados para que você possa revelar suas diversas facetas: BATOM DUO O Batom Duo Glam Micro Plump é múltiplo! Ele garante lábios volumosos em 5 minutos, deixando a boca exuberante de imediato e bem tratada a longo prazo. Possui duas possibilidades de texturas: Batom stick semi-matte e gloss plump de cor única, o que permite alcançar três tipos de efeitos com seus diferentes modos de uso: Efeito vinílico, semi-mate ou gloss plump, depende de como você quiser usar! Conheça essas cores que vão te acompanhar na vida: Rosado Nobre: Um batom rosa clássico, que dá vida à produção;Malva Essential: Uma cor de rosa queimado ideal para diversas ocasiões. Sua poderosa Tecnologia Micro Plump, enriquecida com Bio Hialurônico e Gergelim Oriental, possui maior permeação na pele e efeitos duradouros. Desenvolvido com biotecnologia , entrega contorno, definição, efeito micropigmentação e firmeza para os seus lábios. Nenhum produto Eudora é testado em animais, ou seja, este item possui selo Cruelty Free. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 125.98, 125.98, NULL, 'Beauty > Makeup > Lips', 'https://cf.shopee.com.br/file/sg-11134201-82604-mjinaiw9tudh1d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1679511787%2F58253930863', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
