INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259463614', 'Da Terrinha Goma de Tapioca', 'A Goma de Tapioca Da Terrinha é perfeita para um lanche rápido e saudável, feita com mandioca, uma rica fonte de carboidratos. Já vem pronta para uso, sem necessidade de peneirar ou adicionar água. Livre de glúten e lactose, ideal para quem possui restrições alimentares. Modo de Preparo: * Aqueça uma frigideira em fogo baixo. * Espalhe cerca de 100g de goma pronta para tapioca Da Terrinha. * Aqueça por cerca de 2 minutos até se soltar da borda. * Coloque o recheio de sua preferência. * Dobre a tapioca sobre o recheio e aguarde por 30 segundos. * Agora é só servir! Bom apetite!', 8.99, 8.99, NULL, 'Food & Beverages > Baking Needs > Flour', 'https://cf.shopee.com.br/file/sg-11134201-8260f-mj72o4apq77nc4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555057%2F58259463614', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19798187477', 'Shampoo Powerdog Neutro 500 mL', 'O Shampoo Powerdog Neutro possui fórmula exclusiva desenvolvida para cães, limpa profundamente proporcionando brilho e maciez e pelagem do animal. Modo de Usar: Molhar o animal e aplicar o produto ao longo de seu dorso, massageando todo o pelo; Enxaguar e repetir a aplicação, deixando a espuma agir por alguns minutos, para obter melhor resultado; Enxaguar novamente.', 32.99, 22.99, NULL, 'Pets > Pet Grooming > Hair Care', 'https://cf.shopee.com.br/file/br-11134207-7r98o-macvoudcinbjad', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F464043565%2F19798187477', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694239657', 'Kit - 12 Colheres De Sobremesa Búzios Em Aço Inox Csibag - Tramontina', 'Kit - 12 Colheres De Sobremesa Búzios Em Aço Inox Csibag - Tramontina MUITO IMPORTANTE: -- CONFERIR PRODUTOS NO ATO DO RECEBIMENTO. NÃO ACEITAR PRODUTOS COM EMBALAGEM VIOLADA (AMASSADO, RASGADO, ABERTO, QUEBRADO, ETC), A RECUSA DEVE SER FEITA NO ATO. 12 Colheres de Sobremesa Búzios Em Aço Inox Csibag - Tramontina 23756400 A sobremesa faz parte de um ritual de alegria e união, a Colher para Sobremesa em Aço Inox Tramontina Búzios auxilia nesses momentos de compartilhamento. Fabricado com materiais de alta qualidade, o talher é de fácil manuseio devido a sua espessura e design inteiramente de aço inox. Simples para limpar, pode ser levado à máquina de lavar e é caracterizado por sua durabilidade e resistência. - Talher produzido em aço inox que mantém a beleza, a higiene e a durabilidade. - Colher que garante maior resistência devido a espessura do aço e a estampagem da lâmina. - Pode ir à máquina de lavar louças facilitando seu dia a dia. - Garantia de 90 dias para vícios ou defeitos de fabricação. Tamanho da embalagem: 3cm A x 13cm L x 20cm P Peso: 0,330kg Cor: Prata | Selecione: Colher de sobremesa | Tipo de Talher: Colher', 33.66, 33.66, NULL, 'Home & Living > Dinnerware > Cutleries', 'https://cf.shopee.com.br/file/sg-11134201-7rdyu-mcc3hodhsgxte2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F22694239657', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
