INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18699579154', 'Máscara de Hidratação Dabelle Explosão de Brilho 800g', 'Características do produto: Marca: Dabelle Peso: 800g Especificações gerais: Ideal para a etapa de reconstrução do cronograma capilar. Produto vegano. Não testado em animais. Sem parabenos, sulfato e sal. Modo de usar: Após lavar os cabelos com o Shampoo, aplique uma quantidade suficiente para enluvar completamente os fios. Massageie em direção às pontas e penteie delicadamente com os dedos ou com um pente de dentes largos. Deixe agir por 3 minutos e enxágue bem. Se preferir um tratamento mais potente, use touca por 5 minutos. Fornecedor: Dabelle', 23.57, 23.57, NULL, 'Beauty > Others', 'https://cf.shopee.com.br/file/sg-11134201-824il-mpibqc8fbi82cd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F822103155%2F18699579154', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693900213', 'Top Feminino Fitness Compresão Rocca', 'Top Feminino Fitness Compresão Rocca O top Compressão Rocca possui design de alta Performance tecnológica que ajuda no desempenho esportivo! Sua modelagem de média impacto sem bojo, possui recortes estratégicos com mix de tecido e decote costas estilo nadador, valorizando ombros, escápula e também facilita no movimento durante a prática. Em tecido Hydefit® Adaptiv que possui ótima sustentação, além de evitar transparência durante o uso, permite maior respirabilidade, evitando o suor excessivo e tecnologia inclusiva LYCRA® ADAPTIV: permitindo que a modelagem se adapta ao seu corpo do jeito que ele é.', 69.9, 62.91, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Sports Bras', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8nk0gtwipw1d2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F675303259%2F23693900213', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21398797826', 'Kit Perfume Capilar + Shampoo a Seco + Óleo Finalizador Capilar (3 Produtos)', 'Não Deu Tempo de Lavar o Cabelo? sem Problemas, o Kit Perfume Capilar + Shampoo a Seco + Óleo Capilar É Seu Aliado para Os Dias Corridos. Combinando Esses Três Produtos de Finalização Capilar da Linha Hair Care Océane, Você Garante Um Cabelo Cheiroso, Hidratado e com Aspecto Limpo, Já Que o Shampoo a Seco Disfarça a Oleosidade do Cabelo, o Perfume Capilar Proporciona Hidratação Dos Fios e Proteção Contra o Ressecamento Natural, Reduz o Frizz e Deixa Os Fios com Um Cheiro Maravilhoso. o Óleo Finalizador Capilar É Perfeito para Combater o Frizz, Dar Brilho e Maciez. Graças Aos Seus Componentes, o Óleo Capilar Repara e Reconstrói a Fibra Desde o Interior, Disciplinando o Arrepiado e Hidratando o Fio. O Kit Perfume Capilar + Shampoo a Seco + Óleo Capilar Contém: - 1 Shampoo a Seco 150ml - 1 Perfume Capilar 60ml - 1 Óleo Finalizador Capilar 60ml Shampoo a Seco Sim, Nosso Shampoo a Seco Pode Ser Utilizado Por Todos Os Tipos de Cabelos, Incluindo Os Cabelos Cacheados e Ondulados, Lisos ou Coloridos. Ele Disfarça a Oleosidade Dos Fios sem Ressecar e Seu Cabelo Não Fica Duro! Ah, e Se Você Tem Cabelos Tingidos ou Descoloridos, o Shampoo a Seco Ainda Ajuda a Prolongar a Durabilidade da Coloração, Sabia? Isso Porque Lavar Fios Coloridos com Muita Frequência Pode Desbotar a Cor. Pegou Essa Praticidade? Então Chegou a Hora de Experimentar! Sua Fórmula É Livre de Clorofluorcarbono, o Temido Cfc, Que É Um Dos Responsáveis Pela Degradação da Camada de Ozônio da Atmosfera. Pensando Nisso, Desenvolvemos Uma Fórmula Que Expele o Produto Na Medida Certa sem Prejudicar o Meio Ambiente. Perfume Capilar Já Ouviu Falar em Perfume Capilar? Este Produto Deixa Os Cabelos com Uma Fragrância Fantástica de Maneira Descomplicada - Basta Borrifar Ao Longo Dos Fios e Sentir a Sensação de Leveza e Refrescância. Pode Usar Todos Os Dias sem Medo: Ele Vai Neutralizar Os Odores Que Podem Se Acumular No Seu Fio Ao Longo do Dia Como em Um Passe de Mágica! Se Você Ama Aquele Cheirinho de Banho Recém-Tomado, Esse Produto Foi Feito Sob Medida para a Sua Vida. O Perfume Proporciona Hidratação Dos Fios e Proteção Contra o Ressecamento Natural. e Ainda Tem Mais Benefícios: Ele Aumenta o Brilho e Deixa Os Fios Super Leves, Tudo Isso Enquanto Reduz o Frizz e Deixa o Visual Mais Bonito. Óleo Finalizador Capilar Este Poderoso Óleo Finalizador Capilar É Perfeito para Combater o Frizz, Dar Brilho e Maciez. Graças Aos Seus Componentes, o Óleo Capilar Repara e Reconstrói a Fibra Desde o Interior, Disciplinando o Arrepiado e Hidratando o Fio. O Ativo Pro Care Aox Atua Contra o Envelhecimento Dos Fios e Combate o Estresse Oxidativo No Sistema Capilar. Enquanto o Reparage Age Na Reparação Dos Danos Causados Pelo Estresse Físico, Químico, Térmico e Ambiental. O Óleo Finalizador Capilar É Rico em Aminoácidos e Possui Uma Fórmula Suave Que Confere Luminosidade Radiante, Deixando Os Cabelos Mais Macios e Sedosos.', 189.9, 179.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-824j5-mpe5zozdtr7lbe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842559166%2F21398797826', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29387169650', 'NIVEA Hidratante Labial Cupcake de Baunilha Ed. Limitada Bela Disney® Princesa 4,8g', 'O que é? Chegou a hora de brilhar junto com o novo NIVEA HIDRATANTE LABIAL BELA NIVEA 4.8G, Edição Limitada Disney da Bela! Com uma fórmula produzida à base de óleos de origem natural, o novo hidratante labial NIVEA hidrata por 24h e protege contra o ressecamento. Com cheirinho delicioso de baunilha e um toque sutil de brilho, deixa o sorriso pronto para espalhar magia por onde for. Benefícios e diferenciais -Ingredientes de origem natural, livre de óleo mineral -Protege contra o ressecamento -Hidrata por 24h -Cheirinho de Baunilha -Dermatologicamente aprovado Como usar o NIVEA HIDRATANTE LABIAL BELA NIVEA 4.8G Disney Bela? 1. Deslize NIVEA Hidratante sobre os lábios 2. Reaplique facilmente sempre que necessário *PRECAUÇÕES: Uso externo. Não ingerir. Não usar em crianças menores de 3 anos.', 27.9, 27.9, NULL, 'Beauty > Skincare > Lip Treatment', 'https://cf.shopee.com.br/file/br-11134207-820m9-mlhvyjn03n5y97', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F502619181%2F29387169650', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793881907', 'Conjunto Sofá Luxemburgo 3 E 2 Lugares 1,52m e 2,02m Suede Castor', 'Por que o Conjunto Estofado Luxemburgo? Elegância, Requinte, Glamour, É isso que o Conjunto Estofado Luxemburgo vai Agregar à sua sala. O móvel traz traços modernos e agradáveis proporcionando uma decoração fina e poderosa. Suas almofadas nos Braços são macias e seu revestimento em Poliéster de alta resistência a fricção reconhecido pela extrema maciez ao toque. Características: - Encosto: Fibra de silicone / Flocos de espuma - Assentos: Espuma D28 - Largura do braço: 25cm - Espuma do braço: Fibra siliconada / Flocos de espuma - Estrutura desenvolvida em madeira de eucalipto - Suporta até 110kg por pessoa Medidas montado: Peça de 2 Lugares Altura: 100cm Largura: 152cm Profundidade: 75cm Peça de 3 Lugares Altura: 100cm Largura: 202cm Profundidade: 75cm *Fácil montagem, não é necessário montador. *3 meses de Garantia Marca: Cama InBox Uma praticidade: Encosto Removivel para facilitar o transporte em corredores estreitos e escadas. Informações importantes: * Os objetos que ambientam as fotos não acompanham o produto. * Nossas cores podem sofrer alterações dependendo do seu monitor. * Verifique as dimensões do produto e certifique-se que o percurso que ele fará até o local de uso permite sua passagem. * Nos responsabilizamos pela entrega dos produtos adquiridos até a porta de entrada ou portaria do endereço indicado. Quaisquer despesas ou dano no transporte até o local de uso ficam a cargo do cliente.', 2719.0, 2368.48, NULL, 'Home & Living > Furniture > Sofas', 'https://cf.shopee.com.br/file/sg-11134201-7reo0-m8dcwmynvg9h4b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F882904544%2F23793881907', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20499067431', 'Aparador Buffet Multiuso Multimóveis Suspenso com Espelhos 4 Portas MP8005', 'O Aparador Buffet Suspenso com Espelhos 4 Portas Multimóveis MP8005 é ideal para quem quer unir organização, sofisticação e praticidade em um só móvel. Com design clean e moderno, ele valoriza a sala de jantar, estar ou espaço gourmet sem pesar na decoração. Por ser suspenso, ajuda a otimizar o espaço e facilita a limpeza do ambiente, deixando tudo mais funcional no dia a dia. As 4 portas oferecem ótimo espaço interno para guardar louças, utensílios, jogos americanos ou objetos que você prefere manter organizados e fora de vista. Os espelhos aplicados nas portas trazem um toque de elegância e ainda ajudam a ampliar visualmente o ambiente, deixando o espaço mais iluminado e moderno. Além disso, as bordas lapidadas garantem mais segurança no uso diário. ✨ Por que escolher este aparador suspenso com espelhos? ✔ Visual moderno e sofisticado ✔ Suspenso: mais espaço livre e fácil de limpar ✔ 4 portas para melhor organização ✔ Espelhos que ampliam e valorizam o ambiente ✔ Ideal para sala de jantar, estar ou espaço gourmet 💡 Dica valiosa dos clientes: instale o aparador em frente ou próximo a uma fonte de luz natural ou luminária. Os espelhos ajudam a refletir a luz, deixando o ambiente mais claro e com sensação de espaço maior. 📦 Conteúdo da embalagem 1 (um) Aparador Buffet Suspenso 1 Kit Espelhos Kit de ferragens Manual de montagem 📐 Dimensões do produto montado Altura: 39,5 cm Largura: 123,5 cm Profundidade: 31,5 cm Confira as medidas detalhadas na imagem técnica do produto. ⚠️ Observações importantes Produto entregue desmontado (não oferecemos serviço de montagem). As cores podem variar conforme a configuração da tela do seu dispositivo. Imagem meramente ilustrativa. Itens de decoração não acompanham o produto. ⚡ Aqui na Loja Multimóveis, você compra com total segurança e recebe sua entrega garantida.', 509.99, 349.99, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7rbk5-lnsjzgdnojhi68', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F20499067431', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10637994383', 'Assadeira Quadrada Antiaderente 3L Preto Nacional', 'Transforme seus momentos na cozinha em experiências cheias de cor e sabor com a Assadeira Quadrada Antiaderente Nacional preta. Produzida em alumínio de alta qualidade, esta assadeira de alumínio combina resistência, beleza e desempenho para quem ama preparar receitas deliciosas no forno. Seu revestimento antiaderente premium impede que os alimentos grudem, garantindo desenforme fácil, limpeza prática e resultados perfeitos a cada uso. Com design moderno e acabamento na cor preta, ela adiciona um toque de elegância e personalidade ao ambiente. Seu formato quadrado assegura uma distribuição uniforme do calor, proporcionando um cozimento homogêneo da massa e realçando o sabor natural dos alimentos. As bordas altas e retas foram pensadas para evitar derramamentos e oferecer maior segurança ao transportar suas receitas diretamente do forno à mesa. Ideal para assar bolos, tortas, carnes ou gratinados, essa assadeira une funcionalidade e charme, tornando-se indispensável em qualquer cozinha. Experimente preparar suas receitas favoritas com mais estilo e praticidade. Ficha Técnica Medidas e dimensões: Altura: 4cm | Largura: 25cm | Comprimento: 25cm | Capacidade: 3,15L Material do corpo: Alumínio Material da alça/cabo: Não possui Marca: Alumínio Nacional Fabricante: Alumínio Nacional Garantia: 90 dias Composição 01x Assadeira Quadrada Antiaderente', 55.9, 55.9, NULL, 'Home & Living > Kitchenware > Bakewares & Decorations', 'https://cf.shopee.com.br/file/a620327ef857e1e8ea5a4cbe6a9988b5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F359066629%2F10637994383', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10638962767', 'Abafador De Hambúrguer Profissional 14Cm Nacional', 'Eleve a performance da sua cozinha com o Abafador de Hambúrguer Profissional 14cm Nacional, feito em alumínio polido de alta qualidade pensado para quem prepara hambúrgueres de forma eficiente e saborosa no dia a dia. Com 14cm de diâmetro, esse abafador é ideal para cobrir perfeitamente seus hambúrgueres, promovendo um cozimento uniforme e rápido que mantém a suculência da carne e potencializa o sabor dos ingredientes, incluindo aquele queijo derretido perfeitamente sobre o hambúrguer. Projetado para uso intenso tanto em ambientes profissionais quanto em cozinha de casa com grande movimento, esse utensílio para hambúrguer é resistente, durável e fácil de limpar, reduzindo o tempo gasto após o preparo e garantindo mais produtividade. O design em alumínio confere longa vida útil e robustez diante de uso contínuo. O abafador também retém calor, ajudando a derreter queijo de forma homogênea e manter o suco da carne, proporcionando resultados consistentes e que impressionam clientes e familiares. Sua cozinha ganha mais agilidade no serviço e padronização no preparo, refletindo diretamente na experiência dos seus pratos. Transforme receitas simples em hambúrgueres suculentos com acabamento profissional. Adicione já ao seu fluxo de trabalho culinário esse abafador de hambúrguer indispensável e sinta a diferença no padrão de qualidade. Ficha Técnica: Medidas e dimensões: Altura: 5,6cm | Comprimento: 14,3cm Material do corpo: Alumínio polido Material da alça/cabo: Baquelite Marca: Alumínio Nacional Fabricante: Alumínio Nacional Garantia: 90 dias Composição: 01× Abafador de Hambúrguer Profissional', 44.9, 31.9, NULL, 'Home & Living > Kitchenware > Pans', 'https://cf.shopee.com.br/file/7d084a29a94b0dc4f0d22f92eb455ed1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F359066629%2F10638962767', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21999844969', 'Carrinho Bolsa Sacola Multiuso com Rodinhas Azul Bel', 'Versatilidade para o seu dia a dia! A Bolsa Sacola Multiuso com Rodinhas da Bel é 2 em 1: pode ser usada como carrinho ou como sacola comum. Compacta, funcional e resistente, é perfeita para compras rápidas, feira, academia ou pequenos transportes no cotidiano. ✔️ Capacidade de até 14 litros: espaçosa na medida certa! A sacola oferece volume ideal para o transporte de itens do dia a dia, como compras de mercado e muito mais. ✔️ Suporta até 10 kg: perfeita para levar o que você precisa sem abrir mão da mobilidade. ✔️ Rodinhas retráteis em polipropileno: as rodas podem ser dobradas quando não estiverem em uso, transformando o carrinho em uma sacola comum ✔️ Com bolsos e zíper: a praticidade está nos detalhes - bolsos extras para separar objetos menores e zíper frontal. ✔️ Fabricada em poliéster 600D – material durável conhecido por sua alta resistência a rasgos. Leve, dobrável e multiuso: a solução ideal para mais praticidade no dia a dia, com conforto.', 53.14, 53.14, NULL, 'Sports & Outdoors > Sports & Outdoor Accessories > Others', 'https://cf.shopee.com.br/file/sg-11134201-821ef-mgwdxrz03r4a44', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F757094384%2F21999844969', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58204265185', 'Ribbed Short Vermelho Hyperion Poliamida', 'Shorts Ribbed Vermelho Hyperion | Tendência Minimalista Estruturado e elegante! O Ribbed Short Vermelho Hyperion da Donna Carioca apresenta textura canelada que está em alta nas passarelas, com recortes estratégicos na cintura e cós com recorte arredondado que valorizam sua silhueta enquanto proporcionam sustentação e estrutura. Tecnologia Premium Excelência em Materiais Textura Canelada - Tecido em alta que adiciona interesse visual e estrutura Recortes Estratégicos na Cintura - Detalhes posicionados para silhueta valorizada e sustentação Costura Reforçada - Construção durável para atividades intensas Modelagem que Abraça - Abraça seu corpo sem restringir movimento Design Exclusivo Cor Vermelho Hyperion - Tom vibrante e cheio de energia para styling marcante Tag Personalizada - Detalhe personalizado para caráter exclusivo Cós com Recorte Arredondado - Valoriza e realça a silhueta Não Possui Forro - Tecnologia zero transparência COMPRE AGORA - Textura em alta para seu guarda-roupa!', 111.0, 77.7, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Bottoms', 'https://cf.shopee.com.br/file/sg-11134201-82624-mk2dmmfijxtzf9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1576910750%2F58204265185', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697503255', 'Pneu Itaro Aro 18 IT101 235/50R18 97W', '*Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores. A segurança e conforto que você procura para o seu SUV está no Itaro IT101! O desenho da banda de rodagem é simétrico, com sulcos mais largos para dissipar a água com maior velocidade, diminuindo as chances de aquaplanagem. Com baixa resistência ao rolamento, o IT101 oferece melhores condições para a economia de combustível e excelente dirigibilidade. O desenho do ombro foi otimizado para melhorar o apoio no solo, aumentar a aderência e proporcionar maior conforto com menos ruído. Sobre a marca Itaro A Itaro nasceu para motoristas viverem novas histórias - em duas ou quatro rodas. Desenvolvida nas grandes fábricas asiáticas, a marca é homologada nos principais mercados da Europa e América, como o Brasil. Seus pneus foram pensados em centros de pesquisa e desenvolvimento de países como China, Paquistão e Tailândia, que estão entre os maiores do mundo. Com presença exclusiva na PneuStore, a Itaro oferece soluções para carros de passeio, SUVs, caminhonetes, motos e caminhões, com excelente qualidade e custo que ajudam motoristas a viverem novos capítulos todos os dias. Garantia Especial Itaro A Garantia Especial Itaro foi pensada para que você possa rodar com segurança e tranquilidade, com os pneus nascidos para contar histórias. São 180 dias contra Danos Acidentais, que impossibilitem o pneu de ser reparado. Ou seja, em casos de pequenas avarias, em que há conserto constatado por um profissional indicado pela PneuStore, a troca não é aplicada. Consulte o regulamento completo acessando a nossa página de garantias: Garantia Especial Itaro.', 625.78, 581.98, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Industrial Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rd49-lveo0lwhhkmzbc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F23697503255', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793683499', 'Jogo 4 Pneus Continental Aro 15 PowerContact 2 195/60R15 88H', '*Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores. Desenvolvido para equipar carros compactos e médios, o pneu Continental PowerContact oferece qualidade de sobra para o uso diário, seja urbano ou rodoviário, com muita segurança e conforto. Possui banda de rodagem assimétrica e composto da 4ª geração de sílica, que em conjunto fazem com que o pneu tenha ampla área de contato com a pista, porém com desgaste reduzido, devido à baixa resistência ao rolamento, o que também ajuda no consumo de combustível, resultando em menor emissão de CO2 e aumento da vida útil do pneu. Sobre a marca Continental A marca Continental foi fundada em Hanover, na Alemanha em 1871. Os pneus Continental são referência mundial em desempenho e qualidade, equipando os mais modernos e sofisticados carros. São usados como pneu original de fábrica em marcas como BMW, Mercedes e Porsche, tanto com pneus comuns quanto em pneus RunFlat. Seja em pneus para carros de passeio, carros esportivos, utilitários, a Continental oferece inovações e a garantia de segurança total nos trajetos realizados.', 2454.06, 2257.74, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rble-m5vij9785v9cc4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F23793683499', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298284573', 'Conversor Rca Remoto Zendel Filtro Anti Ruido Som Automotivo', 'O CONVERSOR RCA REMOTO ZENDEL é indicado para aparelhos originais de veículos, nacionais ou importados, que não possuem saída RCA e remote para instalação de amplificadores. O aparelho funciona como conversor de baixa impedância para alta impedância (RCA).Possui sistema eletrônico de acionamento do remote através dos fios dos alto falantes originais. Permitindo em muitos casos instalar sem a necessidade de desmontar o painel, apenas instalando junto ao amplificador e conectando o fio dos alto falantes originais para a entrada do conversor. Possui filtro de anti-ruído evitando ruídos gerados pela parte elétrica do automóvel. ESPECIFICAÇÕES TÉCNICAS: • Ajuste de Ganho • Com Saída Remote • Filtro Anti Ruído • Estéreo (R + L) • Full Range • Placa em Fibra de Vidro de Alta Resistência DIAGRAMA DE INSTALAÇÃO: Entradas: • - GND: Ligar ao negativo • + 12V: Ligar ao positivo + 12 Volts • - L: Entrada de Áudio – negativo Canal Esquerdo • + L: Entrada de Áudio + positivo Canal Esquerdo • - R: Entrada de Áudio – negativo Canal Direito • + R: Entrada de Áudio + positivo Canal Direito Saídas: • RMT: Saída Remote, ligar na entrada Remote do Amplificador • Saídas RCA: Ligar nas Entradas RCA do Amplificador CONTEÚDO DA EMBALAGEM: • 1 Central de Conversor RCA Com Filtro Anti Ruído', 87.0, 83.9, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m70uuxv0nbjkbd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F411081274%2F23298284573', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20997760211', 'Jogo 2 Pneus Speedmax Aro 17.5 SPM01 235/75R17.5 143/141K 18 Lonas', 'Marca: SPEEDMAX Modelo: SPM01 Medida: 235/75R17.5 Largura: 235 Perfil: 75 Tamanho de Aro: 17.5 Índice de peso: 143 - 2725 kg, 141 - 2575 kg, 143/141 Índice de velocidade: K - 110 km/h, K Tipo de Veiculo: CARGA Tipo de terreno: URBANO RunFlat: N/A Sidewall: BSW LETRAS PRETAS Extra Load: Não Desenho: N/A UTGQ: N/A Adesão à àgua: C Eficiência energética: C Ruído externo: 71 *Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores. Sobre a SpeedMax A SpeedMax produz pneus para todos os tipos de veículo, com qualidade e custo que ao encontro com a sua busca por um pneu com ótima dirigibilidade, desempenho e economia para ter o máximo em qualquer situação - do campo ao asfalto. Pensados em Centros de Pesquisa e Desenvolvimento em países como China, Vietnã, Índia e Paquistão, a SpeedMax também tem produção feita no México e é homologada nos principais mercados, como Brasil e Estados Unidos.', 2087.77, 1883.97, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Truck Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rdxc-ly5g4v9s3rwm14', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F20997760211', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
