INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18397808482', 'Broadsword Warlord Edition Switch Midia Fisica', 'BROADSWORD WARLORD EDITION SWTICH **PRODUTO 100% ORIGINAL, LACRADO E COM NOTA FISCAL** **PRONTA ENTREGA ENVIO IMEDIATO** - Mídia: Física (disco ou cartucho no caso se for Nintendo); - Console: Compatível com Nintendo SWITCH, LITE E OLED; - Versão: Importada; - Idioma ou Áudio: Inglês; Legenda ou Texto: Inglês, Francês, Espanhol; - Jogadores: 1 a 2; CONTEÚDO DA EMBALAGEM: 1 (um) Jogo BROADSWORD WARLORD EDITION SWITCH; IMAGENS MERAMENTE ILUSTRATIVAS Todas as informações divulgadas são de responsabilidade do Fabricante/Fornecedor GARANTIA: 90 dia(s) de Garantia Produto 100% Original. A nota fiscal garante contra defeito de fabricação! **ATENÇÃO** Antes de finalizar a compra, pergunte quantas vezes for necessário e tire todas as suas dúvidas. Nossa equipe de vendedores está à disposição para auxiliar. Se não conseguir localizar o item que precisa ou se necessitar de mais alguma informação sobre o produto entre em contato conosco (GAMER HUT STORE). SOBRE O JOGO Comande um dos cinco exércitos diferentes: os ingleses, os franceses, os espanhóis, os poloneses ou os Habsburgos. Lidere diferentes tipos de unidades em batalha - de arqueiros, hussardos alados, cavaleiros, arqueiros, pikemen e catapultas com unidades especiais por nacionalidade. Controle unidades especiais de heróis como Henrique III, Joana d''Arc, Wladylaw I da Polônia e Pedro de Castela, entre outros cujos poderes especiais de "herói" podem afetar todo o campo de batalha.', 149.97, 149.97, NULL, 'Gaming & Consoles > Video Games > Switch', 'https://cf.shopee.com.br/file/sg-11134201-7rdw9-lz7pfxoksf7qb3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F594422693%2F18397808482', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45254362258', 'Yooka Replaylee PS5 Midia Fisica', 'YOOKA REPLAYLEE PS5 **PRODUTO 100% ORIGINAL, LACRADO E COM NOTA FISCAL** **PRONTA ENTREGA - ENVIO IMEDIATO** - Mídia: Física (disco ou cartucho no caso se for Nintendo); - Console: Compatível com Nintendo PS5; - Legenda ou Texto: Inglês, Francês, Espanhol, Português; - Jogadores: 1; CONTEÚDO DA EMBALAGEM: 1 (um) Jogo YOOKA REPLAYLEE PS5; IMAGENS MERAMENTE ILUSTRATIVAS Todas as informações divulgadas são de responsabilidade do Fabricante/Fornecedor GARANTIA: 90 dia(s) de Garantia - Produto 100% Original. A nota fiscal garante contra defeito de fabricação! **ATENÇÃO** Antes de finalizar a compra, pergunte quantas vezes for necessário e tire todas as suas dúvidas. Nossa equipe de vendedores está à disposição para auxiliar. Se não conseguir localizar o item que precisa ou se necessitar de mais alguma informação sobre o produto entre em contato conosco (GAMER HUT STORE). SOBRE O JOGO Yooka-Replaylee é a versão definitiva, remasterizada e aprimorada do aclamado jogo indie de plataforma 3D com elementos de coleta, Yooka-Laylee (2017). Novos desafios remixados e favoritos antigos aguardam você enquanto explora os vastos e belos mundos abertos com a dupla inseparável Yooka (o verde) e Laylee (a roxa), tudo isso embalado por uma linda trilha sonora orquestral. E tem mais: agora tem mapa! Uma nova moeda brilhante? E diversas opções de personalização? A dupla favorita nunca se moveu, pareceu ou soou tão bem! O magnata Capital B está em uma missão para roubar todos os livros do mundo e transformá-los em dinheiro vivo. MAS o livro mais poderoso do universo está bem debaixo do seu nariz no vizinho Shipwreck Creek, lar da nossa dupla aventureira, Yooka e Laylee! Ao verem seu livro mais precioso roubado, eles embarcam em uma aventura maluca por diversos mundos fantásticos e imaginativos, repletos de personagens cativantes e um tesouro de itens colecionáveis ​​brilhantes. Você consegue encontrar todas as Páginas mágicas do livro e salvar o dia?', 299.89, 299.89, NULL, 'Gaming & Consoles > Video Games > Playstation', 'https://cf.shopee.com.br/file/sg-11134201-8262l-mj8kvaqaatxcd7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F594422693%2F45254362258', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
