INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22699290501', 'Wella Professionals Invigo Nutri-enrich Frizz Control - Leve-in 150ml', 'Leave-in para cabelos secos, ressecados ou quimicamente tratados. Wella Professionals Invigo Nutri-Enrich Frizz Control traz uma carga de nutrientes que atuam no alinhamento e maleabilidade dos fios. O Leave-in Wella Professionals Invigo Nutri-Enrich é composto por um blend de nutrientes multifuncionais que restauram a maciez, o brilho e a saúde do cabelo. Além disso, ele conta com uma fragrância luxuosa Frutal Chipre Almiscarado, para uma íncrível experiência aromática. Como usar: Aplique o leave-in sobre os fios limpos e úmidos. Distribua pelo comprimento e pontas de maneira uniforme, massageando mecha a mechas. Finalize como preferir, sem enxaguar. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 136.9, 136.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-8261r-mk4aks2tuiv95d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F22699290501', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
