INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897087144', 'Rack c/ Painel para Tv até 50'' Ohio Carraro Preto', 'Projetado para quem busca estilo e funcionalidade, o Conjunto de Sala de Estar Ohio da Carraro é a escolha perfeita para criar um espaço contemporâneo e dinâmico. Combinando a elegância do MDP com a robustez dos tubos de aço, este conjunto exala um charme industrial que transformará completamente o visual do seu ambiente. O conjunto é composto por dois elementos distintos: o Painel de Parede 1123 e a Bancada 1290. Essa combinação oferece infinitas possibilidades de configuração, permitindo que você crie arranjos personalizados de acordo com seu gosto e necessidade. Além disso, a Bancada 1290 não só é funcional como superfície de apoio, mas também pode atuar como um divisor de ambientes, graças ao seu acabamento impecável na parte traseira. Isso proporciona uma versatilidade extra, permitindo que você defina espaços sem comprometer a estética ou a qualidade do mobiliário. Seja para otimizar o espaço, dar um toque de modernidade ou criar uma atmosfera única, o Conjunto Ohio é a solução perfeita para quem busca um ambiente sofisticado, contemporâneo e altamente funcional. Adquira agora e transforme sua sala de estar no espaço dos seus sonhos! Especificações do Painel de Parede: Medidas: Largura: 150 cm | Altura: 80 cm | Profundidade: 14,5 cm Peso: 17,2 Kg Matéria Prima: MDP Prateleiras: 3 (3 Nichos) Especificações da Bancada: Medidas: Largura: 150 cm | Altura: 50 cm | Profundidade: 43 cm Peso: 19,7 Kg Matéria Prima: MDP Pés em tubo de aço retangular Prateleiras: 1 Nicho inferior', 989.99, 760.85, NULL, 'Home & Living > Furniture > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rbkd-lncuipj2g6ggc3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F952014476%2F23897087144', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259451667', 'H2OH Limoneto', 'A H2OH! Limoneto 350 ml chega como uma brisa embalada em sua nova versão em lata: leve, cintilante e com o toque cítrico que desperta o paladar sem pesar. A combinação equilibrada entre água gaseificada e sabor de limão ganha ainda mais praticidade e frescor, tornando-se a companhia ideal para quem busca uma bebida suave, portátil e deliciosamente refrescante. Perfeita para o trabalho, para o almoço rápido ou para aquele instante em que a tarde pede um gole de leveza, agora com todo o charme e conveniência da lata.', 3.79, 3.09, NULL, 'Food & Beverages > Beverages > Carbonated Drinks & Tonics', 'https://cf.shopee.com.br/file/sg-11134201-81zwl-micjnnmyhbswdc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555057%2F58259451667', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20099567819', 'Kit Kombi Educativa + Cubo Educativo | Acompanha12 Peças de Encaixar | Carrinho Meninos +12 Meses | INMETRO | QUEEN SHOP', 'Kit Kombi Educativa + Cubo Educativo com 12 Peças de Encaixar Diversão em dobro para brincar, explorar e aprender! Este kit combina dois brinquedos coloridos e interativos que estimulam o desenvolvimento infantil de forma leve e divertida. A Kombi Educativa mede aproximadamente 29 cm e acompanha 6 peças geométricas. Além das aberturas de encaixe, possui rodas móveis para a criança brincar de empurrar, criar trajetos e inventar diferentes aventuras. O Cubo Educativo mede aproximadamente 10 cm e também acompanha 6 peças geométricas, com aberturas em diferentes formatos para a criança encontrar o encaixe correspondente. Benefícios do kit Estimula a coordenação motora; Auxilia no reconhecimento de cores e formas; Desenvolve o raciocínio e a percepção espacial; Trabalha a atenção e a concentração; Incentiva a criatividade e a imaginação; Oferece diferentes maneiras de brincar. Conteúdo da embalagem 1 Kombi Educativa; 1 Cubo Educativo; 12 peças de encaixar. Medidas aproximadas Kombi Educativa: 29 cm; Cubo Educativo: 10 cm. As cores das peças e dos produtos podem variar conforme o modelo escolhido e a disponibilidade. Um kit completo, colorido e educativo, excelente para presentear e transformar cada brincadeira em uma nova descoberta.', 49.9, 38.9, NULL, 'Mom & Baby > Toys > Toy Vehicles', 'https://cf.shopee.com.br/file/br-11134207-820lh-mr07e6aoc4xz2b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1007842724%2F20099567819', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
