INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593608781', 'Kit 2un Creme Dental Closeup Fresh Action Red Hot Em Gel 130g', 'Pasta De Dentes Closeup Fresh Action Red Hot Em Gel 130g Principais Características: - Sensação Refrescante e Duradoura: A formulação em gel proporciona uma sensação de frescor imediato e duradouro, combatendo o mau hálito de forma eficaz. - Branqueamento e Limpeza Profunda: Remove manchas superficiais dos dentes e limpa profundamente, deixando um sorriso mais branco e brilhante. - Proteção Completa: Contém ingredientes que protegem contra cáries, gengivite e outros problemas bucais. Benefícios: - Frescor prolongado ao longo do dia. - Melhora na confiança ao conversar de perto. - Prevenção de problemas bucais comuns. Diferenciais do Produto: - Tecnologia Avançada: Utiliza uma combinação de ingredientes que não só limpam, mas também ajudam a proteger e fortalecer os dentes. - Aroma e Sabor Agradável: O sabor Red Hot é uma combinação única que torna a escovação uma experiência agradável e revitalizante. - Embalagem Prática: Tubo de 130g com tampa flip-top para fácil abertura e dosagem adequada. Especificações Técnicas: - Peso: 130g Instruções de Uso: - Aplique uma quantidade adequada de gel na escova de dentes. - Escove todos os dentes por, pelo menos, dois minutos, duas vezes ao dia. - Enxágue bem a boca após a escovação. Avisos e Precauções: - Manter fora do alcance de crianças. - Não ingerir. - Em caso de irritação, suspender o uso e consultar um dentista. O que está incluso? - 2 Tubos de Pasta de Dentes Closeup Fresh Action Red Hot em Gel 130g DÚVIDAS FREQUENTES Os produtos são originais? Sim. Todos os nossos produtos são originais. Emitem nota fiscal? Sim. Emitimos nota fiscal para todos os pedidos.', 32.49, 24.29, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/br-11