INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43169066405', 'Repetidor Roteador Wi-Fi 1200Mbps Amplificador de Sinal Forte 8 Antenas Wireless Knup KP-RW408G', 'Repetidor WiFi Knup KP-RW408G oferece conexão estável e alcance ampliado para seu ambiente, com tecnologia avançada e design compacto. Compatível com múltiplos modos de operação repetidor, roteador e ponto de acesso, garante versatilidade e facilidade na instalação. Equipado com 8 antenas que reforçam o sinal, proporciona cobertura eficaz de até 300 metros ao ar livre e 100 metros em ambientes internos, adaptando-se às necessidades do usuário. Com suporte às bandas de 2.4GHz e 5GHz e padrões IEEE802.11ac/n/g/b/a, oferece velocidades somadas de até 1200 Mbps (300 Mbps em 11n e 867 Mbps em 11ac), garantindo navegação rápida e estável. A configuração é simples, com conexão rápida via WPS, e a compatibilidade ampla assegura funcionamento com diversos dispositivos. ESPECIFICAÇÕES: - Marca: Knup - Modelo: KP-RW408G - Banda de Frequência: 2.4GHz / 5GHz - Potência: 802.11b: 17dBm ± 2dBm; 802.11g: 14dBm ± 2dBm; 802.11n: 14dBm ± 2dBm; 802.11ac: 12dBm ± 2dBm - Velocidade: até 1200 Mbps (300 Mbps em 11n + 867 Mbps em 11ac) - Alcance: 300m externo / 100m interno (varia conforme ambiente) - Modos: Repetidor, Roteador, Ponto de Acesso - Antenas: 8 antenas para sinal forte - Tamanho: 100mm (altura) x 95mm (comprimento) x 100mm (largura) - Tomada: EU CONTEÚDO: 01 Repetidor WiFi Knup KP-RW408G', 138.5, 116.88, NULL, 'Computers & Accessories > Network Components > Repeaters', 'https://cf.shopee.com.br/file/sg-11134201-824he-meob4zolmsqu71', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373745451%2F43169066405', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201148998', 'Kit Sangria Freio Hidráulico GTA', 'Kit de Sangria para Freio Hidráulico GTA 10923 O Kit de Sangria GTA 10923 é a solução ideal para manutenção completa de sistemas de freio hidráulico de bicicletas. Projetado para oferecer praticidade e eficiência, ele permite realizar a sangria, remover bolhas de ar e substituir o fluido de maneira precisa, garantindo um sistema de frenagem mais seguro e responsivo. Compatível com uma ampla variedade de sistemas, o kit atende desde bikes de entrada até modelos avançados, sendo uma excelente opção para oficinas, mecânicos e ciclistas que realizam manutenção própria. Compatibilidade: Compatível com freios GTA, SRAM, Shimano, Avid, Magura, Hayes, Tektro, Formula, entre outros modelos que utilizam fluido mineral ou DOT (conforme adaptadores disponíveis). Especificações do Produto Modelo: Kit de Sangria Freio Hidráulico Finalidade: Purga e manutenção de sistemas de freio hidráulico Material dos componentes: Plástico resistente, borracha e metal Marca: GTA', 157.9, 107.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-8225q-mhktk8lxk2rm5f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F813601541%2F58201148998', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
