INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20099840806', 'Rack Rivoli 100% MDF 2 Portas 1 Nicho e Pés Estilo Retrô', 'O Rack Rivoli 100% MDF 2 Portas 1 Nicho e Pés Estilo Retrô é perfeito para compor sua sala com charme e organização. Fabricado em 100% MDF, oferece espaço para eletrônicos e objetos decorativos. Acabamento: Pintura U.V. Touch com 7 camadas de proteção, garantindo proteção e beleza duradoura. Largura: 1,92m Altura: 64,2cm e Profundidade: 38,4cm. Destaques: Fabricante: MH Móveis Acabamento com pintura U.V. Touch com 7 camadas de proteção Design Moderno 2 Portas Basculantes Acabamento Soft 45o Suporta TV?s de até 60 polegadas 5 Pés Dimensões Totais: Altura 642cm Largura 1924m Profundidade 384m Garantia: 6 Meses Contra defeitos de Fabricação', 805.64, 684.8, NULL, 'Home & Living > Furniture > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdyf-mbwitk3s9ua58a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1573190120%2F20099840806', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56253240387', 'Vestido Feminino Infantil Pequena Florista', 'Descrição: Vestido Feminino Infantil Pequena Florista Vestido em polifléx 96% poliéster e 4% elastano. Possui cor vermelha com estampa rotativa de flores, gola em V, manguinhas estilo princesa e leves babados super delicados para a sua menina! Tudo pensado e produzido com muito amor e carinho. Selecionamos os melhores materiais para crianças que desejam ser destaque por onde passam! Guia de Tamanhos Como medir a criança? Utilizando uma fita métrica, envolva as regiões a serem medidas. Busto: Enrole a fita métrica em torno do corpo, na linha do peito. Comprimento: Comece pelo topo do ombro e meça até chegar no comprimento desejado. Quando for calça, short ou saia, comece medindo na linha da cintura. Cintura: Enrole a fita métrica em torno da cintura, sem apertar. As medidas da tabela abaixo são referentes á parte frontal da peça, então busto e cintura você deve multiplicar por 2. A tabela pode sofrer alterações de 1 á 2 cm para mais ou menos, leve isso em conta na hora de selecionar o tamanho adequado. Características: - Estação: Verão - Gênero: Feminino - Tecido Peça: Cotelê e Poliflex - Composição: 96% Poliéster 4% Elastano - Faixa Etária: 1 à 12 anos - Garantia: 1 Mês - Tipo de Roupa: Vestido - Tabela de Medidas: Tabela de Medidas Vestido: Tamanho | Busto | Comprimento 2 | 25CM | 50CM 3 | 27CM | 56CM 4 | 30CM | 59CM 6 | 32CM | 62CM 8 | 34CM | 66CM 10 | 37CM | 69CM 12 | 39CM | 73CM', 39.9, 29.9, NULL, 'Baby & Kids Fashion > Girl Clothes > Dresses', 'https://cf.shopee.com.br/file/sg-11134201-81zwh-midfegqqlsznee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F717393801%2F56253240387', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393347521', 'Pneu 180/65b16 Traseiro Metzeler Cruisetec Reinf Sem Câmara', 'Pneu Traseiro.: 180/65B16 81H Modelo: Cruisetec Reinf Marca: Metzeler Índice de Carga: 81 (462kg) Índice de Velocidade: H (210km/h) Uso: Sem câmara -------------------------------------------------------- Antes de finalizar a compra, confira as medidas que sua moto está utilizando atualmente! Aguardamos a sua compra! -------------------------------------------------------- * NÃO ACOMPANHA RODA -------------------------------------------------------- Garantia de 5 anos somente por defeitos de fabricação, ficando inválida em caso de danos por acidentes, buracos na pista, mau uso e ainda má instalação. É necessário e indispensável instalar o pneu com um profissional especializado.', 2042.69, 1904.19, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Tires', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m0kol3vo2aaob2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1311725041%2F22393347521', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201985996', 'Salame Tipo Italiano Fatiado Seara Gourmet', 'Salame tipo italiano fatiado Seara Gourmet, perfeito para aperitivos e lanches rápidos. Produzido artesanalmente com cortes nobres de carne suína e especiarias naturais selecionadas, já vem fatiado para sua praticidade.', 15.99, 15.99, NULL, 'Food & Beverages > Bakery > Others', 'https://cf.shopee.com.br/file/sg-11134201-82585-mqnekz8cpixb7d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554774%2F58201985996', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23197731851', 'HIPOGLÓS POMADA COM 40G AMÊNDOAS', 'Hipoglós é indicado para: Proteger a delicada pele do bebê das assaduras que são causadas pelo contato das fezes e urina com a pele do bebê.', 49.93, 49.93, NULL, 'Mom & Baby > Baby Healthcare > Baby Skincare', 'https://cf.shopee.com.br/file/sg-11134201-7rdvr-lz7n0uzc1mzu33', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1251200960%2F23197731851', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43973376395', 'Ring Light 10 Polegadas Pau de Selife Tripé Controle Remoto Bluetooth Oberon OR-1685', 'Ring Light com Bastão para Selfie Oberon OR-1685 oferece iluminação profissional e praticidade em um único produto. Ideal para gravações, fotos e transmissões ao vivo, combina um anel de luz de 10 polegadas com bastão retrátil, proporcionando versatilidade em qualquer situação. Possui três modos de cor ajustáveis (branco frio, branco quente e branco morno), além de rotação de 360° e inclinação de 180°, garantindo o melhor ângulo em cada uso. Com controle remoto via Bluetooth recarregável e entrada Tipo C, oferece total liberdade de movimento com alcance de até 10 metros. Compatível com dispositivos Android e iOS, é resistente, leve e fácil de transportar. ESPECIFICAÇÕES: - Modelo: OR-1685 - Tamanho do ring light: 10 polegadas - Alimentação: 5V DC / 1A - Bateria do ring light: 1200 mAh - Bluetooth: 5.2 - Alcance do Bluetooth: até 10 metros - Comprimento da haste: 33,5 cm a 2,3 m - Bateria do controle: 125 mAh - Conexão: Tipo C - Compatível com Android e iOS - Modos de luz: branco frio, branco quente, branco morno - Rotação: 360° - Inclinação: 180° - Composição: Termoplásticos e metal CONTEÚDO: 01 Ring Light com bastão retrátil 01 Controle remoto recarregável 01 Cabo USB Tipo C', 149.5, 118.53, NULL, 'Mobile & Gadgets > Accessories > Selfie Accessories', 'https://cf.shopee.com.br/file/sg-11134201-824hm-mfmk56szoh712f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373745451%2F43973376395', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43201853225', 'Kit 2 Bíblias Sagrada Com Harpa Tamanho Médio Palavra de Deus em Azul e Palavra de Jesus em vermelho', 'Bíblia Sagrada, com a linguagem na versão ARC (Almeida Revista e Corrigida) de João Ferreira de Almeida. Sendo a versão mais utilizada pelos evangélicos do Brasil. Com sua fidelidade traduzida dos textos originais pelo missionário português João Ferreira de Almeida. Além disso, conta com tecnologia full color: Promessas em destaque, palavras de Deus em azul e palavras de Jesus em vermelho. A Bíblia também inclui mapas coloridos, que enriquecem o entendimento geográfico e histórico dos acontecimentos bíblicos. • Capa Dura • Almeida Revista e Corrigida (ARC) • Harpa Avivada e Corinhos • Tamanho: 12 x 15,2cm • 1236 Páginas • Letra Maior • Full Color • Mapas Coloridos • Promessas em destaque • Palavra de Deus em Azul e Palavra de Jesus em vermelho', 54.99, 49.5, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ma32iyv2lgzd49', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F651108134%2F43201853225', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27140670627', 'Bíblia Sagrada Tamanho Grande NVI Capa Dura Flores Rosa', '*Medida: 15x22 *Papel Pardo *Letras Gigantes Bíblia Sagrada, com a versão NVI (Nova Versão Internacional). Uma das mais modernas traduções que valoriza a clareza do texto, permanecendo fiel aos Escritos originais. Proporciona ao leitor uma linguagem mais atual e fluente. Incluindo panorama bíblico, mapas e também possuí índice. O projeto de tradução para a língua portuguesa começou em 2000, a partir de uma reunião da comissão da Sociedade Bíblica Internacional. Um grupo formado por respeitados estudiosos brasileiros e de outros países foi reunido para produzi-la. Este projeto durou quase uma década. Muitos acham que é apenas uma tradução da americana, porém erram ao pensar assim, pois a versão em português foi feita no Brasil. O propósito dos idealizadores da NVI foi fazer um texto que se definisse por quatro elementos: precisão, clareza, beleza de estilo e dignidade. Com uma linguagem clara e mais próxima da atualidade, sem perder a beleza do estilo da linguagem bíblica. Cercada de elogios por conta do compromisso que conseguiu manter com os Escritos originais, esta versão da Bíblia já vendeu milhões de exemplares nos últimos anos, e vem se popularizando cada vez mais.', 31.99, 29.76, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-81z1k-me04t24gqpkx95', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F651108134%2F27140670627', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58258885631', 'Chuteira Umbro Techno II Futsal Indoor Quadra Antiderrapante Controle Conforto', 'A Chuteira Umbro Techno II Futsal é ideal para jogadores que buscam controle, estabilidade e conforto nas quadras. Desenvolvida para futsal indoor, oferece excelente aderência e precisão nos movimentos, garantindo mais segurança durante o jogo. Seu cabedal em material sintético resistente proporciona maior durabilidade e melhor contato com a bola, favorecendo o domínio, passes e finalizações. O ajuste com cadarço garante firmeza e segurança em mudanças rápidas de direção. A entressola leve auxilia na absorção de impacto, proporcionando mais conforto durante as partidas. Já o solado em borracha antiderrapante foi projetado para quadras lisas, garantindo tração eficiente e estabilidade. Destaques do produto: Ideal para futsal (quadra indoor) Solado antiderrapante com excelente tração Cabedal resistente e durável Melhor controle de bola Conforto durante o jogo Design esportivo moderno Ficha técnica: Marca: Umbro Modelo: Techno II Futsal Categoria: Futsal / Indoor Material do cabedal: Sintético resistente Forro: Têxtil acolchoado Palmilha: Macia e confortável Entressola: Leve com absorção de impacto Solado: Borracha antiderrapante Tipo de ajuste: Cadarço Indicado para: Futsal / quadras indoor Gênero: Masculino / Unissex (varia conforme versão) Origem: Nacional', 199.9, 119.94, NULL, 'Sports & Outdoors > Sports Footwear > Futsal Shoes', 'https://cf.shopee.com.br/file/sg-11134201-81zvv-mn2wzlzpglxfd8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1191965739%2F58258885631', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23494779370', 'Chinelo Fila Drifter Basic Masculino Casual Confortável Solado Borracha Antiderrapante Original', 'Chinelo Fila Drifter Basic Masculino: Conforto e Estilo para o Dia a Dia O Chinelo Fila Drifter Basic Masculino é a escolha ideal para quem busca conforto e estilo em seus momentos de lazer. Projetado para proporcionar uma experiência de uso leve e macia, este chinelo masculino Fila combina design funcional com amortecimento superior, tornando-o perfeito para diversas ocasiões. Confeccionado em EVA, o Chinelo Fila Drifter Basic oferece uma sensação de leveza e maciez inigualáveis. Sua tira única na região do médio-pé garante sustentação e um calce seguro, enquanto a palmilha anatômica e o solado em EVA trabalham em conjunto para proporcionar excelente amortecimento a cada passo. O nome da marca Fila é estampado em destaque na tira, adicionando um toque de autenticidade e reconhecimento ao seu visual. Este chinelo confortável masculino é versátil e ideal para piscina, praia, momentos casuais e de lazer, ou simplesmente para curtir o dia a dia com máximo bem-estar. Desfrute da combinação perfeita de praticidade, durabilidade e o reconhecido padrão de qualidade Fila. Características Técnicas Gênero: Masculino Faixa Etária: Adulto Material do Cabedal: Sintético Material da Palmilha: EVA Material do Solado: EVA Tecnologia do Solado: Amortecimento Indicação de Uso: Piscina, praia, momentos casuais e de lazer, dia a dia Código do Fabricante: 11A017X', 159.9, 127.92, NULL, 'Men Shoes > Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/sg-11134201-8262p-mjfplll1u1hh65', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1191965739%2F23494779370', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
