INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21997368853', 'Encrespando A Juba Creme De Pentear Cachos Hidratante 1 Litro', 'A linha de tratamento juba foi especialmente desenvolvida para as necessidades dos cabelos cacheados (3a, 3b e 3c) e crespos (4a, 4b e 4c), proporcionando brilho, definição e hidratação aos fios. Com seus ativos 100% vegetais, promove emoliência, atuando no interior da fibra capilar. Rico em ômega 3 e 6, auxilia no condicionamento e brilho acetinado, além de manter a definição por até 48 horas. Acha que acabou tem mais segura esses ativos: Manteiga de murumuru orgânica - promove ação hidratante e restauradora dos fios Óleo de linhaça dourada - rico em ômega 3 e 6, proporciona condicionamento e brilho acetinado', 63.99, 63.99, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rbkf-llaugjiynqz6dc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F602117686%2F21997368853', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
