INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58212837972', 'Tênis Fila Fastness Preto Rosa e Verde Limão - Feminino', 'Estilo vibrante e desempenho que impulsiona cada passada! Tênis Fila Fastness Preto Rosa e Verde Limão - Feminino Ficha Técnica: Marca: Fila Cor: Preto, rosa e verde limão Cabedal: Mesh respirável com texturas e pontos variados Gênero: Feminino Palmilha: Têxtil Sola: Emborrachada nas regiões traseira e frontal Fechamento: Cadarço Amortecimento: Macio Estabilidade: Neutro Tecnologias: Energized Plus - proporciona conforto, maciez e alta responsividade Entressola: EVA com tecnologia Energized Plus Indicação: Corridas Detalhes: Design moderno com peças volumétricas e cores vibrantes O Tênis Fila Fastness foi criado para mulheres que desejam ir além nas corridas e manter o estilo em alta. Porque investir: Seu cabedal com textura em mesh garante respirabilidade e leveza, enquanto a entressola com tecnologia Energized Plus impulsiona cada passo com conforto e resposta. O visual moderno, com cores marcantes, completa o look esportivo com atitude e energia. Conteúdo da embalagem: 1 par de Tênis Fila Fastness Preto Rosa e Verde Limão - Feminino', 349.99, 226.99, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-824gz-mpnsd7phzytqae', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1614877278%2F58212837972', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22536889154', 'Tampa Reservatório Água Renault Laguna Trafic Twingo TC6400', 'Tampa do Reservatório de Água do Radiador TanClick TC6400 – Renault Laguna, Trafic Express e Twingo – Válvulada 1.10 a 1.60 Bar Controle correto da pressão do sistema de arrefecimento é fundamental para o funcionamento seguro do motor. A Tampa do Reservatório de Água do Radiador TanClick TC6400 foi desenvolvida para garantir vedação eficiente e controle adequado da pressão no sistema de arrefecimento, evitando vazamentos, superaquecimento do motor e perda de eficiência do líquido refrigerante. Equipada com válvula calibrada entre 1.10 e 1.60 bar, a tampa mantém a pressão ideal no sistema, permitindo que o motor trabalhe na temperatura correta e protegendo componentes como radiador, mangueiras e reservatório contra danos causados por excesso de pressão. Fabricada em plástico de alta resistência, oferece excelente durabilidade, resistência a altas temperaturas e vedação confiável, sendo ideal para reposição com padrão equivalente ao original. Veículos compatíveis Aplicação em veículos Renault Laguna Trafic Express Twingo Dica: sempre verifique a referência da peça original antes da instalação para garantir compatibilidade. Especificações técnicas Modelo: TC6400 Tipo: Tampa do reservatório do radiador Sistema de Fixação: Rosca Pressão da válvula: 1.10 a 1.60 bar Material: Plástico Cor: Cinza Referência Original: 7700805032 Marca: TanClick Principais benefícios da Tampa TanClick Mantém a pressão correta do sistema de arrefecimento Evita vazamentos do líquido do radiador Ajuda a prevenir superaquecimento do motor Fabricada com material resistente a altas temperaturas Excelente vedação e durabilidade Produto com padrão de reposição confiável Conteúdo da embalagem 1 Tampa do reservatório de água do radiador Sobre a marca A TanClick desenvolve componentes automotivos com foco em qualidade, durabilidade e segurança, oferecendo soluções confiáveis para o sistema de arrefecimento dos veículos. TanClick – Tecnologia para seu carro, segurança para você. Garanta o funcionamento correto do sistema de arrefecimento do seu veículo com a Tampa do Reservatório do Radiador TanClick TC6400. Mais segurança, proteção e confiabilidade para o motor.', 25.0, 25.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7qvfw-lfa5i65k3avgbf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F552700125%2F22536889154', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
