INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20897686632', 'HARRY POTTER E A CÂMARA SECRETA', 'HARRY POTTER E A CÂMARA SECRETA Depois de férias aborrecidas na casa dos tios trouxas, está na hora de Harry Potter voltar a estudar. Coisas acontecem, no entanto, para dificultar o regresso de Harry. Persistente e astuto, o herói não se deixa intimidar pelos obstáculos e, com a ajuda dos fiéis amigos Weasley, começa o ano letivo na Escola de Magia e Bruxaria de Hogwarts. As novidades não são poucas. Novos colegas, novos professores, muitas e boas descobertas e um grande e perigosos desafio. Alguém ou alguma coisa ameaça a segurança e a tranquilidade dos membros de Hogwarts.. Informações Adicionais Autor: ROWLING, J.K. Data Publicação: 30/12/1899 Tipo de capa: CAPA DURA Condição do Item: Novo Subtitulo: HARRY POTTER E A CÂMARA SECRETA Idioma: PORTUGUES Páginas: 224 Edição: 1 ISBN-13: 9788532530790 ISBN-10: 8532530796', 69.9, 55.92, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-7rcev-lr6fp8mefym75c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F20897686632', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
