INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13990943760', 'Kit Canaleta Pestanas Interna E Externa Brasilia Variant 2', 'Kit Canaleta + Pestanas Interna e Externa – Brasília / Variant – 2 Portas O Kit de Canaleta e Pestanas Interna e Externa para Volkswagen Brasília e Variant 2 Portas é fabricado em material de alta qualidade, garantindo encaixe perfeito, vedação eficiente e funcionamento suave dos vidros. Esse kit é ideal para reposição completa, pois reúne as canaletas do vidro e as pestanas interna e externa, protegendo contra entrada de água, poeira e ruídos, além de preservar o acabamento original das portas. Produto novo, desenvolvido no padrão original de fábrica, sem necessidade de adaptações. Compatibilidade: Volkswagen Brasília – 2 Portas Volkswagen Variant – 2 Portas (Aplicação completa nas portas: canaleta do vidro + pestana interna e externa.) Características: Inclui canaleta + pestana interna + pestana externa Excelente vedação e durabilidade Auxilia no deslizamento correto do vidro Encaixe perfeito, padrão original VW Produto novo Conteúdo da Embalagem 1 Kit de Canaleta do Vidro 1 Kit de Pestanas Internas 1 Kit de Pestanas Externas', 94.1, 84.69, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/cde0290bb6489d86882145f94bfa90b9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F691145803%2F13990943760', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22499307445', 'Niina Secrets Pocket Pink Espelho Led', 'Tenha sempre em mãos o melhor espelho para te acompanhar em todos os momentos. Espelho Pocket Pink Led Niina Secrets é compacto e cheio de charme, possui luzes de LED que garantem uma visão clara e iluminada. Feito para levar na bolsa e garantir uma maquiagem impecável em qualquer lugar: Luzes de LED que proporcionam uma iluminação clara e uniformeCompacto e com a alça giratória em 360ºBateria recarregável de longa duraçãoAcompanha cabo USB O Espelho Pocket Pink Led Niina Secrets é o acessório ideal para quem busca praticidade e estilo na hora de cuidar da beleza. Pensado para ter sempre por perto e garantir um visual impecável em qualquer ocasião. Niina Secrets é a linha de maquiagem e skincare de Eudora, feita em parceria com a influencer e empresária Niina Secrets, com o intuito de revolucionar a beleza com tecnologia e muita inspiração. Os produtos - dentre eles base, batom, blush, corretivo, iluminador, paletas completas, itens de skincare e até esponja - foram cocriados aliando tendências e diversidade, para te acompanhar no dia a dia, te tornando a sua melhor versão possível. Cuide de você com os produtos Eudora Niina Secrets, transbordando a sua personalidade. Nenhum produto Eudora é testado em animais, ou seja, este item possui selo Cruelty Free. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 119.9, 119.9, NULL, 'Beauty > Beauty Tools > Makeup Accessories', 'https://cf.shopee.com.br/file/sg-11134201-82629-mjyipx52r1twa7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1679511787%2F22499307445', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
