INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253302083', 'Eudora Base Líquida Niina Secrets Hidra Glow Cor 65 30ml', 'A Base Líquida Niina Secrets Hidra Glow é a base que hidrata e deixa sua pele radiante! Niina Secrets Hidra Glow contém ácido hialurônico de última geração que deixa a pele hidratada, radiante como uma pétala, deixando um viço natural sem deixar oleosa. Possui cobertura média, permite construção de camadas sem craquelar e acumular nas linhas faciais, e deixa uma sensação confortável na pele. Sua textura é surpreendente e sua fragrância exclusiva é encantadora. Com Dupla proteção: Protege contra luz azul (luz do seu computador ou celular) e FPS16/UVA+++. São 17 tons de base que representam a diversidade brasileira. A exclusiva tecnologia Secrets combina Óleo de rosas e vitaminas, que nutre a pele, possui ação antioxidante e auxilia a formação de colágeno. Benefícios: -Nutre a pele. -Efeito antioxidante. -Auxilia a formação do colágeno. *Resultado obtidos através de teste de eficácia percebida. Complete seu Nécessaire com a nossa linha de Corretivo e arrase com sua make. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 94.99, 94.99, NULL, 'Beauty > Makeup > Eyes', 'https://cf.shopee.com.br/file/sg-11134201-82628-mjho9y8xrs3k20', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1679511787%2F58253302083', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
