INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17224837587', 'Kit 6 Porta Fusível Montagem Permak P/ Fusível Max', 'É melhor prevenir do que remediar. E para prevenir problemas no seu sistema de som automotivo, nada melhor do que utilizar fusíveis para garantir o máximo de proteção contra curtos-circuitos. Para isso, invista neste Porta Fusível da Permak que alia qualidade superior e o melhor custo-benefício que você vai encontrar. Possui carcaça super resistente em nylon e sua montagem é feita de forma precisa e simples através de encaixes. Conta ainda com proteção anti-chamas e capacidade para um fusível lâmina max. Garanta já o seu! Especificações Técnicas: • Para uma Tensão Não Superior a 1.000V • Conectores em Material de Alta Condutividade • Confeccionado em Nylon de Alta Resistência • Anti-Chamas • Resistente ao Calor • Acabamento Perfeito • Exelente durabilidade • Encaixes Práticos e de Precisão Conteúdo da Embalagem: • Kit Com 6 Porta Fusível Max Permak Importante: • Garantia de 90 Dias.', 29.32, 27.56, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Tools > Others', 'https://cf.shopee.com.br/file/3242ae1bc19b50aa3e2a8da3c85b3db5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F463375702%2F17224837587', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
