INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21598312435', 'Neutrogena Deep Clean C/25 Lenços De Limpeza Demaquilante', '*Produto Original* *Atenção:* Venda exclusiva para pessoa física. Pedidos com CNPJ serão cancelados. O que é e para que serve? Lenços demaquilantes que limpam profundamente removendo impurezas, oleosidade e maquiagem, inclusive à prova d''água, deixando uma sensação refrescante na pele. Com textura ultra macia, podem ser usados até para a área delicada dos olhos. Benefícios e diferenciais -Limpa profundamente removendo impurezas da pele -Remove a maquiagem com apenas 1 lenço -Sensação refrescante na pele após o uso -Hidratação por 24 horas -Oil free: não deixa resíduos oleosos -Hipoalergênico, oftalmológica e dermatologicamente testado Como usar Com movimentos suaves, passe o lenço de limpeza sobre a pele do rosto e área dos olhos. Não é necessário enxaguar. Para evitar o ressecamento do produto, mantenha o lacre adesivo da embalagem fechado. Composição Aqua, Cetyl Ethylhexanoate, Isostearyl Palmitate, Hexylene Glycol, Pentaerythrityl Tetraethylhexanoate, Isononyl Isonopanoate, Glycerin, PEG-6 Caprylic/Capric Glycerides, Sucrose Cocoate, Phenoxyethanol, Chlorphenesin, Carboner, Tocopheryl Acetate, Parfum, Sodium Hydroxide, Tela não tecida. Precauções Uso externo. Não aplicar sobre a pele lesada ou irritada. Em caso de irritação ou alergia, suspenda o uso. Conserve fora do alcance das crianças, em local fresco e seco.', 35.26, 35.26, NULL, 'Beauty > Makeup > Makeup Removers', 'https://cf.shopee.com.br/file/sg-11134201-824hl-mfcyj8bcwiyxb2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1458515228%2F21598312435', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20641669992', 'Piscina Retangular 5000 Litros Estruturada Premium Mor', 'Piscina Retangular 5000 Litros Estruturada Premium Mor A Piscina Premium de 5.000 litros Mor tem detalhes únicos que vão proporcionar uma diversão segura para toda família, sendo a melhor opção para quem quer curtir ao máximo os prazeres da água!Com estrutura resistente à fortes impactos, sua lona monocromática azul possui tripla camada: duas lâminas de PVC com uma trama de poliéster entre elas. Seus exclusivos esquineiros na cor verde-maçã garantem mais firmeza, facilidade ao montar e também um melhor acabamento. As escoras da Piscina são pintadas em epóxi à pó na cor branca, garantindo ainda mais durabilidade, além do design moderno e inovador. Tudo para proporcionar mais praticidade durante sua manutenção, deixando a hora do lazer muito mais tranquila e divertida.Possui ainda, válvula para encaixe de filtro e deságue de água. Perfeita para a família toda se reunir e brincar de montão na melhor época do ano! Atenção! Nunca deixe crianças sozinhas perto da água sem supervisão de um adulto. Descrição do produto Marca: Mor Material da estrutura: Aço pintado Material da piscina: Lona Formato: Retangular Cor: Azul Capacidade: 5.000 Litros Possui fita de segurança Medida da piscina com escoras: 4,03m x 2,84m x 75cm Peso: 26,30 kg Imagens meramente ilustrativas, todos os itens que ambientam o produto não estão inclusos.', 1444.33, 994.5, NULL, 'Mom & Baby > Toys > Sports & Outdoor Play', 'https://cf.shopee.com.br/file/345e5e1cd3235cec7790681d6df5da59', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F638399297%2F20641669992', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694980032', 'Kit 5 Sabonetes Phebo Nectarina Da Andaluzia Barra 100g Cada', '*Produto Original* *Atenção:* Venda exclusiva para pessoa física. Pedidos com CNPJ serão cancelados. O Sabonete em Barra Phebo Nectarina da Andaluzia proporciona uma limpeza suave com fragrância sofisticada e marcante. Inspirado na perfumaria tradicional Phebo, combina notas frutadas e florais que deixam a pele delicadamente perfumada após o banho. Sua fórmula com base vegetal auxilia na limpeza sem ressecar, promovendo sensação de maciez e cuidado diário para todos os tipos de pele. Benefícios: Kit com 5 unidades de 100g Fragrância sofisticada e duradoura Limpeza suave para uso diário Base vegetal Pele macia e perfumada Espuma cremosa e agradável Ideal para todos os tipos de pele Modo de usar: Aplicar sobre a pele molhada, massageando suavemente até formar espuma. Enxaguar em seguida. Conteúdo da embalagem: 05 Sabonetes Phebo Nectarina Da Andaluzia 100g Marca: Phebo Linha: Perfumaria Tradicional Fragrância: Nectarina Da Andaluzia Peso unitário: 100g Peso total do kit: 500g Categoria: Sabonete em Barra', 36.45, 36.45, NULL, 'Beauty > Bath & Body Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-823qj-mojst851rbia61', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1458515228%2F22694980032', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19999903814', 'Episol Intense Protetor Solar 200Ml Fps50 Spray Bruma', '*Produto Original* *Atenção:* Venda exclusiva para pessoa física. Pedidos com CNPJ serão cancelados. Episol Intense FPS 50 é um protetor solar em formato spray que proporciona ação hidratante, ação antioxidante, rápida absoção e pode ser aplicado em pele molhada. É prático e tem alta proteção solar.', 111.95, 111.95, NULL, 'Beauty > Skincare > Face Sunscreen', 'https://cf.shopee.com.br/file/sg-11134201-825am-mg52ytu46yh6fd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1458515228%2F19999903814', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
