INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17230874893', 'Como Manter a Cabeça no Lugar neste Mundo Louco | Rick Renner', 'Estamos vivendo em um tempo em que multidões incontáveis se perderam, tanto moral quanto espiritualmente. Como um navio sem âncora, esta geração dos últimos dias está sendo jogada de um lado para o outro por uma enxurrada de engano e influências erradas, fazendo as pessoas perderem tragicamente as amarras que as prendem ao ancoradouro. O que devemos fazer para garantir que não sejamos sugados pelo turbilhão caótico de confusão moral e espiritual que está varrendo o mundo hoje? Esta é a pergunta vital que o autor Rick Renner responde neste livro instigante e oportuno. Autor(es): Rick Renner ISBN: 9786599007002 Número de Páginas: 368 Tamanho: 15,5x23 cm Peso: 0,484', 54.9, 54.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/d4b80312224ab091b70a487f551e426c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F17230874893', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
