INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23001381226', 'Isca Artificial Lambari Articulado Ligeira 10cm 15g Xingu', 'Isca Artificial Ligeira Articulada 10cm 15g Xingu Articulada O poder de atração dessa isca se torna irresistível a qualquer espécie de predador. Pois possui uma movimentação extrema lado a lado semelhante a um Lambari vivo, conta com seu corpo articulado com 7 segmentos, 2 garatéias afiadas e olhos 3d holográficos. Essa isca é ideal para pesca de todos os tipos de peixes predadores, tais como Tucunarés, Traíras, Dourados, Robalos, Black Bass , Badejos, anchovas, Tabarana, Matrinxãs entre outros. ESPECIFICAÇÕES: Marca: Xingu Modelo: Ligeira Ação: Meia-água Peso: 15g Tamanho: 10cm Cor: Cores conforme disponibilidade de estoque 7 segmentos e 2 garatéias Composição: Plástico/Metal Imagens Ilustrativas', 35.89, 35.89, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fishing', 'https://cf.shopee.com.br/file/sg-11134201-7rbkh-lp5m49fggjjnf3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F320275364%2F23001381226', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
