INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398641971', 'Coxim Superior Câmbio Fiat Palio Siena 1.0 2001-2017', 'Coxim Superior Câmbio FIAT Original - Estabilidade e Conforto Garantidos Número da Peça: 51736530 Compatibilidade: Fiat Palio e Siena 1.0 (2001-2017) Renove o sistema de transmissão do seu FIAT com o Coxim Superior do Câmbio original, projetado para oferecer máxima estabilidade e redução de vibrações. Esta peça é essencial para manter o desempenho e o conforto do seu Palio ou Siena 1.0, garantindo uma condução suave e silenciosa. Destaques: - Qualidade FIAT Original: Desenvolvido especificamente para os modelos Palio e Siena 1.0, assegurando durabilidade e eficiência máxima. - Instalação Perfeita: Projetado para um ajuste preciso, garantindo o funcionamento ideal do câmbio. - Conforto e Segurança: Reduz vibrações e ruídos, proporcionando uma experiência de direção mais agradável. Mantenha seu FIAT com a qualidade que ele merece! Escolha o Coxim Superior do Câmbio original e desfrute de uma condução mais suave e confortável. Seja bem-vindo ao Grupo Orletti, um dos maiores grupos automotivos da região, com anos de tradição, excelência em atendimento e compromisso com a sua satisfação! Somos concessionárias autorizadas das marcas Jeep, Renault, Ram, Citroën, Peugeot, Volkswagen, Fiat,Man,Hyundai e Omoda & Jaecoo', 258.14, 219.42, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Air Conditioning', 'https://cf.shopee.com.br/file/sg-11134201-7rdyj-md20qn38ju0n76', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1547130617%2F22398641971', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
