INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '6192304143', 'Par Palheta Limpador Parabrisa Dianteiro I30 2010 2011 2012', 'Par de Palhetas Limpador de Para-brisa Dianteiro I30 2010/2011/2012 Garanta a segurança e o conforto durante suas viagens com o Par de Palhetas Limpador de Para-brisa Dianteiro, compatível com Hyundai I30 dos modelos 2010, 2011 e 2012. Fabricadas com material de alta qualidade, as palhetas oferecem desempenho superior na limpeza do vidro, removendo água, sujeira e outros resíduos de maneira eficaz, proporcionando uma visão clara e sem manchas, mesmo em condições de chuva intensa. Características: ENCAIXE GANCHO!! Compatibilidade: Hyundai I30 2010, 2011 e 2012 Material durável e resistente, garantindo longa vida útil Desempenho eficiente em diversas condições climáticas Fácil instalação', 30.8, 21.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/e97d1b0a720e600c52c7a5ddf9fa7622', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F357432948%2F6192304143', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23498814280', 'Sapateira Modular Estante de Sapatos 12 Pares Deend', 'Organize seus calçados com praticidade e estilo usando a sapateira modular Deend. Com estrutura leve, funcional e de fácil montagem, o modelo é ideal para quem busca otimizar espaços pequenos sem abrir mão da organização. Suas laterais em plástico resistente e hastes metálicas garantem estabilidade e durabilidade no uso diário, além de um design discreto que combina com qualquer ambiente. Com 4 andares e capacidade real para até 12 pares, ela é perfeita para quartos, corredores, lavanderias ou closets. A montagem é simples, feita por encaixe, e não exige ferramentas. Com apenas 57 cm de comprimento é uma ótima solução para cantos estreitos e espaços reduzidos, oferecendo praticidade sem ocupar muito espaço. Características: Marca: Deend Modelo: D250419 Material: Estrutura em plástico com hastes metálicas Cor: Preto com tubos metálicos prateados Capacidade: Até 12 pares (3 por andar, 4 andares) Montagem: Manual, com encaixe Uso: Quarto, closet, lavanderia, hall de entrada 57 x 19 x 57 cm (AxLxC) Peso: 0.5 kg Benefícios: Compacta e ideal para ambientes pequenos Montagem rápida, sem uso de ferramentas Leve e fácil de mover para outros cômodos Design moderno e ventilado para os calçados Organização prática para o dia a dia', 61.47, 41.18, NULL, 'Home & Living > Home Organizers > Shoe Storage Boxes', 'https://cf.shopee.com.br/file/sg-11134201-7rdw8-mdg6h4i2yppg6f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F23498814280', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
