INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56410511339', '02 CefaWorld 150 mg Cães e Gatos Com 12 Comprimidos - World', 'Descrição:02 UNIDADES CefaWorld 150 mg Cães e Gatos Com 12 Comprimidos - World CefaWorld é um antibiótico à base de cefalexina, seguro em cães e gatos eficaz no combate de bactérias Gram + e Gram -indicado para tratamento de infecções dermatológicas, geniturinárias e intestinais. Comprimidos sulcados e revestidos para maior eficácia, segurança e facilidade de administração. Principais Características: - Comprimidos palatáveis; - Produto com rápida absorção pelo organismo. Indicação: Indicado para cães e gatos no tratamento de infecções bacterianas. Posologia e instruções de uso: Administração por via oral, conforme o peso do animal. Conforme fabricante a administração é de 30mg de cefalexina/kg de peso corporal, a cada 12 horas, durante 8 dias consecutivos, sendo: 01 comprimido de CefaWorld 150mg para cada 5 Kg de peso vivo. 01 comprimido de CefaWorld 300mg para cada 10 Kg de peso vivo. 01 comprimido de CefaWorld 600mg para cada 20 Kg de peso vivo. *Consulte sempre um médico veterinário e, em caso de outra indicação de uso, siga sempre o receitado pelo médico veterinário. _______________________________________________________ A MANADA ANIMAL é um marketplace de produtos veterinários. É a escolha certa para tutores que prezam pela qualidade dos produtos que seu animal necessita. Tudo com o suporte de uma equipe de veterinários e gestores com mais de 10 anos de experiência no mercado. Fique tranquilo, todos os nossos produtos são originais, adquiridos através de distribuidores credenciados! Ah, e todas as vendas acompanham nota fiscal! MANADA ANIMAL, Tranquilidade pra você, cuidado para ele!', 51.55, 51.55, NULL, 'Pets > Pet Healthcare > Vitamins & Supplements', 'https://cf.shopee.com.br/file/sg-11134201-822z9-mo8fmxh3lzwl51', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F450664666%2F56410511339', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47158059490', 'Lovito Elegante Bolsa de Ombro Pequena com Fivela Metálica Preta Bolsa de Ombro Pequena para Mulheres LFA113022', '✅DESTAQUES -❤️fivela metálica -❤️Clássico e versátil -❤️Retrô -❤️anual -❤️Vestuário de trabalho ✅DESCRIÇÕES Estampa / Padrão:Plain Estilo:Casual Tipo de fechamento: Estrutura das bolsas:Main compartment Tipo de bolsa:Baguette bag Material:PU Feito na China ✅INSTRUÇÕES DE CUIDADOS 1. Mantenha materiais como couro, materiais sintéticos e acessórios de metal longe da exposição direta ou excessiva à umidade, líquidos, calor e luz solar. A exposição a estes elementos pode causar desgaste permanente. 2. A fricção excessiva e o contato com substâncias oleosas, como cosméticos ou solventes, podem causar danos, desbotamento ou transferência de cor em roupas e superfícies de cores claras. 3. Use um pano macio e úmido para limpar manchas, poeira ou sujeira. 4. Quando não estiver em uso, guarde os itens em uma caixa ou saco protetor contra pó em local fresco e seco. ✅O PACOTE INCLUI 1XBolsa ✅INTRODUÇÃO LOVITO A Lovito é uma marca em crescimento que acredita no poder das meninas. Estamos comprometidos em oferecer opções de roupas fashion e acessíveis, para todos os estilos, necessidades e identidades. Acreditamos que a moda deve ser divertida, liberadora e fazer você se sentir incrível. Afinal, o melhor acessório para qualquer look é a autoconfiança! ✅NOTAS DE COMPRA Antes de comprar, dê uma olhadinha na tabela de medidas disponível no site. Lembre-se de que, por serem feitas manualmente, as medidas podem variar de 1 a 2 cm. As cores dos produtos também podem ter pequenas diferenças em relação às fotos, dependendo da iluminação e das configurações do seu dispositivo. Siga nossa loja e conheça novos itens e as melhores ofertas para você!! Se você tiver alguma dúvida, converse conosco e responderemos o mais rápido possível.', 67.5, 46.9, NULL, 'Women Bags > Crossbody & Shoulder Bags', 'https://cf.shopee.com.br/file/sg-11134201-823od-mp0m5vmv0b9e4b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F426378412%2F47158059490', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
