INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22892987862', 'Fralda Pampers Premium Care Pants XG com 26un', 'A fralda calça Pamper Pants Premium Care possui cintura elástica 360° é fácil de colocar até quando o bebê está em movimento, dando um ajuste perfeito e mantendo a pele seca e protegida. A fralda Pampers Premium Care Pants possui canais de ar que permitem que o ar circule livremente pela fralda, para que o bumbum fique menos abafado e a pele fique arejada e sequinha durante a noite. Pampers Pants Premium Care também possui proteção Pampers Premium Care, a proteção mais suave para a pele do bebê, ultra respirável para manter a pele do bebê fresca e loção hipoalergênica que ajuda a prevenir irritações. A fralda calça Pampers Pants Premium Care é muito fácil de pôr e tirar basta seguir o modo de uso: 1. Coloque a mão dentro da fralda; 2. Suba a fralda como um shortinho através dos elásticos adaptáveis; 3. Para retirar a fralda rasgue suas laterais e retire-a normalmente; 4. Enrole e feche a fralda com a fita adesiva da parte de trás.', 76.79, 66.06, NULL, 'Mom & Baby > Diapering & Potty > Disposable Diapers', 'https://cf.shopee.com.br/file/sg-11134201-7rd5i-luoy19qpqfp901', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F353664457%2F22892987862', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259434200', 'Molho de Tomate Tradicional Heinz', 'O Molho de Tomate Tradicional Heinz é a escolha perfeita para quem busca praticidade e sabor. Com pedaços de tomate, ele é ideal para dar um toque especial em massas, carnes e outros pratos. * Prático: já vem pronto para uso, basta aquecer e servir. * Saboroso: feito com ingredientes selecionados, garantindo o sabor tradicional Heinz. * Versátil: perfeito para diversas receitas. Modo de preparo: Coloque o molho de tomate Heinz em um recipiente apropriado e aqueça em fogo médio por, aproximadamente, 3 minutos. Sirva com a sua receita de preferência.', 3.99, 3.99, NULL, 'Food & Beverages > Cooking Essentials > Seasonings & Condiments', 'https://cf.shopee.com.br/file/sg-11134201-825ap-mqnelhd1jbwu87', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555161%2F58259434200', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209363513', 'SIO2 - PRO 500ML VONIXX', '🚗✨ BEM-VINDO! Você está em uma loja especializada em soluções automotivas seguras e confiáveis. Aqui, cada detalhe é pensado para cuidar do que move você: sua família, sua segurança e seus melhores momentos na estrada. 🧴 SiO2-Pro – Manutenção para Vitrificadores – 500ml 🆕 NOVA FÓRMULA Os vitrificadores à base de silício protegem a pintura por muito tempo — e o SiO2-Pro foi desenvolvido para manter e potencializar esse efeito. 🌟 PRINCIPAIS BENEFÍCIOS 💧 Maior poder hidrofóbico ✨ Melhor acabamento 🚘 Mais brilho por até 3 meses 🔬 SOBRE O PRODUTO Os vitrificadores oferecem alta proteção, porém deixam o toque mais “vidrado”. Pensando nisso, o SiO2-Pro foi desenvolvido para: ✔️ Proporcionar toque aveludado ✔️ Melhorar o acabamento da superfície ✔️ Reduzir o atrito (menos risco de riscos) ✔️ Prolongar a vida útil da vitrificação 🧪 Sua fórmula contém silanos e siloxanos, polímeros derivados do silício, responsáveis por uma hidrorrepelência incrível. 🔁 MANUTENÇÃO IDEAL 📅 Reaplicação recomendada a cada 30 a 45 dias 🧩 ONDE PODE SER USADO 🚗 Pintura 🛞 Rodas 💡 Faróis e lanternas 🧴 Plásticos (internos e externos) 🛠️ MODO DE USAR 1️⃣ 🧼 Certifique-se que a superfície esteja limpa e seca 2️⃣ 🔄 Agite bem o produto antes de usar 3️⃣ 💦 Pulverize uma leve névoa (área de até 60x60cm) 4️⃣ 🧽 Espalhe com microfibra limpa e seca 5️⃣ ✨ Finalize até obter o brilho desejado 6️⃣ 🔁 Se houver manchas, repita o processo 💡 DICA PROFISSIONAL ✔️ Use sempre toalha de microfibra de qualidade ✔️ Trabalhe em pequenas áreas para melhor resultado ✔️ Evite aplicação sob sol forte ☀️', 70.96, 63.92, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-820ll-mndcncq0kum9b4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1552175911%2F58209363513', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
