INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209456833', 'Salgadinho de Camarão Ebicen', 'O salgadinho de camarão Ebicen é um dos mais tradicionais e conhecidos no Brasil, apreciado por adultos e crianças. Crocante e saboroso, é perfeito para um lanche rápido a qualquer hora. Ingredientes: Farinha de trigo enriquecida com ferro e ácido fólico, fécula de mandioca, camarão, óleo vegetal, sal iodado, açúcar cristal, realçador de sabor glutamato monossódico. Alérgicos: Contém derivados de trigo e crustáceos (camarão). Pode conter outros frutos do mar. Contém glúten.', 3.49, 3.49, NULL, 'Food & Beverages > Snacks > Chips & Crisps', 'https://cf.shopee.com.br/file/sg-11134201-8260d-mj72nl479u6d45', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554909%2F58209456833', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22897558627', 'Luva de Lavagem PRO Culture', 'Luva de Lavagem PRO Culture A Luva de Lavagem PRO Culture conta com tentáculos facilita na hora da lavagem, deslizando sobre a superfície sem causar danos, removendo as sujeiras presentes na superfície. Conta com tentáculos que fazem a sujeira ser puxada em direção à mão, assim evitando riscos e danos à superfície. Garanta uma lavagem eficiente e segura com a Luva de Lavagem PRO Culture! Tamanho da Luva: 25x18cm', 23.99, 23.99, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdx4-lxsdw9ch03fkea', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F384950713%2F22897558627', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198482403', 'Chantilly Chanty Norcau Puratos 1 Litro', 'Chantilly Norcau Puratos é uma ótima opção para boleiras e profissionais do ramo de confeitaria; pois ele garante resultado excelente e um sabor maravilhoso em suas receitas. Ideal para coberturas; para alisar bolos; recheios; fazer trufas; ganaches; mousses; cafés; sobremesas; bebidas e outros. Ótimo rendimento. Rapidez no preparo. Não contém conservantes e possui suavidade ao paladar. DICAS: Antes de usar, manter na geladeira por 12 horas. Para bater o produto: 5 a 8°C para temperatura ambiente de até 25°C para temperatura ambiente acima de 25°C. Batimento: Bater com a velocidade média até que você consiga a consistência desejada. Conteúdo: 1 Litro. Ingredientes: Água, gordura vegetal hidrogenada, açúcar, caseinato de sódio, sal, estabilizantes: sorbitol, hidroxipropilcelulose e alginato de sódio, emulsificantes: ésteres de ácido diacetil tartárico e mono e diglicerídeos, lecitina de soja e polisorbato 60, aromatizantes e corante betacaroteno sintético. CONTÉM GLÚTEN. ALÉRGICOS: Contém derivados de leite de vaca e soja. Pode conter trigo, aveia, centeio, cevada, tritical e ovos. Informação Nutricional - Porção de 20g Valor Energético: 58kcal=242kj; Carboidratos: 2,6g; Proteínas: 0g; Gorduras Totais: 5,2g; Gorduras Saturadas: 5,2g; Gorduras Trans: 0g; Gorduras Monoinsaturadas: 0g; Gorduras Poliinsaturadas: 0g; Colesterol: 0mg; Fibra Alimentar: 0g; Sódio: 14mg.', 44.42, 33.32, NULL, 'Food & Beverages > Dairy & Eggs > Others', 'https://cf.shopee.com.br/file/sg-11134201-824hm-meh77lxgrrida0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1507942655%2F22198482403', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53701324412', 'Cake Box Redondo com Tampa para Bolo 1,5L Bluestar', 'A Cake Box Redonda Cristal Com Tampa Bluestar é um recipiente prático e elegante, ideal para armazenar e transportar bolos e sobremesas. Feita em material transparente de alta qualidade, a caixa oferece uma visão clara do conteúdo, preservando a apresentação do doce. Sua tampa firme garante o fechamento seguro, mantendo o frescor e protegendo contra contaminações externas. Com capacidade de 1,5 litros, é perfeita para porções menores de bolos, tortas ou outras delícias. O design redondo e compacto facilita o manuseio e armazenamento, sendo uma excelente opção para confeiteiros e amantes de sobremesas. Medidas aproximadas do produto: Diâmetro 18,6cm Altura 8,7cm.', 36.32, 25.79, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/sg-11134201-821f1-mh0o6nu0uq6i1d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1507942655%2F53701324412', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
