INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20998525654', 'Mop Rodo Magico Flash Limp Limpeza Geral Plus + Refil Extra MOP7672', 'Seja bem-vindo(a) ao nosso canal de vendas! Temos como objetivo a satisfacao de nossos clientes e a missao de atender bem, trabalhando com profissionalismo nas vendas e no atendimento. Proporcionando assim uma otima experiencia de compra! - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - O Mop Limpeza Geral Plus da Flash Limp tem grande poder de absorcao. Pode ser utilizado para lavar e secar janelas e pisos. Ele substitui o rodo, a vassoura e o pano de chao. O melhor de tudo e que voce nao precisa torcer a mao. O aparelho possui um mecanismo que faz isso por voce. Seu dia a dia ficara muito mais simples e a sua casa muito mais limpa, com o Mop Limpeza Geral da Flash Limp. Nunca utilize agua sanitaria, amaciantes ou alvejantes, isso diminuira a vida util , o cabo e feito de metal e o mau uso ou ma conservacao pode levar ao rompimento do mesmo, nao acionar a lavanca com a espuma seca, pode danificar a engrenagem, seguir as orientacoes na embalagem. Leve, pratico e simples ao utilizar! Adquira ja o seu! - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - ITENS INCLUSOS: - 1 Mop Limpeza Geral Plus - 2 Refis Para Mop Limpeza Geral Plus CARACTERISTICAS: - Alto poder de absorcao - Ideal para limpezas rapidas - Substitui a vassoura, o rodo e pano de chao - Cabo telescopico possui ajuste de altura MEDIDAS E PESO: C-89 A 125cm L-28cm A-6cm - 617g - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - Aguardamos a sua compra e esperamos te proporcionar uma excelente experiencia! Conte conosco para melhor lhe atender!', 120.9, 120.9, NULL, 'Home & Living > Home Care Supplies > Sponges & Scouring Pads', 'https://cf.shopee.com.br/file/sg-11134201-7qvfa-lgy1ee5kw3ij78', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F741045633%2F20998525654', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17482255840', 'Refil Mop Giratorio Fit Kit 5 Uni RMOP5011 Flash Limp', 'Seja bem-vindo(a) ao nosso canal de vendas! Temos como objetivo a satisfacao de nossos clientes e a missao de atender bem, trabalhando com profissionalismo nas vendas e no atendimento. Proporcionando assim uma otima experiencia de compra! O Refil para Mop Giratorio Fit e lavavel e 100% microfibra. Esse modelo e exclusivo para Mop Giratorio Fit. Antes de utilizar, verifique se o pano esta limpo, pois particulas de sujeira podem riscar a superficie. Lave o pano imediatamente apos o uso e deixe secar. Caso o pano seja lavado na maquina de lavar, nao utilize amaciantes e nem misture com panos que possam soltar fiapos. Guarde o produto em local seco ao abrigo da luz solar. Mantenha o produto longe de fontes de calor. ITENS INCLUSOS: - 1 Refil de microfibra Caracteristicas: - Compativel com os Mops Giratorios Fit: MOP5010, MOP5011, MOP9775 e MOP9379 - O refil de microfibra, possui alta absorcao, nao solta fiapos, reduz o uso de produtos quimicos - Ideal para pisos frios, sinteticos ou madeiras Medidas e peso: C-35cm L-35cm A-4cm - 100g Aguardamos sua compra e esperamos que tenha uma otima experiencia! Conte conosco! Sera um prazer lhe atender!', 75.9, 75.9, NULL, 'Home & Living > Home Care Supplies > Mops', 'https://cf.shopee.com.br/file/bf6920a26e4886e9aa0187a321daddc7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F741045633%2F17482255840', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
