INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19399068337', 'Piercing Helix Conch Tragus Labret Titânio Pvd Estrela Zirconia', '💖 💖 🥳 🥳 Bem-vindo a 《LOMISS Piercing》🥳 🥳 💖 💖 🎊🎊👍👍Somos uma grande empresa de piercing. O endereço está localizado em São Paulo.Todos os produtos da loja são de alta qualidade. 👍👍🎊🎊 🚚 🚚🚀 🚀 Temos uma grande quantidade de estoque. Enviaremos seu pedido em até 48 horas após o pagamento. 🚀 🚀🚚 🚚 🎉🎉🎫 🎫Clique em ""SEGUIR"" e receba vouchers de desconto exclusivos.🎫 🎫🎉🎉 ---------------------------------------------------------------------------------------------------------------- ⭐⭐O produto é 100% titânio puro. Absolutamente sem alergias!! ⭐⭐Características:Resistente à corrosão, alta resistência, Inibição de bactérias, não alergênico！ 💎- Modelo: Labret 💎- Espessura Da haste:1.2 mm 💎- Comprimento da haste: 8mm 💎- Material: Titânio 100% 💎- Pedra: Zircônia 💎- Fecho: Rosca Piercing 100% Novo e a Pronta Entrega - Podendo ser Usado: Helix, Tragus, Conch, Nariz, Boca-Medusa e Outros Lembrando que: Cada pessoa tem formato de corpo/local de aplicação (mais pra dentro/fora), então varia com tamanho de joia. Fácil Colocação e Remoção *PVD - É uma tecnologia utilizada para a deposição de filmes metálicos finos sobre diversos tipos de substratos. O processo é realizado, sob vácuo, onde os metais a serem depositados são evaporados. É particularmente indicado para aqueles produtos inovadores e de qualidade que necessitam atender elevados padrões e permite ainda obter uma vasta gama de cores. - Elevada resistência ao desgaste e abrasão; - Resistência ao suor e transpiração humanos; - Hipoalergênicos. ✚ Como cuidar de suas joias novas ✚ As joias corporais, independentemente do material, requerem cuidados redobrados, pois o material pode penetrar na carne. Recomendamos o seguinte. - Sempre remova as joias durante esportes com suor intenso, natação e banho, pois qualquer coisa, desde água, óleo, cloro, perfume e suor, pode danificar as joias. - Se for necessário limpar, use sempre água morna e sabão neutro. Nunca use álcool ou quaisquer produtos químicos, pois podem causar descoloração ou outras reações adversas às joias. Certifique-se de secar bem o corpo e as joias antes de reinserir. Certifique-se de usar um pano macio e não abrasivo para evitar riscar o metal. - Se você tiver alguma reação a joias folheadas (como colares, pulseiras, anéis, etc.), não recomendamos nenhuma joia folheada, pois você pode ter uma reação semelhante. - Recomendamos que você guarde suas joias em uma bolsa com zíper quando não estiver em uso.', 35.9, 35.18, NULL, 'Fashion Accessories > Additional Accessories > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lnsvqdvf1zyf80', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F493729464%2F19399068337', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22628608761', 'Piercing Microbell AÇo CirÚrgico Borboleta Helix Flat Conch Tragus Lóbulo Lomiss piercing', '💖 💖 🥳 🥳 Bem-vindo a 《LOMISS Piercing》🥳 🥳 💖 💖 🎊🎊👍👍Somos uma grande empresa de piercing. O endereço está localizado em São Paulo.Todos os produtos da loja são de alta qualidade. 👍👍🎊🎊 🚚 🚚🚀 🚀 Temos uma grande quantidade de estoque. Enviaremos seu pedido em até 48 horas após o pagamento. 🚀 🚀🚚 🚚 🎉🎉🎫 🎫Clique em ""SEGUIR"" e receba vouchers de desconto exclusivos.🎫 🎫🎉🎉 ---------------------------------------------------------------------------------------------------------------- 💎- Diâmetro Interno: 6/8mm 💎- Espessura da Haste: 1.2 mm 💎- Topo: 6 mm 💎- Material: Aço Cirúrgico 💎- Fecho: Rosca 💎- Pedra: Opala 💎- Pode Ser Usado: Helix, Flat, Conch, Tragus, Lóbulo e Outros 💎- Quantidade: 1 Unidade Piercing 100% Novo e a Pronta Entrega Lembrando que: Cada pessoa tem formato de corpo/local de aplicação (mais pra dentro/fora), então varia com tamanho de jóia. Fácil Colocação e Remoção *PVD - É uma tecnologia utilizada para a deposição de filmes metálicos finos sobre diversos tipos de substratos. O processo é realizado, sob vácuo, onde os metais a serem depositados são evaporados. É particularmente indicado para aqueles produtos inovadores e de qualidade que necessitam atender elevados padrões e permite ainda obter uma vasta gama de cores. - Elevada resistência ao desgaste e abrasão; - Resistência ao suor e transpiração humanos; - Hipoalergênicos. ✚ Como cuidar de suas joias novas ✚ As joias corporais, independentemente do material, requerem cuidados redobrados, pois o material pode penetrar na carne. Recomendamos o seguinte. - Sempre remova as joias durante esportes com suor intenso, natação e banho, pois qualquer coisa, desde água, óleo, cloro, perfume e suor, pode danificar as joias. - Se for necessário limpar, use sempre água morna e sabão neutro. Nunca use álcool ou quaisquer produtos químicos, pois podem causar descoloração ou outras reações adversas às joias. Certifique-se de secar bem o corpo e as joias antes de reinserir. Certifique-se de usar um pano macio e não abrasivo para evitar riscar o metal. - Se você tiver alguma reação a joias folheadas (como colares, pulseiras, anéis, etc.), não recomendamos nenhuma joia folheada, pois você pode ter uma reação semelhante. - Recomendamos que você guarde suas joias em uma bolsa com zíper quando não estiver em uso.', 22.99, 22.99, NULL, 'Fashion Accessories > Additional Accessories > Others', 'https://cf.shopee.com.br/file/br-11134201-23030-jmpy8b7f86nvbc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F493729464%2F22628608761', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58258921668', 'Pneu Maxzez Grepower 195/55 R15 Aro 15 85V', 'Liberte o verdadeiro potencial do seu carro com o pneu Maxzez Grepower 195/55 R15 Aro 15 85V. Projetado para ótima aderência e dirigibilidade tanto em baixa quanto em alta velocidade, esse pneu oferecem precisão e controle, permitindo que você obtenha o melhor do seu veículo. O índice de velocidade V indica especificamente uma capacidade de velocidade máxima de até 240 Km/h, enquanto o índice de carga máximo é indicado por 85 (515 Kg).', 327.73, 327.73, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-81ztf-mn3cm73tmc5e1b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F540643031%2F58258921668', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
