INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43609024914', 'Pneu Chaoyang Phantom Wet 29x2.20 2c Tubeless Kevlar Sem Arame Preto c/ Bege MTB', 'PNEU CHAOYANG PHANTOM WET 29X2.20 - TUBELESS READY – KEVLAR – PRETO COM FAIXA MARROM Atenção: - Anúncio unitário. Descrição: Para condição de terreno molhado ou solto. Os cravos possui altura média com maior espaçamento entre os cravos, garantindo mais aderência e controle em curvas. Esse modelo tem a banda de rolagem na cor preta e a faixa lateral na cor marrom. Características: - SEM ARAME, DOBRÁVEL; - TLR - Tubeless Ready – Compatível com uso sem câmara; - Também pode ser usado com câmara; - TPI 60 fios por polegada; - Modalidade de uso: XC / TREKKING; - Indicação de uso: Dianteira ou Traseira; - Para terrenos: Molhado e soltos com obstáculos medianos. Especificações: - Marca: CHAOYANG; - Modelo: PHANTOM WET – H-5235TR; - Tubless Ready: TLR - Aceita uso com selante e sem câmara (Tubeless); - Dobrável com composto de Kevlar; - Carcaça: Composto 2C-MTB – Combinação de materiais, aprimorando o produto no equilíbrio entre aderência, resistência e desgaste; - TPI: 60; - Calibragem recomendada: 23-50 PSI; - Disponível na medida: 29x2.20 (55-622) – Largura 55mm montado no aro; - Peso aproximado: 29x2.20 - 790g; - Cor: Preto; - Origem: China; - Part Number: EB10803008FB; - Cód. Barras: 6938112672690. Observação: - Anúncio unitário; - Compatível com sistema Tubeless (sem câmaras); - Compatível com uso com Câmaras de Ar, também; - Produto original CHAOYANG e acompanha nota fiscal; - Garantia 90 dias CHAOYANG BRASIL.', 299.99, 210.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mccfce0ze8yo75', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F819102597%2F43609024914', NULL, NU