INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21198698300', 'Kit Engrossador Tio Nacho Shampoo 415ml + Condicionador 200ml', 'Kit Tio Nacho Engrossador Shampoo 415ml + Condicionador 200ml O Kit Tio Nacho Antiqueda Engrossador contém exclusiva combinação de Geleia Real com Capilgross e extratos de origem natural, que aumentam a espessura do fio e evitam a queda, proporcionando cabelo mais forte, volumoso e saudável. Modo de usar Aplique o shampoo sobre o cabelo molhado, distribuindo generosamente, fazendo uma leve massagem no couro cabeludo; enxágue e repita a operação. Após o uso do shampoo, aplique sobre todo o comprimento dos fios, até as pontas. Deixe agir por um minuto e enxágue. Benefícios - Proporciona um aumento na espessura dos fios, fortalece e revitaliza o couro cabeludo; - Além disso, devolve o brilho e a força dos cabelos opacos e quebradiços. - Indicado para cabelos com pouco volume.', 64.9, 55.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7qved-li7toyjfvasz1b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290598330%2F21198698300', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
