INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18861790791', 'Atuador Hidráulico Embreagem Corsa Prisma Montana 2002 a 2019 FTE 1102031', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. Aplicação GM - CHEVROLET Corsa 1.0/1.4/1.8 8V - 2002 até 2012 Prisma 1.0/1.4 8V - 2013 até 2019 Montana 1.4/1.8 8V - 2004 até 2018 Conteúdo Da Embalagem 1 Atuador de Embreagem Observação Fluído Hidráulico Utilizado Dot3 Ou Dot4. Tipo de Veículo para Carros Marca A FTE é um fornecedor de equipamentos originais para o setor automotivo mundial e também um parceiro preferido no aftermarket. Aplicando a experiência e o conhecimento adquirido na produção de equipamentos originais em seus programas de peças. De peças de freio e de embreagem até os fluidos de freio para veículos de passeio e comerciais, a FTE oferece uma extensa linha de produtos para seus atacadistas e para oficinas independentes em 117 países. Garantindo a qualidade de um produto de primeira linha e o suporte para manutenção e reparos. Importante Recomendamos que os produtos sejam instalados por profissionais especializados e não nos responsabilizamos pelo mau uso ou instalação indevida, causando a perda da garantia. Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades. Tempo de garantia: 3 Meses Valor Unitário Imagem meramente ilustrativa Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078 Código do Fabricante 1102031 Código da Montadora 24 422 061 Atuador Hidráulico', 264.41, 264.41, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Transmission', 'https://cf.shopee.com.br/file/sg-11134201-7rbmj-lm4iuhzxmund34', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F18861790791', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21757314666', 'Filtro Óleo Ford Fiesta Hatch 1.0 2002 A 2007 Wega', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. >Aplicação FIESTA GL 1.0 3P 2002 FIESTA GL 1.0 5P 2002 FIESTA STREET/ ACTION 1.0 8V 5P 2002 até 2007 Conteúdo Da Embalagem 1 Filtro de óleo Tipo de Veículo para Carros Marca Quase 50 anos após sua fundação, a empresa familiar tornou-se uma empresa industrial, comercial e exportadora que investe no país criando oportunidades no presente e continuidade para as gerações futuras. A Wega possui o mais completo catálogo de filtros, e antecipa as necessidades do mercado de reposição, diferencia-se pela rápida incorporação de novos desenvolvimentos, oferecendo lançamentos mensais de produtos que atendem aos requisitos dos diferentes mercados-alvo e expandem continuamente as opções disponíveis. O Produto > Com a finalidade de remover os resíduos indesejáveis que podem estar contidos no óleo do motor, o f iltro de óleo é feito com um papel especial, que está contido dentro da carcaça do filtro. O óleo sujo pode causar entupimento do motor podendo causar até a fundição do mesmo. Importante • Tempo de garantia - 4 meses • Imagem meramente ilustrativa • Valor unitário • Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078 EAN 17798001699247 Código do Fabricante WO1501 >', 16.35, 16.35, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rbng-lltnbcsuyp9668', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F21757314666', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
