INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40175344330', 'Tesoura Para Poda Famastil', 'A Tesoura Para Poda é um produto de alta qualidade, ideal para realizar cortes precisos em plantas, brotos e ramos mais fortes. É produzida com aço temperado especial, garantindo durabilidade e resistência. Com um tamanho de 6,5 polegadas, essa tesoura é perfeita para uso em jardins e áreas verdes. Seu cabo anatômico proporciona um manuseio confortável, permitindo que você trabalhe por mais tempo sem sentir desconforto nas mãos. Essa tesoura conta com uma trava de segurança, que aumenta a durabilidade da mola e evita acidentes durante o uso. Seu design foi pensado para oferecer praticidade e eficiência, tornando-a a escolha perfeita para os amantes de jardinagem. Essa tesoura é indicada para cortar plantas, brotos e ramos mais fortes, deixando seu jardim ainda mais bonito e bem cuidado. Com ela, você poderá realizar podas com precisão, garantindo o crescimento saudável das suas plantas.', 43.93, 38.75, NULL, 'Home & Living > Gardening > Gardening Tools', 'https://cf.shopee.com.br/file/sg-11134201-8259r-mg3oywlz03d8fd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F988566789%2F40175344330', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
