INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897684310', 'Farol de Trabalho Redondo com LEDS 16W 9V A 48V Especial para Tratores e Máquinas Agrícolas - DNI 41', 'Farol de Trabalho Redondo com LEDs 16W 9V a 48V Especial para Tratores e Máquinas Agrícolas - DNI 41DescriçãoO Farol de Trabalho Redondo com LEDs 16W é a solução ideal para iluminação em tratores, máquinas agrícolas, empilhadeiras e outros equipamentos. Com uma potência máxima de 16W e tensão de funcionamento de 9 a 48Vdc, este farol oferece um fluxo luminoso de 1100lm, proporcionando uma iluminação eficiente e potente. Sua temperatura de cor de 6000K emite uma luz branca fria, ideal para ambientes de trabalho. Atributos Marca: DNI Modelo: DNI4183 Número de Peça: DNI4183 CaracterísticasO Farol de Trabalho Redondo com LEDs 16W utiliza 4 LEDs com tecnologia SMD, garantindo uma iluminação de alta qualidade. Sua carcaça em alumínio reforçado e lente em policarbonato proporcionam durabilidade e resistência, com excelente acabamento. Com classificação IP68, este farol é protegido contra poeira e imersão temporária em água, tornando-o ideal para uso em ambientes externos e sujeitos a condições adversas. Especificações Fluxo Luminoso: 1100lm Temperatura de Cor: 6000K - Branco Frio Cor: Preto Formato: Redondo Fixação por parafusos Fácil instalação Dimensões Aproximadas: Ø8,2 x 5,2cm AplicaçõesO Farol de Trabalho Redondo com LEDs 16W é indicado para tratores, máquinas agrícolas, empilhadeiras e diversos outros equipamentos. Sua versatilidade e qualidade de iluminação o tornam essencial para ambientes de trabalho que necessitam de uma fonte de luz eficiente e durável. Adquira agora o Farol de Trabalho Redondo com LEDs 16W e garanta uma iluminação de qualidade para suas atividades agrícolas e industriais!', 73.61, 73.61, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Electrical System', 'https://cf.shopee.com.br/file/sg-11134201-7rdvh-lydo0wr53lwqa7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F972460632%2F23897684310', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
