INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22392518509', 'Sombra e Iluminador Disney 100 Bruna Tavares Bt Maloow', 'Descrição: A Sombra e Iluminador Disney 100 Bruna Tavares Bt Maloow em parceria Bruna Tavares e Disney se une para a Celebração Disney100 Anos de Emoção. Possui uma fórmula híbrida que combina a mistura de pó e gel. Com toque macio como o de um marshmallow e acabamento em pó ultra brilhante, esse produto possui uma fórmula única com ultra sedosidade e pigmentos finos e sofisticados de brilho e cor. Cores: - Happily Ever After - coral com brilho dourado - Dream Castle - azul celeste com brilho azul cristalino MODO DE USAR: 1 - Aplique com ajuda de um pincel ou com os dedos nas áreas desejadas. USO EXTERNO. MANTENHA FORA DO ALCANCE DAS CRIANÇAS. Conteúdo da embalagem: 5g. Composição: Polymethylsilsesquioxane/polimetilsilsesquioxano, talc/talco, oryza sativa bran wax/cera do farelo de oryza sativa, octyldodecanol/octildodecanol, phenyl trimethicone/fenil trimeticona, dimethicone/dimeticona, dimethicone/vinyl dimethicone crosspolymer/crospolímero de dimeticona/vinil dimeticona, phenoxyethanol/fenoxietanol, tocopherol/tocoferol, octocrylene/octocrileno, homosalate/homossalato, butyl methoxydibenzoylmethane/avobenzona, helianthus annuus seed oil/óleo de girassol. pode conter: calcium aluminum borosilicate/ borossilicato de cálcio alumínio, calcium sodium borosilicate/borossilicato de cálcio sódio, synthetic fluorphlogopite/fluorflogopita sintética, tin oxide/óxido de estanho, silica/dióxido de silício, ci 77007/corante azul 77007, ci 77891/dióxido de titânio, ci 15850/corante vermelho 15850. #Imagem ilustrativa. Cor do produto poderá variar dependendo da configuração do monitor ou celular.', 39.99, 39.99, NULL, 'Beauty > Makeup > Eyes', 'https://cf.shopee.com.br/file/sg-11134201-7rbly-lmno6pgp46e2d2', 'https:/