INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18098202106', 'Oleo de Limpeza Vizzela Cleansing Oil 100ml', 'Descrição: O Oleo de Limpeza Vizzela Cleansing Oil 100ml ele funciona usando uma combinação de óleos não comedogênicos que remove todas as sujeiras e impurezas da pele, até as mais pesadas. É uma limpeza profunda que diferente de sabonetes remove com maior eficiencia os resíduos oleosos da pele. E o diferencial é que quando enxaguado ele forma uma emulsão e sai totalmente na água. Ou seja, não deixa resíduo oleoso. E o mais importante: pode ser utilizado por todos os tipos de pele. MODO DE USAR: 1 - Aplique massageando bem o rosto até dissolver toda a maquiagem ou impurezas da pele. 2 - adicione água para formar uma emulsão e enxaguar todo o produto. 3 - Aplique massageando bem o rosto ate dissolver toda maquiagem ou impurezas da pele. adicione água para formar uma emulsão e enxaguar todo o produto. USO EXTERNO. MANTENHA FORA DO ALCANCE DAS CRIANÇAS. Conteúdo da embalagem: 100ml. Composição: caprylic/capric triglyceride, heliantus annus (sunflower) seed oil, c12-15 alkyl benzoate, diethylhexyl sodium sulfosuccinate, polyglyceryl-3 caprate, tocopheryl acetate, bellis perennis (daisy) flower extract, foeniculum vulgare oil, phenoxyethanol. #Imagem ilustrativa. Cor do produto poderá variar dependendo da configuração do monitor ou celular.', 84.9, 84.9, NULL, 'Beauty > Skincare > Facial Oil', 'https://cf.shopee.com.br/file/sg-11134201-7req7-m86a3s153vky4e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322432427%2F18098202106', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
