INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17940989272', 'Cabo Rca Blindado Pontas Preto 1,5 Metros Emborrachado', 'Cabo RCA Simples 1,5 Metros com 4 Conectores Machos Preto Borracha Som Automotivo : Cansado das interferências que o seu aparelho de áudio e vídeo vêm apresentando? Então se liga nesse Cabo RCA que a Tech One preparou para você! Com esse cabo a sua disposição, você poderá ligar o player automotivo ao módulo amplificador sem nenhum problema. Além da excelente qualidade, este cabo recebe revestimento em borracha evitando que correntes elétricas possam danificar o seu produto. Possuindo ainda 4 conectores machos, esse cabo tem tonalidade preta e conta com 1,5 metros de comprimento. Especificação Técnica: - Cabo RCA Simples - Revestimento em Borracha - Disponível na Cor Preta - Possui Conectores Duplos - 4 Conectores Macho - Alta Durabilidade - Diminui Interferências na Transmissão de Áudio ou Vídeo - Medidas Aproximadas da Espessura: 5mm - Comprimento Aproximado do Cabo: 1,5m Conteúdo da Embalagem: - 01 Cabo 1,5 Metros', 13.9, 13.9, NULL, 'Audio > Audio & Video Cables & Converters', 'https://cf.shopee.com.br/file/0693787aa83121a1b7c5184a02605c88', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F288113309%2F17940989272', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23219532345', 'Filtro de Óleo Tecfil PSL148 ECOSPORT, FIESTA', 'APLICAÇÃO = FORD ECOSPORT 1.0 8V GASOLINA 03 -- 06 ECOSPORT 1.6 8V XL/XLT GASOLINA / FLEX 03 -- 12 FIESTA 1.0 8V GASOLINA 01 -- 06 FIESTA 1.6 8V GASOLINA / FLEX 04 -- 15', 38.0, 38.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/br-11134201-23010-myp2ud3bujmvdb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F868014016%2F23219532345', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593168478', 'Restaura Plástico para-choque Brazilian', 'Restaura Plástico para-choque Brazilian CONTÉM NA EMBALAGEM: 1 Bisnaga de resina 75g 1 Bisnaga endurecedor 75g 1 Manta de fibra de vidro 50 cm 1 Filme plástico 50cm ................................................................................................................................................ INFORMAÇÕES DO PRODUTO ................................................................................................................................................ Restaura Plástico é Indicado para o reparo de para-choques, para-lamas e quaisquer outras peças feitas de plástico (Poliuretano e ABS) ou fibra de vidro. Secagem rápida, fácil de lixar e excelente aderência. ................................................................................................................................................ Preparação ................................................................................................................................................ 1 parte de Resina para 1 parte do Endurecedor RESTAURA PLÁSTICO. Homogeneizar bem por pelo menos 01 (um) minuto. Pot life (tempo de utilização após preparo) 35 minutos, não utilizar após esse período. ................................................................................................................................................ Aplicação ................................................................................................................................................ Utilizar o filme plástico pressionando para retirar as bolhas de ar e melhor adesão da manta com a mistura. Após a secagem, retirar o filme plástico e efetuar o lixamento. Não é recomendado fazer a aplicação em PVC. Não aplicar massa poliéster sobre o RESTAURA PLÁSTICO. Lixar bem a superfície a ser colada. Limpe a peça, a fim de eliminar qualquer resíduo de óleo, graxa, poeira e quaisquer outros contaminantes. ................................................................................................................................................ Secagem ................................................................................................................................................ Ao ar 25°C: 4 horas para manuseio • 48 horas secagem final. ................................................................................................................................................ Instruções ................................................................................................................................................ Cortar 3 camadas da manta de vidro, uma mais larga que a outra, com o comprimento respeitando o tamanho do reparo. Aplique a primeira camada do RESTAURA PLÁSTICO (mistura da Resina e o Endurecedor) para peças plásticas e em seguida a manta com a largura menor. Sempre alternar entre uma camada do RESTAURA PLÁSTICO e uma de manta. Realizar esse processo por três vezes, com a manta na ordem crescente e finalizar com mais uma camada do RESTAURA PLÁSTICO para peças plásticas. ................................................................................................................................................ #FLEXSEAL #restauraplastico #restauraparachoque #restaurarachadura', 58.9, 56.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdyx-lxwpjtzplhsw53', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1027399414%2F22593168478', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
