INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698393770', 'Nível de Alumínio MTX 400mm 16" com 3 Bolhas Régua Vermelha', '***PRODUTO A PRONTA ENTREGA COM ENVIO IMEDIATO*** Nível de Alumínio 16" (400mm) com 3 Bolhas – MTX 332209 O Nível de Alumínio MTX 332209 é a ferramenta ideal para garantir medições precisas em qualquer projeto. Com estrutura leve e resistente em alumínio reforçado, possui três bolhas calibradas para verificar nivelamento horizontal, vertical e ângulos de 45°. Além disso, conta com uma régua integrada, tornando-se um item versátil para profissionais e entusiastas do faça-você-mesmo. Diferenciais: Três bolhas para medições exatas (horizontal, vertical e 45°) Precisão de 1 mm/m (0,057°) Corpo em alumínio reforçado: leve e durável Acabamento resistente a substâncias agressivas Régua integrada para medições adicionais Tampas de extremidade para proteção contra sujeira e detritos Especificações técnicas: Comprimento: 400mm (16") Material: Alumínio reforçado Quantidade de visores: 3 Modelo: 332209 Marca: MTX Peso aproximado: 190g Garantia: 3 meses Ideal para: Construção civil Reparos e montagens Projetos de marcenaria e decoração Com o Nível de Alumínio MTX 332209, você garante alinhamentos precisos e resultados impecáveis em qualquer trabalho.', 40.9, 39.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7reox-m8kmpbr3te1l9c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F445163047%2F23698393770', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
