INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56810976375', 'Tênis Under Armour Charged Sunny Masculino', 'Desafie seus limites com o Tênis Under Armour Ch.Sunny Unissex! Projetado para corredores que buscam performance, este tênis de corrida oferece o equilíbrio ideal entre leveza e amortecimento, impulsionando você em cada quilômetro. O cabedal em knit respirável proporciona um ajuste perfeito e ventilação superior, mantendo seus pés frescos e confortáveis do início ao fim do treino. A entressola em EVA expandida garante uma absorção de impacto responsiva, transformando cada aterrissagem em energia para a próxima passada. Por fim, o solado de borracha de alta abrasão assegura durabilidade e tração excepcional em diversas superfícies. Não perca tempo calce o tênis Under Armour e eleve seu desempenho na corrida!', 399.9, 349.9, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-823qz-mok0kvpplki7e2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1178125772%2F56810976375', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23794206500', 'Kit Meia Infantil Lupo Básico Cano Baixo 3 Pares', 'As meias da Lupo são fabricadas em algodão super macio, proporcionando conforto e bem-estar. O tecido é respirável, deixando os pés respirar naturalmente. É Indicado para crianças de todas as idades e para o uso diário. Ela é uma meia considerada de calcanhar verdadeiro, proporcionando um ajuste perfeito aos pés. - Calcanhar verdadeiro; - Indicada para o uso diário; - Ajuste perfeito; - Qualidade Lupo; - Algodão super macio; - Tecido respirável.', 59.9, 49.9, NULL, 'Baby & Kids Fashion > Baby & Kids Accessories > Socks', 'https://cf.shopee.com.br/file/sg-11134201-7rdvq-mc2do30uxopa5f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1178125772%2F23794206500', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58206078925', 'Frigobar Brastemp Retrô 76 Litros Marsala Wine - BRA08MG', 'O Frigobar Brastemp Retrô 76 litros com performance de refrigeração eficiente que economiza até 21% de energia elétrica no ano¹, transforma qualquer ambiente no seu mundo! O design inconfundível conta com os acabamentos vintage com pés palito, puxadores metálicos e o icônico logo Brastemp dos anos 50. Em 8 opções de cores exclusivas, sejam as clássicas ou as inspiradas nas tendências mais atuais do design, pra você escolher a que representa melhor o seu estilo. Além disso, se surpreenda com a possibilidade de armazenar tudo como você quiser, seja com os compartimentos modulares, cesto cromado ou no freezer - que dá um gelo em qualquer frigobar.', 2169.99, 2169.99, NULL, 'Home Appliances > Large Household Appliances > Others', 'https://cf.shopee.com.br/file/sg-11134201-825av-mr1z1n4gasqv56', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1648122739%2F58206078925', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58251977181', 'Pipoca Microondas Manteiga com Sal Yoki', 'A Pipoca de Microondas Yoki sabor Manteiga com Sal é perfeita para aqueles momentos de descontração em frente à TV. Prática e rápida de preparar, basta colocar no micro-ondas e em poucos minutos você terá uma pipoca deliciosa e crocante. * Milho de alta qualidade * Sabor delicioso de manteiga com sal * Não contém glúten e lactose * Contém derivados de soja Modo de preparo: - Abra a embalagem e separe o pacote de milho de pipoca. Coloque apenas o pacote de milho no centro do micro-ondas com o lado indicado para cima. - Não use o botão de pipoca. Ajuste o seu micro-ondas na potência máxima por até 3min. Atenção: ouça atentamente e, assim que o intervalo entre os estouros for maior que 2 segundos, desligue o aparelho. - Retire o pacote com cuidado (o vapor é muito quente!) abra-o puxando pelos cantos superiores. Bom apetite! Mesmo após o preparo, é normal que alguns grãos permaneçam sem estourar. O produto não deve ser preparado por crianças sem a supervisão de um adulto. Não estoure novamente nem reutilize a embalagem.', 4.79, 4.79, NULL, 'Food & Beverages > Snacks > Popcorn', 'https://cf.shopee.com.br/file/sg-11134201-8258e-mqnel3d6lreqae', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554783%2F58251977181', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594063961', 'VELA IGNIÇÃO XTZ 125 TRAXX SKY 110 NEO 115 TTR 125 YFM 80 LASER 150 WEB 100 EAGLE 50 SUPER SMART 50 WAVE 125 NGK', 'A Vela NGK CR7HSA Standard é ideal para motos e quadriciclos, garantindo um desempenho confiável e duradouro. Com a qualidade reconhecida da marca NGK, você terá a certeza de estar adquirindo um produto de alta performance. Este modelo é compatível com diversos modelos, como YBR 125, XTZ TTR 125, NEO 115, entre outros. A quantidade de velas incluída é de 1 unidade, proporcionando uma excelente relação custo-benefício. Invista na sua segurança e no bom funcionamento do seu veículo com a Vela NGK CR7HSA Standard. APLICAÇÃO: - YAMAHA YBR 125 / YBR FACTOR 125 ( 2000 ATÉ 2015 ); - YAMAHA XTZ 125 ( 2003 ATÉ 2016 ); - YAMAHA NEO 115 ( 2005 ATÉ 2012 ); - YAMAHA TTR 125 ( 2008 ATÉ 2011 ); - YAMAHA YFM 80 ( 2005 EM DIANTE ) / YFM 80R ( 2006 EM DIANTE ); - DAFRA LASER 150 ( 2008 ATÉ 2010 ); - SHINERAY 50CC - PHOENIX 50 / JET 50 / EAGLE 50 / SCOOTER BIKE 50 / SCOOTER NEW 50 / SCOOTER RETRO 50 / SUPER SMART 50; - SHINERAY NEW WAVE 125 ( TODOS OS ANOS ); - SUNDOWN FUTURE 125 ( 2005 ATÉ 2013 ); - SUNDOWN WEB 100 ( ATÉ 2004 ); - TRAXX SKY 110 ( 2003 ATÉ 2011 ). NÃO ACEITAMOS DEVOLUÇÕES DE PRODUTOS QUE JÁ FORAM MONTADOS E/OU USADOS. - Instalação- De extrema importância que o produto seja instalado nas fixações originais da moto e por um mecânico profissional - EVITAR ADAPTAÇÕES. - Todas as garantias são dadas pelos fabricantes, e variam de produto para produto. Caso tenha alguma dúvida, entre em contato conosco. - Para devoluções, os produtos deverão ser remetidos em suas embalagens originais. - Certifique-se de preencher corretamente seus dados pessoais e endereço para que não haja problemas com o pedido. - Produto Novo - Enviamos para todo o Brasil. - Todos nosso produtos acompanham Nota Fiscal! - Tire TODAS as dúvidas antes da compra - IMAGENS ILUSTRATIVAS. - EVITE TRANSTORNOS!', 30.0, 30.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Ignition', 'https://cf.shopee.com.br/file/sg-11134201-7rdwd-mckn7c0apmkz5b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842545535%2F23594063961', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23392222576', 'Babuche Sandália Chinelo Infantil Plugt Menina Confortável Macio Leve Básico Verde Neon Promoção', 'O Babuche Plugt Ventor Baby Mono Verde Neon Azul é básica e monocromática, mas é muito delicada e linda que combina com muitos looks das meninas. A palmilha tecnológica possui furinhos que ajudam na transpiração dos pés e ainda é bem confortável. A sola é levinha e antiderrapante. Comprimento da Palmilha em CM: (medida do dedão ao calcanhar) 19/20 - 13,3 cm 21/22 - 14,6 cm 23/24 - 16 cm 25/26 - 17,3 cm --------------------------------------------------------------------------------------------- SOBRE NÓS: A Plugt é uma empresa especialista em fabricação de calçados infantis injetados. O material que utilizamos é o PVC Microexpandido que além de leve, confortável, FÁCIL DE LAVAR, ainda é RECICLÁVEL (o que conseguimos fazer desde o processo produtivo até após o uso - um processo amigo do meio ambiente). Sempre nos inspiramos no poder da imaginação das crianças para criar produtos divertidos e coloridos assim como a Plugt é! Ah, e sem deixar de lado o conforto, a praticidade de calce e a facilidade em lavar que as mamães amam! Fabricamos calçados do 19/20 até o 41/42', 139.9, 29.9, NULL, 'Baby & Kids Fashion > Girl Shoes > Sandals', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ma09dpvth0cic5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F284865829%2F23392222576', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21599188721', 'CAPA PARA BANCO HONDA CB 300R 2009 a 2015 PRETA ORIGINAL CAPAS', 'Capa de Banco CB 300R 2009 A 2015 Esta capa de assento na cor preta tem uma excelente qualidade de primeira classe, feita por especialistas e profissionais de primeiro nível com as melhores matérias - primas, para garantir que sua cadeira seja durável e macia! São confeccionados em PVC e poliéster para garantir firmeza, maciez e elasticidade, podendo ser ajustados de forma excelente sem afrouxar ou formar bolhas no assento. -Contém: 1 - Capa Banco. -Marca: Original Capas -Cor : Preta Peso: 0,150 Kg Dimensões: 20x20x10 IMAGENS ILUSTRATIVAS.', 25.0, 25.0, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Covers', 'https://cf.shopee.com.br/file/sg-11134201-8260l-mldnm70tyww247', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842545535%2F21599188721', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
