INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22397722795', 'Caixa Térmica 26 Litros Preta MOR - 25108175', 'Para acompanhar seu dia na praia, camping ou até mesmo garantir as bebidas geladas e os lanchinhos em longas viagens, a Caixa Térmica 26 Litros da Mor é item indispensável! As Caixas Térmicas Mor possuem parte interna e externa em polipropileno injetado, tampa soprada e contam com isolamento em isopor. Além disso, são desenvolvidas com material 100% virgem, atóxico e sem odor, o que garante a qualidade e a durabilidade do produto. As dimensões internas da Caixa Térmica permitem que sejam armazenadas 35 latinhas de 350ml ou 5 unidades de garrafas pet de 2 Litros deitadas. Para facilitar o transporte, possui uma alça prática para você carregar sempre que desejar garantir as bebidas geladinhas para a reunião com amigos ou familiares! Material: Polipropileno Capacidade: 26 litros Informações importantes: Dimensão interna da caixa térmica: 34 cm x 25 cm x 31,5 cm Capacidade da caixa: Latinha: 35 unidades de 350 ml Garrafa pet: 5 unidades de 2 L - deitadas Garantia: 90 Dias Altura: 38,50cm Largura : 29cm Comprimento: 42,50cm Peso: 1,93kg Características: - Marca: MOR - Modelo: 25108175 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: 01x Caixa Térmica MOR 26L caixa térmica - mor - 18 litros - preta - camping - praia - piquenique - bebidas geladas - alimentos frescos', 132.65, 115.9, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/sg-11134201-7rdwq-lyz73ohbdyze70', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1088013647%2F22397722795', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18599603338', 'Enxaguante Bucal Listerine, Melancia e Hortelã sem Álcool 500ml', 'Características do Produto: Marca: Listerine Tipo de Produto: Enxaguante bucal Sabor: Melancia e Hortelã Conteúdo: 500 ml EAN: 7891010256050 Características Adicionais: Sem álcool na fórmula Enxaguante bucal número 1 do mundo Refrescância suave de melancia e hortelã 24 horas de proteção com uso a cada 12 horas Fórmula exclusiva com agentes antibacterianos Embalagem 100% reciclável (frasco e tampa) com 50% de plástico reciclado Elimina até 99% dos germes causadores de mau hálito, placa bacteriana e gengivite Mais proteção contra mau hálito, placa e gengivite quando comparado apenas à escovação Modo de Uso: Não diluir Enxaguar a boca com 20 ml por 30 segundos, de manhã e à noite, após a escovação dos dentes Precauções: Não ingerir Manter fora do alcance de crianças Não indicado para crianças menores de 12 anos Em caso de irritação ou reação adversa descontinuar o uso e consultar um profissional de saúde Fornecedor: Jntl Consumer Health (Brazil) Ltda', 32.6, 32.6, NULL, 'Home & Living > Home Care Supplies > Others', 'https://cf.shopee.com.br/file/sg-11134201-824j3-mpibqnx795oh99', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F822103155%2F18599603338', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
