INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998935218', 'Furadeira e Parafusadeira Sem Fio Black Decker ‎LD12S Bivolt', 'A Furadeira e Parafusadeira Black Decker LD12S é a escolha ideal para quem busca praticidade e desempenho em um único equipamento. Com design ergonômico e leve, ela permite realizar desde pequenos reparos até trabalhos mais exigentes com facilidade. Sua bateria de 12V proporciona autonomia para diferentes aplicações, enquanto o mandril de 3/8" (10mm) sem chave garante trocas rápidas e eficientes de acessórios. Seja para furar ou parafusar, essa ferramenta entrega precisão e conforto em cada uso. Principais Características: - Bateria de 12V - 1.5Ah: Maior autonomia e praticidade para trabalhos contínuos. - Mandril de 3/8" (10mm) sem chave: Facilita a troca rápida de brocas e pontas. - Velocidade variável até 900 RPM: Ajuste conforme a necessidade de cada aplicação. - Torque de 16Nm: Potência ideal para fixações e perfurações em diferentes materiais. - Empunhadura emborrachada: Conforto e firmeza para longos períodos de uso. - Luz LED integrada: Iluminação para áreas de difícil acesso, garantindo mais precisão. Acessórios Inclusos - 1 carregador; - 10 pontas para fixação; - 2 brocas para metal; - 1 extensor para bits. Adquira agora a Furadeira e Parafusadeira Black Decker LD12S e tenha em mãos uma ferramenta versátil e eficiente para todas as suas tarefas!', 273.28, 233.1, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-820lq-mqnrh1oydywyee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1475265282%2F23998935218', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250495575', 'TOP CROPPED FITNESS FEMININO COM RECORTES OASIS DLK', 'Top Cropped Fitness Feminino Com Recortes Oasis O Top Cropped Fitness Feminino Com Recortes Oasis é a peça ideal para quem busca desempenho, conforto e proteção em seus treinos. Esse top tem um design moderno e é ideal tanto para suas atividades físicas, quanto para composições casuais, garantindo conforto e estilo. Tecido de Alta Performance O Top Fitness é feito em tecido super macio. Ele é confortável e proporciona sensação agradável à pele, enquanto suas alças largas reforçam a segurança, ideal para treinos intensos ou para compor um look casual urbano. A tecnologia de secagem rápida mantém você seca e confortável, permitindo que o suor evapore rapidamente durante suas atividades. Além disso, este top oferece proteção solar UV 50+, protegendo sua pele durante treinos ao ar livre. Design e Funcionalidade Com esse Top Fitness você tem o melhor em tecnologia de tecidos e design funcional. Seja na academia, corrida ou ioga ao ar livre, ele oferece a combinação perfeita entre estilo, proteção e conforto!', 92.99, 92.99, NULL, 'Women Clothes > Tops > Tube Tops', 'https://cf.shopee.com.br/file/sg-11134201-821fj-mgwj39puayo84b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1628803380%2F58250495575', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
