INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18963935035', 'Auto Falante Triaxial 6 Polegadas Hurricane A6t 120w rms Par', 'A linha Aurum foi desenvolvido com as mais novas tendências tecnológicas. Qualidade e resposta sonora de alta definição são algumas das caracteristicas marcantes desta linha. Seu design inovador e moderno, aliado ao projeto dimencional adequado faz desta linha o que há de mais moderno no mercado. A sua construção robusta com carcaça injetada, cone de PP, borda sobre injetada e bobina de kapton e conjunto com torre de tweeters com imã de ferrite e piezo, que o tornou uma referência no mercado. Pode ser utilizado com amplificador ou diretamente no seu player. Especificação Técnica: Modelo A6 T Código 10000249 Potência RMS (par) 120W Potência Máx. (par) 240W Impedância 4 ohms Resposta de Frequência 80Hz ~ 22KHz Sensibilidade (dB/W/m) 89 dB Cone PPI Borda Borracha Carcaça Injetada em PP Bobina Alumínio Ø 1" Tweeter Piezo Bobina Aluminio Diafragma PEI 55mm Tweeters Piezo Diafragma Mylar', 127.08, 113.0, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/sg-11134201-22110-kc60oqlld7jvb9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328179142%2F18963935035', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
