INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259859809', 'Kit Alto Falante Automotivo 5 Pol M7 200w Triaxial M50PRO', 'KIT ALTO-FALANTES 5” M7 M50PRO 200W – POTÊNCIA E FIDELIDADE PARA SEU CARRO O Kit M7 M50PRO foi desenvolvido para quem não abre mão de qualidade sonora no dia a dia. Com tecnologia triaxial, ele entrega uma experiência de áudio completa, preenchendo o interior do veículo com um som envolvente e potente. Por que escolher o M7 M50PRO? Som de Alta Definição: O sistema triaxial garante que você ouça cada detalhe da música, desde a batida do grave até a voz e os instrumentos mais agudos. Tecnologia de Ponta: Equipado com bobina em Kapton e conjunto magnético de alta força (70x10mm), garantindo que o som não distorça mesmo em volumes mais altos. Durabilidade Premium: O cone em polipropileno injetado e o chassis em aço carbono garantem que o produto suporte vibrações e variações de temperatura sem perder a performance. Design Universal: Com 5 polegadas, ele é compatível com a maioria dos veículos do mercado, sendo fácil de instalar nos locais originais das portas ou laterais. Ideal para: Substituição de alto-falantes originais, sistemas de som interno e projetos de áudio de entrada com excelente custo-benefício. Conteúdo da Embalagem: 01 Par de Alto-Falantes 5 Polegadas M50PRO M7', 94.43, 94.43, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-820lb-mnnaavoowglgcc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F369458625%2F58259859809', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
