INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694078541', 'Sabonete de Glicerina Granado Bebe Tradicional, Liquido, 1 Unidade Com 250Ml', 'Sabonete Líquido Granado Bebê Tradicional 250ml é formulado com glicerina vegetal e pH balanceado, garantindo limpeza suave e eficaz para a pele delicada do bebê. Sua fragrância suave proporciona uma sensação agradável de frescor e bem-estar. Dermatologicamente testado e livre de parabenos e ingredientes de origem animal, é ideal para uso diário, mantendo a pele do bebê hidratada, protegida e confortável após o banho.', 31.59, 31.59, NULL, 'Mom & Baby > Bath & Body Care > Hair Care & Body Wash', 'https://cf.shopee.com.br/file/sg-11134201-7rauh-mamxvg4laiq862', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1547988074%2F22694078541', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
