INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19499088959', 'Óleo Vegetal de Rosa Mosqueta 30ml - Grandha Alkimia 100% PURO regeneração da pele e o combate', 'ÓLEO VEGETAL DE ROSA MOSQUETA: A Beleza da Natureza em um Frasco Imagine proporcionar à sua pele e cabelos a riqueza da natureza em sua forma mais pura. Apresentamos o Óleo Vegetal de Rosa Mosqueta da Alkymia di Grandha, um verdadeiro tesouro natural repleto de benefícios para a sua beleza. Principais Características e Benefícios: Rico em Ácidos Graxos e Vitamina A: Este óleo é uma fonte natural de ácidos graxos como oléico, linolêico e linolênico, bem como Vitamina A, que contribuem para a regeneração da pele e o combate a estrias, cicatrizes, rugas e linhas de expressão. Regenerador e Emoliente: O Óleo de Rosa Mosqueta é amplamente reconhecido por sua capacidade de regenerar a pele, mantendo-a macia e hidratada. Uso Versátil: Pode ser aplicado em massagens corporais, faciais e cranianas. Além disso, é um aliado perfeito para hidratar e nutrir os cabelos. Integridade e Pureza: Os produtos da Alkymia di Grandha são conhecidos por sua pureza. Nossos óleos vegetais não contêm corantes, conservantes ou fragrâncias adicionados. Como Usar: Para aproveitar ao máximo os benefícios do Óleo Vegetal de Rosa Mosqueta: Aplique o óleo em massagens corporais, faciais, cranianas ou como parte de preparados para hidratar e lubrificar os cabelos. Para obter resultados aprimorados, você pode associar 5 gotas de óleo essencial a cada 10 ml de óleo vegetal carreador. Informações Adicionais: Certificado pela ABT: Este produto é certificado pela Academia Brasileira de Tricologia, garantindo sua qualidade e eficácia. Puro e Natural: O Óleo Vegetal de Rosa Mosqueta mantém suas propriedades naturais sem aditivos artificiais. Compromisso Ético: Nossos produtos não são testados em animais. Ofereça à sua pele e cabelos os cuidados que merecem com o Óleo Vegetal de Rosa Mosqueta da Alkymia di Grandha. Transforme sua rotina de beleza com a beleza da natureza. Garanta o seu frasco agora e descubra o segredo da vitalidade e regeneração da pele e dos cabelos!', 80.39, 80.39, NULL, 'Beauty > Bath & Body Care > Body Oil', 'https://cf.shopee.com.br/file/sg-11134201-7rbl1-lngg7yj0p8ljfc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F337450537%2F19499088959', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10404793131', 'Jogo Chave Fenda e Philips Cromo Vanádio com 10 peças Vonder', 'Conteúdo da embalagem 1 Jogo de chaves de fenda/phillips, composto por 10 peças, sendo: 6 chaves de fenda (1/8" x 2", 3/16" x 1.1/2" (toco), 3/16" x 3", 1/4" x 1.1/2" (toco), 1/4" x 4" e 5/16" x 6") e 4 chaves phillips (1/8" x 2", 3/16" x 1.1/2" (toco), 3/16" x 3" e 1/4" x 4") Aplicações e dicas de uso Indicado para fixar e soltar parafusos fenda/phillips Destaques e diferenciais Produzido em aço cromo vanádio, proporcionando maior resistência e durabilidade. Possui acabamento niquelado que aumenta a proteção contra oxidação/corrosão. Conta com ponta magnetizada que facilita tanto a colocação quanto a retirada de parafusos em locais de difícil acesso, além de cabo anatômico em polipropileno que garante maior conforto ao operador. DETALHES TÉCNICOS Material do jogo de chave fenda e phillips: Aço cromo vanádio Acabamento do jogo de chave de fenda e phillips: Niquelado Material do cabo da chave: Polipropileno Cor do cabo da chave: Amarelo', 68.9, 68.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-8262m-ml5i2zef5jbh12', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442555366%2F10404793131', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
