INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22699157727', 'Vinil Dinah Washington - Great Women Of Song: Dinah Washington - Importado', 'Vinil Dinah Washington - Great Women Of Song: Dinah Washington - Importado Como diria Duke Ellington, DINAH WASHINGTON estava "além da categoria". Sutil e inventiva o suficiente para ocupar um lugar de honra no panteão do jazz, mas firme e contundente o suficiente para atrair a atenção do público de blues, R&B e rock & roll. Igualmente à vontade interpretando canções da Broadway, pop ou jazz, Washington combinava a delicadeza urbana com a garra caseira para criar uma música que refletisse sua personalidade forte e extraordinária. Repertório do LP: Lado A: A1. What A Difference A Day Made A2. It''s Magic A3. I Can''t Believe You''re In Love With Me A4. Baby (You''ve Got What It Takes) A5. I Get A Kick Out Of You A6. September In The Rain A7. This Bitter Earth Lado B: B1. Teach Me Tonight B2. Smoke Gets In Your Eyes B3. Cry Me A River B4. Mad About The Boy B5. After You''ve Gone B6. Is You Is Or Is You Ain''t My Baby? B7. A Rockin'' Good Way (To Mess Around And Fall In Love)', 249.9, 249.9, NULL, 'Hobbies & Collections > Vinyl Records', 'https://cf.shopee.com.br/file/sg-11134201-82593-mq6xsppr93bha6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1356917260%2F22699157727', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
