INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21596887248', 'Inoar Creme de Pentear Meu Cacho Meu Crush 500ml', 'Inoar Creme de Pentear Meu Cacho Meu Crush 500ml Creme para pentear indicado para cabelos ondulados, cacheados ou crespos. Inoar Meu Cacho, Meu Crush define as curvas e ajuda a desembaraçar. Para fios saudáveis, lindos e sem frizz. Creme para Pentear Inoar Meu Cacho, Meu Crush conta com fórmula rica que penetra fundo na fibra capilar e traz hidratação e emoliência, essenciais para a saúde e beleza dos cachos. Perfeito para quem quer valorizar e assumir sua textura natural. Conselho de Aplicação: Nos cabelos limpos e úmidos, aplique a quantidade suficiente do creme para pentear pelo comprimento e pontas, mas evite a raiz. Com um pente de dentes largos, desembarace os fios e deixe secar naturalmente ou use um difusor. Modele como desejar. Contém: 1- Inoar Creme de Pentear Meu Cacho Meu Crush 500ml', 51.8, 51.8, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7qvdk-lg2qnuqs05qma9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290896931%2F21596887248', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22994311727', 'Troninho Penico Infantil Musical Desfralde Tigre Replay Kids', 'Troninho Penico Infantil Musical Desfralde Que Vira Banquinho Tigre Replay Kids O Troninho Musical é mais uma ideia prática e inovadora da Replay Kids para o dia a dia da mamãe com o bebê. Facilitando a transição do desfralde de fraldas para o assento de forma lúdica e divertida. Modo Troninho: Base antiderrapante, garantindo estabilidade para a criança, o assento possui uma pequena elevação no meio para bloquear possíveis respingos, com reservatório removível que facilita na hora de higienizar e tampa fixa com bichinhos para inibir odores. Botão musical para descontrair a criança tornando o momento mais calmo e divertido. Modo Banquinho: Possibilita transformar o troninho em um banquinho, quando virado de cabeça para baixo e retirado as alças de apoio. Ideal para o descanso das crianças e atividades extras. Possui adesivos que podem ser colados em qualquer lugar do troninho estimulando a criatividade e imaginação da criança. Prático e Portátil: Cabe em qualquer cantinho da casa, ideal para levar em viagens e passeios. Feito com materiais resistente garantindo conforto e segurança. Principais Características: - Idade recomendada: A partir de 12 meses - Assento de tampa fixa - Reservatório removível - Interativo com música - Vira Banquinho - Base antiderrapante - Fácil de limpar - Uso no chão - Pratico e Portátil: Cabe em qualquer cantinho da casa - Ideal para Desfralde - Conforto e Segurança Especificações Técnicas: - Conteúdo da Embalagem: 1 Troninho Penico - Material/Composição: Estrutura em plástico resistente / Polipropileno - Dimensões do Produto: ‎32,0 x 25,0 x 36,0 cm - Garantia: 90 Dias (Contra Defeito de Fabricação Pelo Fabricante) - Referência do Fabricante: 21823 - Cód. EAN: 7899403218234 - Marca: Replay Kids Imagens meramente ilustrativas, as cores e estampas podem variar de acordo com o lote do fabricante.', 129.9, 129.9, NULL, 'Mom & Baby > Diapering & Potty > Potty Training & Commode Chairs', 'https://cf.shopee.com.br/file/sg-11134201-7rdxh-mdf15ccrr7r08b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F828882817%2F22994311727', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
