INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58158172195', 'Lovito Conjuntos de Saias Casuais com Laço Plissado Verde Claro Primavera/Verão LK5ED443', '✅DESTAQUES -❤️Arco -❤️Plicado -❤️Macio e confortável -❤️Primavera e verão -❤️Fim de semana casual ✅DESCRIÇÕES Estampa / Padrão:Plain Estilo:Casual Tamanho Plus:No Material:Poliéster Composição:100%Polyester Tipo de modelagem:Regular Fit Transparência:No Esticar:Non-stretch Feito na China ✅O PACOTE INCLUI 1XConjuntos de saia ✅INTRODUÇÃO LOVITO A Lovito é uma marca em crescimento que acredita no poder das meninas. Estamos comprometidos em oferecer opções de roupas fashion e acessíveis, para todos os estilos, necessidades e identidades. Acreditamos que a moda deve ser divertida, liberadora e fazer você se sentir incrível. Afinal, o melhor acessório para qualquer look é a autoconfiança! ✅NOTAS DE COMPRA Antes de comprar, dê uma olhadinha na tabela de medidas disponível no site. Lembre-se de que, por serem feitas manualmente, as medidas podem variar de 1 a 2 cm. As cores dos produtos também podem ter pequenas diferenças em relação às fotos, dependendo da iluminação e das configurações do seu dispositivo. Siga nossa loja e conheça novos itens e as melhores ofertas para você!! Se você tiver alguma dúvida, converse conosco e responderemos o mais rápido possível.', 76.5, 53.5, NULL, 'Women Clothes > Sets > Individual Sets', 'https://cf.shopee.com.br/file/sg-11134201-820nc-mnnsbfjppwxyda', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F426378412%2F58158172195', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
