INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11110177973', 'Inoar Speed Blond Shampoo Bisnaga 240ml', 'Inoar Speed Blond Shampoo Bisnaga 240ml Hidrata e elimina o amarelado dos fios loiros e grisalhos. Condiciona, desembaraça e neutraliza o tom amarelo que aparece com o passar do tempo nos fios claros. Inoar Speed Blond Shampoo Bisnaga 240ml Possui uma fórmula antioxidante e hidratante, que renova a saúde capilar, hidrata o cabelo e repõe os nutrientes perdidos durante a química, proporcionando brilho. Seus fios livres das manchas amarelas, saudáveis, condicionados e fáceis de pentear.. Ação: Óleo de Argan: hidrata e nutre os fios para que fiquem saudáveis, com maciez e brilho. Pigmentos Violeta: neutralizam o tom amarelo que fica nos fios claros com o tempo. Não testado em animais. Produto vegano. Como Usar: Shampoo (low poo): Passe o shampoo sobre o cabelo úmido massageando até a formação de espuma. Deixe agir por 3-5 minutos e, em seguida, enxágue. Use o shampoo até 2 vezes por semana.', 43.36, 39.03, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m5opdoes3s057e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290896931%2F11110177973', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22094403641', 'Interruptor Inteligente de Toque Wifi Com 3 Botões Controle por Aplicativo Alexa Tuya e Google', '🔌 Interruptor Inteligente Wi-Fi - Controle Remoto e Mais! A Tomada Inteligente Wi-Fi é o dispositivo perfeito para trazer praticidade e controle para o seu dia a dia. Compatível com sistemas Android e iOS, esta tomada oferece recursos avançados para garantir a conveniência e a segurança em sua casa ou escritório. ℹ️ Especificações Técnicas: Tensão de Entrada: 110-250V IP: 20 (Proteção contra poeira) Wi-Fi: 2.4GHz Sistemas Compatíveis: Android e iOS Cores Disponíveis: Branco e Preto 📶 Recursos e Funcionalidades: Controle Remoto: Ligue ou desligue dispositivos conectados de qualquer lugar através do seu smartphone, utilizando o aplicativo dedicado. Programação de Horários: Configure horários específicos para ligar ou desligar automaticamente os aparelhos conectados, proporcionando economia de energia e segurança. Compatibilidade com Voz: Integração com assistentes de voz como Amazon Alexa e Google Assistant, permitindo comandos de voz para controle conveniente. Proteção contra Sobrecarga: Sensor de sobrecarga integrado para proteger seus dispositivos contra danos elétricos. Design Compacto: Dimensões compactas que não ocupam muito espaço na tomada, permitindo o uso simultâneo de outras tomadas. 🏡 Aplicações Versáteis: Controle de eletrodomésticos, lâmpadas, eletroeletrônicos e mais, de forma remota e inteligente. Segurança residencial: Simule presença ligando e desligando dispositivos em horários pré-determinados. Economia de energia: Desligue dispositivos em stand-by para reduzir o consumo energético. Experimente o conforto e a praticidade de ter controle total sobre seus dispositivos elétricos com a Tomada Inteligente Wi-Fi. Simplifique sua vida e traga mais eficiência para o seu dia a dia! 📱💡', 150.0, 72.9, NULL, 'Home Appliances > Electrical Circuitry & Parts > Switches', 'https://cf.shopee.com.br/file/br-11134207-81z1k-me9c52g1awhv72', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F979730489%2F22094403641', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
