INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51859699835', 'Camisa Menina Xadrez Flanelada Pingente - Angerô', 'Camisa Menina Xadrez Flanelada Pingente - Angerô A camisa xadrez flanelada é a escolha perfeita para compor looks estilosos e confortáveis nos dias mais friozinhos. Confeccionada em malha levemente flanelada, possui manga longa, gola colarinho e fechamento em botões. Com um visual clássico que nunca sai de moda, ela traz o charme do xadrez aliado ao toque macio da flanela, garantindo aconchego e muito estilo para os pequenos. Principais características: Camisa infantil em tecido flanelado, macio e quentinho Estampa xadrez clássica, atemporal e fácil de combinar Fechamento frontal por botões, prático e funcional Mangas longas com possibilidade de uso dobrado (estilo mais despojado) Ótima opção para looks casuais, passeios e ocasiões especiais Características Gerais do Produto: • Composição Parte de Cima: 100% algodão • Cor: Azul Marinho, Bege e Pink • Gênero: Feminino • Fechamento: Fechamento em botões • Manga: Longa • Modelagem: Normal • Outros: Conforto garantido! Modelagem padrão. Consulte a tabela de medidas.', 87.0, 87.0, NULL, 'Baby & Kids Fashion > Girl Clothes > Tops', 'https://cf.shopee.com.br/file/sg-11134201-820n0-mnn6m1wtc9hf0f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F688191470%2F51859699835', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58260117070', 'Regata Masculina Em Malha Com Estampa Drop Brasil', 'DROP BRASIL: A fusão do básico com a paixão nacional em uma coleção atual e versátil. Inspirada na energia da torcida brasileira, traz estampas contemporâneas e design moderno que combinam o espírito do futebol com o estilo casual. Ideal para usar nos dias de jogo e também no dia a dia, levando a energia do Brasil para qualquer ocasião.Regata masculina em malha de algodão, com modelagem regular, alças largas e gola redonda. Sua estampa localizada e bordado de peixinhos na barra trazem um toque de estilo e originalidade para um visual autêntico. O tecido de algodão proporciona conforto e respirabilidade, ideal para compor looks casuais e despojados com versatilidade. Detalhes da peça: Malha de algodãoModelagem regularAlças largasDecote redondoBordado peixinhos', 69.99, 39.99, NULL, 'Men Clothes > Tops > Tanks', 'https://cf.shopee.com.br/file/sg-11134201-820n9-mnvhbmc81mh48b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1024179833%2F58260117070', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
