INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21198317369', 'Camisa Polo Masculina Em Piquet Pima', 'Esta camisa polo é confeccionada malha piquet de algodão pima, algodão nobre que garante toque macio e excelente durabilidade. Com meia manga e modelagem regular, oferece um caimento equilibrado e versátil. A vista embutida adiciona um detalhe clean e sofisticado, ideal para looks casuais com um toque refinado.Detalhes da peça:Algodão PimaModelagem regularMeia mangaGola tradicionalVista embutida', 269.99, 269.99, NULL, 'Men Clothes > Tops > Polo Shirts', 'https://cf.shopee.com.br/file/sg-11134201-824gl-mfibdhs6w9vu93', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1024179833%2F21198317369', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49508046730', 'Rasteira Vizzano Adorno Metálico Tira Cruzada Feminina', 'Com design clássico, a Rasteira Vizzano Adorno Metálico Tira Cruzada Femininadeixa os looks de verão mais fashions. O modelo tem cabedal com aplique metálico, fechamento por fivela veste bem com vestido midi, calças e mix de acessórios. Garanta já a sua!', 149.9, 119.9, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flat Sandals', 'https://cf.shopee.com.br/file/br-11134207-820lu-mo8b14za2j9g7c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1178125772%2F49508046730', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41251590720', 'Bota Feminina Lumiss Cano Médio Texana Western Enrugada Slouchy Country Preto', 'Estilo e conforto em um só modelo! Com cano médio levemente enrugado (slouchy), salto grosso e bico fino, essa bota é perfeita para looks modernos e versáteis — do jeans à saia. Ideal para te acompanhar do dia à noite com muito charme. ..:::.. ESPECIFICAÇÕES DO PRODUTO ..:::.. *Material Externo - Napa Sintética *Material Interno - Helanca, Material Têxtil Super Confortável *Altura do salto - 7,0 cm. *Solado - Expandido, Emborrachado Anti-Derrapante, não faz barulho, não escorrega. *Palmilha - Confortável com aplique da logo. Medida aproximada dos pés para cada numeração: Tamanho 34 --- 25,0 cm Tamanho 35 --- 26,0 cm Tamanho 36 --- 26,5 cm Tamanho 37 --- 27,0 cm Tamanho 38 --- 27,5 cm Tamanho 39 --- 28,0 cm Tamanho 40 --- 28,5 cm SOBRE A LUMISS: Desde 2018, brilha no coração da Lumiss a inovação para calçados femininos. Nascida como Amorelle, a marca é fruto do sonho de um visionário que sempre acreditou na possibilidade de fabricar calçados que surpreendessem o mercado, tanto pela variedade quanto por seus preços acessíveis. Com muito trabalho em família, essa ideia foi levada adiante, fortalecendo uma marca que hoje é referência nacional em calçados femininos, com presença marcante nos marketplaces e mais de dois milhões de pares já entregues em todo o Brasil. Comprometida com cada cliente, a Lumiss oferece as maiores tendências do mundo da moda a partir de materiais que garantem conforto, qualidade, sofisticação e estilo aos pés da mulher brasileira, encantando até mesmo os perfis mais exigentes. Além disso, a empresa se preocupa em oferecer a melhor experiência de compra, com total segurança e praticidade. Lumiss é mais que uma marca. É uma ideia que chegou para mostrar que todas as mulheres podem brilhar e ser ainda mais lindas e confiantes com calçados que as valorizam em todos os aspectos.', 299.9, 149.9, NULL, 'Women Shoes > Boots > Fashion Boots', 'https://cf.shopee.com.br/file/br-11134207-820lg-mnvu8bnlbs3o5c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F323760756%2F41251590720', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19939933747', 'Livro - Dinossauros', 'Você sabia que o Velocirraptor era pequeno, mas um ágil predador? E que a cabeça do Alossauro tinha cerca de 1 m de largura? Leia este livro com pop-ups, descubra curiosidades sobre vários dinos e divirta-se!_x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2021_x000D_ Autor: Jamille Gentile_x000D_ Idioma: Português_x000D_ Páginas: 10_x000D_ Dimensões: L 19.50 x A 20.00 x E 1.50_x000D_ ISBN: 9786555007275', 39.9, 39.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/c834a882b6aee34b45da067458b343e3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F19939933747', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
