INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8070327832', 'Livro - Jovens Titãs: Um equipe fora do comum', 'Os Jovens Titãs são um time de heróis nada convencional. Formada por cinco adolescentes, a equipe tem uma única missão: salvar o mundo de possíveis ameaças. Mas, enquanto elas não aparecem, os amigos aproveitam para se divertir. Conheça essa equipe fora de série e divirta-se colorindo as imagens com os lápis de cor que acompanham este livro! Editora: Ciranda Cultural Edição: 1, 2021 Autor: Paloma Blanca Alves Idioma: Português Páginas: 60 Dimensões: L 15.00 x A 24.00 x E 1.00 ISBN: 9786555001396', 24.9, 24.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/daa1858410cdb69b20b7c8d941c57780', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F8070327832', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253123612', 'Armário de Cozinha Jasmim 7 Portas 2 gavetas Pés Reguláveis', 'A Cozinha Jasmim é perfeita para quem busca praticidade, elegância e aproveitamento inteligente do espaço. Com um design moderno e um excelente padrão de qualidade, esse conjunto de móveis oferece durabilidade e sofisticação por um preço acessível. Diferenciais da Cozinha Jasmim: • 2 gavetas com corrediças telescópicas, garantindo um deslizamento suave e silencioso; •9 prateleiras, proporcionando amplo espaço para organização; • Puxadores em MDF, agregando resistência e um acabamento sofisticado; • Fabricado em MDP, assegurando qualidade e durabilidade; •Tampo de 25mm, conferindo robustez e elegância ao conjunto; •Acabamento Touch Alto-Relevo ou Alto Brilho UV (na cor Branca) e Semibrilho na parte interna; • Módulo aéreo, elevando o design e trazendo um toque contemporâneo ao ambiente; • Pés reguláveis, permitindo adaptação a diferentes espaços; • Fácil montagem, com manual incluso. Medidas totais: Altura 196cm | Largura 244cm | Profundidade 38,5cm (balcão) Paneleiro: Altura 196cm | Largura 53,5cm | Profundidade 38,5cm | Peso 38kg Balcão duplo: Altura 83cm | Largura 120cm | Profundidade 39cm | Peso 36kg Aéreo basculante duplo: Altura 73cm | Largura 120cm | Profundidade 29cm | Peso 24kg Aéreo geladeira: Altura 30,5cm | Largura 70cm | Profundidade 29cm | Peso 9kg Gaveta: Altura 13,2cm| Largura 58,7cm | Profundidade 35,5cm Atenção: Não nos responsabilizamos pela montagem ou instalação do produto. Recomendamos contratar um profissional especializado para garantir a montagem correta.', 1139.0, 1139.0, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjfiwv0j5ssi88', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842