INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18898212906', 'Bateria Intercambiável 18V 4.0Ah Ibv1804 Vonder', 'Bateria Intercambiável 18V 4.0Ah Ibv1804 Vonder Bateria recarregável de íons de lítio, indicada para a linha de ferramentas com sistema de bateria intercambiável VONDER. Garante alta eficiência de operação, maior autonomia e desempenho consistente. Conta com indicador de nível de carga em LED e sistema de ventilação para melhor refrigeração durante o uso. A base emborrachada protege contra riscos em superfícies e impactos leves. Itens Inclusos 1 Bateria de íons de lítio 18V 4,0Ah – VONDER IBV 1804 Especificações Técnicas Modelo: IBV 1804 Tipo de bateria: Íons de lítio Tensão: 18,0 V Capacidade: 4,0 Ah Indicador de carga: Sim (3 LEDs vermelhos) Peso aproximado: 0,5 kg Compatível com carregadores: – ICBV 1805 (carregador convencional) – ICBV 1806 (carregador rápido) – Carregador veicular 12 V (60.04.184.300) Por que escolher este produto? Produto novo e original Pronta entrega e envio em até 24 horas Compra 100% segura', 319.9, 319.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rasb-maeg5ocdelow83', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1363787561%2F18898212906', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
