INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23292006657', 'Kit 8 Corrediças Gaveta Trilho Telescópica 45cm 40kg 4 Pares', '4 Pares de corrediça telescópica para gaveta 45cm A Corrediça Telescópica light é uma solução eficiente e versátil para acomodar gavetas em móveis, garantindo uma abertura e fechamento suaves e silenciosos. Com capacidade de carga de até 40kg por par, esse conjunto é projetado para suportar o peso de diversas gavetas, proporcionando durabilidade e segurança em suas aplicações, além disso, a instalação é simples e rápida. Especificações: -Tamanho: 45cm / 450mm -Capacidade de carga: 40kg -Largura: 3,5cm -Cada par corresponde a montagem de uma gaveta -Cada par contém: Lado direito e esquerdo -Acompanha parafusos para fixação -Trava de segurança evitando a queda na abertura total da gaveta. -As esferas proporcionam um deslizamento silencioso e suave sem folga. Nuvem de tags: corrediça telescópica, corrediça gaveta, trilho telescópico, organização, funcionalidade, deslizamento suave, durabilidade, facilidade de uso, otimização de espaço, marcenaria, renovação de móveis, projetos de marcenaria, moveis planejados, armários, guarda-roupas, armarinhos, gabinetes, closets, prateleiras.', 74.9, 62.9, NULL, 'Home & Living > Furniture > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9ofrty1fj21bd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F944577712%2F23292006657', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
