INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694198061', 'Kit Coala Home - Chá Branco + Orquídea Negra', 'Este kit exclusivo combina a leveza e o frescor do chá branco com a intensidade e o mistério da orquídea negra, criando uma experiência olfativa única para todos os seus ambientes. O que vem no seu kit: Limpador Concentrado Coala Chá Branco (1 unidade): Limpeza eficaz e um perfume suave e sofisticado que permanece no ar, deixando sua casa impecável e acolhedora. Difusor de Aromas Coala Chá Branco (1 unidade): Proporciona uma liberação contínua da fragrância delicada e relaxante do chá branco, criando uma atmosfera de tranquilidade e bem-estar. Sabonete Líquido Coala Orquídea Negra (1 unidade): Limpa suavemente as mãos com uma fragrância rica e envolvente de orquídea negra, que adiciona um toque de luxo ao seu lavabo. Odorizante de Ambientes e Tecidos Coala Orquídea Negra (1 unidade): Ideal para perfumar instantaneamente qualquer cômodo ou tecido, liberando a essência marcante e elegante da orquídea negra. Com o Kit você terá: Limpeza profunda com um toque de perfume. Ambientes perfumados de forma com firmeza. Sensação de bem-estar e relaxamento. Toque de moda e sofisticação para sua casa. Transforme seu lar em um refúgio de aromas envolventes e sensações difíceis.', 80.65, 72.99, NULL, 'Home & Living > Home Fragrance & Aromatherapy > Air Fresheners & Home Fragrance', 'https://cf.shopee.com.br/file/br-11134207-81ztp-ml2ht5dws3cze4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1177903362%2F22694198061', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203117815', 'Jogo de Fronha 50cm x 70cm 2 Peças Altenburg Malha Fio Penteado Preto Primitivo', 'A Coleção Malha Fio Penteado na nova cor Preto Primitivo traz elegância e sofisticação para o seu quarto. Feita com 100% algodão de alta qualidade, a malha fio penteado oferece um toque incrivelmente macio e uma sensação de aconchego que só o algodão puro pode proporcionar. Além de seu toque suave, a malha fio penteado garante alta respirabilidade, proporcionando noites de sono mais confortáveis em qualquer estação. A cor Preto Primitivo é sofisticada e atemporal, permitindo fácil coordenação com outras cores da linha para criar combinações harmoniosas e elegantes. A coleção está disponível em edredom, jogos de cama, jogos de colcha, fronhas avulsas e lençol com elástico avulso, permitindo que você monte um enxoval completo com conforto e estilo. A Coleção Malha Fio Penteado na cor Preto Primitivo é a combinação perfeita de maciez, qualidade e elegância em cada detalhe.', 59.9, 59.9, NULL, 'Home & Living > Bedding > Bedsheets, Pillowcases & Bolster Cases', 'https://cf.shopee.com.br/file/sg-11134201-821d5-mhaesga1mfbd43', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674300605%2F58203117815', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
