INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298251460', 'Relógio Orient Masculino MBSS1442DOSX', 'Compre o Relógio Orient Masculino MBSS1442DOSX na Eclock, a maior loja de relógios do Brasil! Vamos conhecer um pouco mais sobre o produto? Possui mecanismo Analógico, a pulseira é na cor Prata, fabricada em Aço, com 25 cm de comprimento e possui Fecho Dobrável com Dois Botões. A Caixa (peça onde fica o mostrador) é fabricada em Aço, possui fundo do tipo Rosqueada, mede 4,5 cm de diâmetro, sem considerar a coroa, e 1,2 cm de espessura, o que é considerado tamanho Grande para relógios do gênero Masculino. O Relógio Orient Masculino MBSS1442DOSX tem nível de resistência à água especificado em 5 ATM. Com relação as funções adicionais do relógio: possui Calendário Analógico com Data e Marcadores com Illuminator. É Fabricado por Orient Relógios da Amazônia LTDA. CNPJ:05.830.195/0001-10 e tem Garantia de 1 Ano com o Fornecedor.', 499.0, 479.0, NULL, 'Watches > Men Watches', 'https://cf.shopee.com.br/file/sg-11134201-7rd71-m6rab2y22zdn29', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F397018433%2F22298251460', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898556211', 'Mesa de Sala Jantar Elba Tampo Madeirado c/ Vidro 120cm Niquel/Off White - Kappesberg', 'Mesa de Jantar Elba Aço c/Tampo Madeirado Chanfrado Canto Curvo c/Vidro Retangular 120x80cm, ideal p/ uso c/até 4 cadeiras - Niquel/Off White - Kappesberg Abaixo segue os produtos do KIT: Mesa Jantar Elba MDF/Vidro 120cm Niquel/Off White Kappesberg BASE PÉS MESA P/ SALA JANTAR ELBA M004 AÇO P/ USO C/TAMPO RETANGULAR ACIMA 120CM, IDEAL P/ 4 OU 6 CADEIRAS - NIQUEL - KAPPESBERG Marca: Kappesberg Linha/Modelo: Crome Dimensões(Cm): Base Mesa Jantar Elba M004 Aço Comprimento(Profundidade): 64 cm Largura: 110 cm Altura: 74,3 cm Materiais de Estrutura: - Aço Tubular Estilo do Móvel: - Moderno Tipo de Pintura: - Cromada Tipo de Acabamento da Pintura: - Pintura Alto Brilho Tipo dos Pés: - Pés Metálicos Quantidade de Pés: - Móvel possui 4 pés Montagem do Produto: - Desmontável Garantia: - Garantia Kappesberg 90 Dias TAMPO MESA MDF/VIDRO TA31 CROME 120CM - OFF WHITE/OFF WHITE - KAPPESBERG Marca: Kappesberg Linha/Modelo: MDF/Vidro TA31 Crome 120cm Dimensões(Cm): Tampo Mesa MDF/Vidro TA31 Crome 120cm Comprimento(Profundidade): 80 cm Largura: 120 cm Altura: 3 cm Materiais de Estrutura: - Estrutura em MDF Tipo de Pintura: - UV Tipo de Acabamento da Pintura: - Pintura Semi Brilho Tamanho do Tampo: - 80x120 Espessura da Estrutura do Tampo: - 30 Garantia: - 3 meses Imagens Meramente Ilustrativas. Não nos responsabilizamos pela montagem/instalação dos produtos. Todas as informações divulgadas são de responsabilidade exclusiva do fabricante/fornecedor. -Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades - Confira as dimensões do produto e analise se irão passar normalmente por elevadores, portas, escadas e corredores, pois não nos responsabilizamos caso o produto necessite durante a entrega de: Desmontagem, subir escadas ou ser transportado por guincho, cordas para apartamentos. A entrega limita-se ao descarregamento em local que tenha e ofereça total facilidade de acesso normal; - Só fazemos entregas por transportes rodoviários. Não realizamos entregas por transportes fluviais, aéreos e outros diferente de rodoviário. Não realizamos entregas na região norte: Amapá, Amazonas, Pará, Roraima e Acre; - Temos áreas com restrição e dificuldades que os transportadores rodoviários não atendem. Área de difícil acesso, área de risco, área rural, áreas fluviais, estradas não pavimentadas; - Sendo assim, caso seu endereço esteja em área restrita de entrega, a retirada de sua compra deverá ser realizada no CD do transportador ou indicar no momento da compra um endereço entrega fora da área restrita; - Caso realize pedido com entregas em locais de difícil acesso ou áreas com restrição e dificuldades que os transportadores e proprio correios não atendem, a compra sera cancelada pela Costa Rica Colchões, com a devida comunicação e estorno do pagamento ao cliente.', 1081.91, 1027.82, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/sg-11134201-8260y-mjsru7qnw83l6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1235923910%2F22898556211', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
