INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20699227303', 'Prancha de Natação Infantil Hammerhead Eva', 'Prancha de EVA Hammerhead Infantil - Acessório Essencial para Iniciantes na Natação A Prancha de EVA Hammerhead Infantil é o acessório ideal para jovens nadadores que estão começando sua jornada nas águas. Desenvolvida para auxiliar na técnica do nado e no aprimoramento dos movimentos, ela proporciona mais segurança e confiança, ajudando a criança a se desenvolver melhor, superando desafios e riscos. Com material totalmente higiênico e lavável, ela é a escolha perfeita para garantir o melhor aprendizado. Características do Produto: Tamanho Infantil: 23,5 x 31 x 3,5 cm, ideal para crianças em fase de aprendizado. Composição: 100% EVA (Etil Vinil Acetato), garantindo leveza, durabilidade e conforto. Uso Didático: Perfeita para aulas e treinos, ajudando na técnica de natação. Higiênica e Lavável: Fácil de limpar e manter, essencial para o uso frequente. Garantia contra Defeito de Fabricação: Garantia de qualidade e durabilidade. Benefícios: Aprimoramento da Técnica: A prancha ajuda a refinar a postura e os movimentos do nado. Desenvolvimento Seguro: Ideal para a criança se desenvolver nas águas de forma segura, evitando riscos. Material Durável: EVA resistente para longa durabilidade. Garantia e Política de Devolução: Garantia: 30 dias para devolução em caso de defeito de fabricação. Devolução e Reembolso: Caso o produto apresente defeito, ele será analisado e reembolsado. Desistência de Compra: Você tem 7 dias corridos após o recebimento para desistir da compra. Envio de Devoluções: Os custos de envio para devolução ou troca são cobertos pela Sloth. Com a Prancha de EVA Hammerhead Infantil, a criança vai aprender de forma divertida, segura e eficiente. Faça a diferença no aprendizado de natação com um produto original, de qualidade e com toda a confiabilidade da Sloth.', 59.9, 41.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Swimming & Diving', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lxqua9toy45292', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322737721%2F20699227303', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22899030395', 'Sandália Feminina Rasteira De Amarração Prata NICE 2036DB', 'Rasteira Feminina DUBUY 2036FG Dourado, Prata A sandália rasteira NICE DUBUY é a peça que traduz frescor e sofisticação para os dias de verão. nspirada no estilo resort wear e no mood mediterrâneo que marca a temporada primavera/verão 2026, a NICE é versátil e atemporal — perfeita para combinar com vestidos leves, saias fluídas ou até mesmo um jeans descontraído, elevando qualquer look com seu charme iluminado. Descrição Calçado: Numeração: 33 ao 40 Modelo: Nice Material: Sintético Solado: TR Palmilha: Micro expandido anatômico Altura Salto: 1,5 cm Fechamento: Fivela Medidas das Palmilhas(em cm): n°34 --- 21,8Cm n°35 --- 22,8Cm n°36 --- 24,0Cm n°37 --- 24,5Cm n°38 --- 25,0Cm n°39 --- 25,8Cm n°40 --- 26,5Cm 90 dias de garantia contra defeitos de fabricação (somente do calçado) Produto enviado com nota fiscal!', 169.99, 119.99, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flat Sandals', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfwtdiaas0lg75', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842569660%2F22899030395', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
