INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598729744', 'Jogo Aneis Motor Medida 040 Para Uno 1.0 Fire De 2001 A 2010', 'IDEAL AUTO PARTS Desde 1990 IDEAL PARA SEU CARRO Jogo Aneis Motor Medida 040 TAKAO APLICAÇÃO FIAT Palio 1.0 8v Fire De 2001 A 2010 Palio 1.0 16v Fire De 2001 A 2010 Palio Wekkend 1.0 16v De 2001 A 2010 Siena 1.0 8v Fire De 2001 A 2010 Siena 1.0 16v Fire De 2001 A 2010 Uno 1.0 Fire De 2001 A 2010 OBS: JOGO ANEIS MOTOR MEDIDA 040 CODIGO DO FABRICANTE TAKAO ASFI10A040 CONTEÚDO DA EMBALAGEM 01 Jogo Aneis De Motor QUALIDADE Produto Novo GARANTIA 03 Meses De Garantia NOTA FISCAL Sim SUPORTE PÓS VENDA Sim SOBRE A IDEAL AUTO PARTS Fundada em 1990, somos uma empresa do ramo de comércio e varejo de peças novas para veículos automotores. São mais de 30 anos oferecendo peças reconhecidas nacionalmente e internacionalmente com os melhores preços do Brasil. A paixão por automóvel e o crescimento do mercado, contribuiu para a expansão da marca e hoje contamos com quatro endereços físicos, localizados em pontos estratégicos na cidade de Limeira, Artur Nogueira e Rio Claro, no interior de São Paulo. Contamos com uma equipe especializada para prestar o melhor atendimento e oferecer exatamente o que nosso cliente precisa. São mais de 35 mil Itens de diversas montadoras a disposição em nossas lojas. CASO TENHA ALGUMA DÚVIDA USE O CAMPO DE PERGUNTAS, ESTAREMOS A DISPOSIÇÃO PARA TE ATENDER', 154.9, 154.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rdys-mcanjm8rje2a10', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616290090%2F23598729744', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
