INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23394177949', 'Par de dobradiças para Notebook Dell Latitude E5420', 'Par de hastes com dobradiças para Notebook Dell Latitude E5420 Estas hastes com dobradiças para notebook são a solução para seus problemas com o movimento de abrir e fechar a tampa do seu computador. O produto é novo, feito em material resistente e a embalagem contém duas unidades para montagem e fixação nos lados direito e esquerdo da carcaça do notebook. Com as hastes e dobradiças novas você soluciona alguns problemas: - Dificuldade ao abrir e/ou fechar o notebook - Tampa do notebook está frouxa e/ou mole - Barulho ao abrir e/ou fechar a tampa - Elevação ou rachadura na carcaça do notebook Atenção! É importante verificar a compatibilidade das hastes e dobradiças com o seu modelo de notebook para que sejam exatamente as peças que seu computador precisa. Garantia: 3 meses de garantia contra defeitos de fabricação Referência: HT029-0001 Esse produto não é compatível com o notebook Dell Latitude E5430. Recomendamos verificar o modelo exato do seu notebook antes de realizar a compra.', 65.01, 44.21, NULL, 'Computers & Accessories > Desktop & Laptop Components > Others', 'https://cf.shopee.com.br/file/sg-11134201-825bc-mq6tw4mz54b309', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801641954%2F23394177949', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
