INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20863932169', 'Alça Traseira Modelo Original Cromo Forte Compatível Com BIZ 100 1998 á 2005', 'A Alça Modelo Original Cromo Forte Biz 100 serve para amarração de pequenos objetos e fixação dos ganchos do extensor. Desenvolvida com desenho ergonômico que proporciona conforto e segurança na qual o passageiro possa segurar-se. Especificações: - Modelo: Original; - Disponível nas cores: Cromado e Preto; - Fabricado em Aço; - Valor Referente ao Par; - Marca: Cromo Forte. Aplicação: - BIZ 100 1998; - BIZ 100 1999; - BIZ 100 2000; - BIZ 100 2001; - BIZ 100 2002; - BIZ 100 2003; - BIZ 100 2004; - BIZ 100 2005. Instalação: - A instalação deve ser feita por um profissional especializado. A Sportbay não se responsabiliza por instalação mal realizada; - O produto é pronto para instalação de acordo com o modelo da moto, e encaixa-se perfeitamente no lugar do original, não sendo necessário nenhum tipo de adaptação. OBS: - Pode haver diferença de tonalidade entre a imagem e o produto real por conta do tratamento de imagens e a calibração de cores da tela de seu monitor ou aparelho. SportBay Seu Esporte Nossa Paixão.', 84.11, 69.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/sg-11134201-22110-y64de9y1b7jva6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F20863932169', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
