INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26586100114', 'Esmerilhadeira GWS 770 Bosch 770W com 6 Discos', 'Esmerilhadeira GWS 770 Bosch 770W com Discos Descrição: - A Esmerilhadeira Bosch GWS 770 M14 é ideal para serralheiros e pedreiros que buscam excelência em corte e desbaste de metais, proporcionando potência e precisão; - A ferramenta foi desenvolvida para realizar trabalhos com eficiência e segurança; - O design ergonômico assegura uma utilização confortável, mesmo nas tarefas mais exigentes; - Equipada com um potente motor que garante alto desempenho, ela se torna a escolha certa para cortes rápidos e desbaste em qualquer tipo de metal; - Seja para serralheiros experientes ou operários que procuram agregar qualidade ao seu trabalho, ela será sua aliada perfeita para produtividade e precisão; - Possui Garantia de 1 ano Bosch + 1 ano adicional fazendo o cadastro no aplicativo BeConnected. Dados Técnicos: - Marca: Bosch; - Linha: Bosch Professional; - Modelo: GWS 770; - Referência: 06013980D0 ou 06013980E0; - Tensão: 127V ou 220V (não é bivolt); - Comprimento do cabo: 2m; - Potência: 770W; - Sem velocidade variável ou controle de torque; - Diâmetro do disco: 115mm (4.1/2"); - Rotações: 11.000rpm; - Eixo: M14. Itens Inclusos: - 01 Esmerilhadeira GWS 770; - 03 Discos de corte; - 03 Discos de desbaste; - 01 Chave de aperto; - 01 porca de apoio; - 01 porca de aperto; - 01 Capa protetora; - 01 punho auxiliar.', 599.0, 599.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9elgplnzvw972', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F397583038%2F26586100114', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19799358675', 'CARENAGEM FAROL BIZ 100 AZUL PEROLA 2002/03', 'A Sportive, empresa líder em peças plásticas para motocicletas com mais de 20 anos de atuação no mercado de moto peças, desenvolve seus produtos para atender as necessidades do exigente mercado de reposição 2 rodas. Nossos produtos buscam atender o público que procuram por um produto de qualidade com baixo custo. Especificações técnicas : • Marca: Sportive; • Não acompanha Parafusos ou Presilhas; • Observação: A cor (tonalidade) segue os mesmos padrões da Moto, Modelo e Ano Original; • Segue todos os padrões Originais (sem adaptações). Instalação: • A instalação deve ser feita por um profissional especializado. não se responsabiliza por instalação mal realizada.', 87.1, 87.1, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/sg-11134201-7rdvc-lyy1wrbk3sl02a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F362325018%2F19799358675', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
