INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47660215312', 'Plástico Bolha 65cm x 100 Metros Máxima Proteção e Segurança para embalar produtos, encomendas e presente lembrancinhas', 'O Plástico Bolha 65 cm x 100m é um material versátil e resistente, ideal para proteger objetos frágeis durante mudanças ou embalagens. Ideal para embalar, proteger produtos e mercadorias para envio e transporte em mudanças e envios nos correios e e-commerces. São produzido em Filme de Polietileno de baixa densidade, com bolhas de ar, o plástico bolha é um produto que proporciona excelente proteção nos materiais nele embalados. Proporciona excelente proteção contra choques mecânicos aos materiais nele embalados. É leve, atóxico e de fácil manuseio. Especificações Plástico Bolha: • Cor: Transparente • Altura: 65 cm • Espessura: 25 micras • Comprimento : 100 M Sobre o produto: • Original. • Lacrado de fábrica. • Com garantia. • Indicada para uso geral. Com espessura de 25 micras, oferece uma proteção eficaz contra impactos e arranhões. Disponível para envio imediato, garantindo a segurança dos seus bens.', 79.0, 73.89, NULL, 'Stationery > Gift & Wrapping > Bubble Wraps', 'https://cf.shopee.com.br/file/br-11134207-820ls-moi6o8klbxmu62', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F718558431%2F47660215312', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
