INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203930676', 'Eudora La Piel Centella Asiática Loção Corporal 400ml', 'Eudora La Piel Biosensitive + Centella Asiática Loção Corporal atua na pele sensível para restaurar e fortalecer a barreira cutânea. Sua reparação intensiva se une com uma hidratação de até 48 horas. Dessa forma, os benefícios deste produto são: Diminuir do repuxamento e a vermelhidão;Evitar a descamação;Acalmar a pele;Eliminar o ressecamento. É vegano e sem sulfatos, parabenos, petrolatos e óleo mineral na composição. O item possui uma fragrância confortável que fica no corpo. Você pode passar a loção na pele úmida ou seca. Além disso, sua embalagem é feita com 50% de plástico vegetal. Nenhum produto Eudora é testado em animais, ou seja, este item possui selo Cruelty Free. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 67.9, 67.9, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/sg-11134201-8260i-mju095217t3499', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1679511787%2F58203930676', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
