INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42381481042', 'Kit 4 Roupinha N2 Para Cachorro Pequeno Porte Roupa Pet Frio', '🐾 KIT COM 4 ROUPINHAS PARA CACHORRO TAMANHO N°2 🐾 Deixe seu pet sempre confortável, protegido e cheio de estilo com este incrível kit contendo 4 roupinhas tamanho N°2. Ideal para cães de porte pequeno, o conjunto oferece praticidade para o dia a dia e garante que seu melhor amigo esteja sempre aquecido e bem vestido. ✨ BENEFÍCIOS DO PRODUTO ✅ Kit com 4 roupinhas para cachorro ✅ Tamanho N°2 ✅ Ideal para cães de porte pequeno ✅ Tecido macio e confortável ✅ Fácil de vestir e retirar ✅ Excelente acabamento ✅ Proteção contra o frio e o vento ✅ Modelos para machos e fêmeas 🐶 MAIS CONFORTO PARA O SEU PET As roupinhas foram desenvolvidas para proporcionar conforto sem limitar os movimentos, permitindo que seu pet brinque, caminhe e descanse com total liberdade. ❄️ PROTEÇÃO E PRATICIDADE Com 4 unidades, você terá mais opções para manter seu pet sempre limpinho, confortável e protegido nos dias mais frios. 📦 CONTEÚDO DA EMBALAGEM: • 4 Roupinhas para Cachorro Tamanho N°2 ⚠️ IMPORTANTE: Antes de finalizar a compra, confira as medidas do seu pet. O peso e a raça são apenas referências, sendo fundamental comparar as medidas para garantir o tamanho ideal. ❤️ Seu melhor amigo merece conforto, proteção e muito estilo em todas as ocasiões! 🐕 Ideal para cães de porte pequeno que precisam de roupinhas confortáveis, práticas e perfeitas para o uso diário.', 75.99, 64.6, NULL, 'Pets > Pet Clothing & Accessories > Pet Clothing', 'https://cf.shopee.com.br/file/sg-11134201-823r6-mp3sdb4a1p8idc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F908280603%2F42381481042', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
