INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41511902667', 'Chinelo Havaianas Power 2.0 Masculino Original', 'Hora de você colocar o seu estilo para jogo com as Havaianas Power 2.0. Hit entres os consumidores, o modelo é sucesso porque tem design diferenciado e sola com borracha extramacia. É Ideal para relaxar os pés antes e depois de praticar esportes. Disponível em tons predominantemente primários, uma tendência atual, é o produto certeiro para quem quer conforto. Garanta já o seu! Tabela de medidas, aproximadamente: Tamanho Medida do Solado 33/34 22.5 cm 35/36 23.5 cm 37/38 25.0 cm 39/40 26.3 cm 41/42 27.5 cm 43/44 29.0 cm 45/46 30.0 cm 47/48 31.5 cm Como saber sua numeração? Coloque o papel no chão: Apoie a folha de papel em uma superfície lisa e encoste a borda dela contra uma parede. Posicione o pé: Pise descalço em cima da folha, garantindo que o seu calcanhar esteja encostado firmemente na parede (sem apertar demais). Marque o dedão: Com a caneta em pé (na vertical, sem inclinar), faça um risco na folha exatamente onde termina o seu dedo mais longo (atenção: em algumas pessoas, o segundo dedo é maior que o dedão). Meça a distância: Use a régua para medir em linha reta da borda da folha (onde estava o calcanhar) até a marcação que você fez. O resultado em centímetros é a medida do seu pé.', 109.9, 79.9, NULL, 'Men Shoes > Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/br-11134207-820m9-mpo071cj981se6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1178125772%2F41511902667', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
