INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40061209437', 'Cute & Comfy Coloring Book for Adults - Fofo e Aconchegante - Livro de Colorir Adulto + 12 Canetas', 'Se colorir é o seu hobby, o Cute & Comfy - Coloring Book for Adults Special Edition é a escolha ideal para você! Um sucesso no TikTok, este livro apresenta 24 ilustrações encantadoras, perfeitas para preencher com lápis de cor ou marcadores. Além disso, acompanha 12 marcadores de ponta dupla, ideais para dar vida às suas criações com cores vibrantes. 24 ilustrações originais: Cada página é desenhada à mão, pronta para receber sua criatividade. Desenhos amplos e de fácil preenchimento: Proporciona uma experiência relaxante e envolvente, perfeita para momentos de descanso. Acompanha 12 marcadores de ponta dupla: Perfeitos para detalhes precisos e preenchimentos suaves, oferecendo versatilidade nas cores. Tamanho confortável (23,0 x 23,0 cm): Ideal para manuseio prático e fácil transporte, para você colorir em qualquer lugar. Alta resolução: Impressões nítidas e detalhadas, garantindo resultados incríveis em cada página. Deixe sua criatividade florescer e aproveite momentos de tranquilidade com o Cute & Comfy! É Um presente perfeito para você, seus familiares ou aquele amigo que também ama colorir. Combine fofura, leveza e inspiração em cada página e torne suas sessões de pintura ainda mais especiais!', 69.9, 16.9, NULL, 'Books & Magazines > Books > Sticker & Colouring Books', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfsbnv5elips82', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F482840775%2F40061209437', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
