INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23496746849', 'Lâmina Trapezoidal com 5 Unidades 48-22-1905 - Milwaukee', 'LÂMINA TRAPEZOIDAL COM 05UN PARA USO GERAL MILWAUKEE 48-22-1905 As lâminas utilitárias de uso geral da Milwaukee são projetadas para oferecer o máximo desempenho de corte e durabilidade nos materiais mais comuns encontrados em canteiros de obra. Compatíveis com estiletes padrão da Milwaukee e de outras marcas que utilizam lâminas trapezoidais, as lâminas utilitárias da Milwaukee são uma escolha versátil para profissionais que buscam alta qualidade. Com o metal disperso em metal duro, as lâminas utilitárias da Milwaukee oferecem até 3 vezes mais vida útil do que as lâminas de carbono padrão. Além disso, o processo de moagem de precisão remove as rebarbas da ponta, proporcionando cortes mais limpos. Os ângulos de moagem otimizados também oferecem maior nitidez para menos cortes repetidos. Feitas nos Estados Unidos, as lâminas utilitárias da Milwaukee são um produto confiável e durável para quem busca desempenho e eficiência em suas tarefas de corte. Com a qualidade e o desempenho garantidos pela marca Milwaukee, as lâminas utilitárias são uma escolha ideal para profissionais exigentes que buscam o melhor em seus trabalhos. Caracteristicas: O metal disperso de microcarboneto oferece vida útil até 3X mais longa do que as lâminas de carbono padrão. O processo de retificação de precisão remove a rebarba da aresta de corte para cortes mais limpos.', 22.81, 22.81, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7r98o-ll0or0duicj40c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F998294051%2F23496746849', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
