INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993611044', '12 Cestos Empilhavel Expositor Gondola Plástico Tamanho Grande Super Resistente Alta Qualidade', 'CESTO EXPOSITOR MÉDIO PRETO. - Cesto expositor empilhável para expor miudezas e deixá-las mais acessíveis ao cliente pode ser utilizado em pequenos espaços. - Ideal para estabelecimentos comerciais, deposito de materiais de construção, lojas de conveniências, aviamentos, chaveiros, peças auto-motivas, etc. - Ideal para armazenamento e exposição de produtos como roupas, calçados, alimentos, acessórios e itens em geral do comércio. Diferenciais: Pode ser encaixado formando uma estante de até 8 peças, sendo uma opção prática e econômica para armazenar e expor produtos, aproveitando melhor o espaço do estoque e da loja. Por um produto leve e prático de carregar, apresenta ótima praticidade na exposição de e/ou estocagem de produtos. Aplicações: Mercadinhos, Supermercados, Hipermercados. Lojas de Auto peças, Lojas de roupas e Calçados, Depósitos de Material de Construção, Drogarias, Perfumarias, Farmácias e Comércio em geral. ======================================================================= ESPECIFICAÇÕES Comprimento: 57cm Largura: 41cm Altura: 29cm Diâmetro Ø: Capacidade volumétrica: 55 Litros Capacidade de carga por cesto: 15 kg Quantidade Max. de empilhamento: 8 peças Peso do Produto: 0,950 kg °° 1 COMPRA = 12 PEÇAS °°', 449.98, 299.99, NULL, 'Home & Living > Home Organizers > Storage Boxes, Bags & Baskets', 'https://cf.shopee.com.br/file/br-11134207-81z1k-meeml0u75tkz83', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F601021305%2F22993611044', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
