INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22297457065', 'Cesto Lixeira 60 Litros Fechado Com Tampa Cor Preta', 'Cesto Lixeira Fechado com Tampa - Capacidade de 61 Litros - Cor Preta Adicione funcionalidade e estilo à sua casa com este Cesto Lixeira de 61 litros. Com um design elegante e compacto, esta lixeira redonda é uma adição versátil para qualquer ambiente. Principais características: - Dimensões: Comprimento: 44cm, Largura: 44cm, Altura: 64cm. - Tampa resistente e prática de remover, facilitando a limpeza e esvaziamento da lixeira. - Fabricado em polipropileno de alta resistência e design arrojado. - Ideal para uso em áreas internas e externas, como edifícios comerciais, laboratórios, hospitais, áreas alimentícias e residências. - A tampa ajuda a conter odores desagradáveis e impede a entrada de insetos, reduzindo o risco de contaminação. Adquira agora mesmo este cesto lixeira e mantenha sua casa limpa e organizada com praticidade e estilo!', 74.9, 49.9, NULL, 'Home & Living > Home Care Supplies > Trash & Recycling Bins', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ltwoas8tiu7472', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F323288678%2F22297457065', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '6484538947', 'Corrente cordão de prata 925 maculino grumet escama de peixe 60cm', 'Adicione sofisticação e brilho ao seu visual com a Corrente de Prata 925 Groumet Masculina 60cm x 2mm. Uma joia clássica e versátil, perfeita para homens que apreciam qualidade, autenticidade e elegância em cada detalhe. Destaques do Produto: Modelo: Groumet – tradicional, resistente e de excelente acabamento Comprimento: 60cm – ideal para uso masculino ou unissex Largura: 2mm – visual marcante e elegante Peso médio: 4g (aproximadamente) Metal: Prata 925 legítima (prata de lei) Fecho: Mosquetão – segurança e praticidade no uso Benefícios Exclusivos: Garantia vitalícia da autenticidade da prata 925 Certificado de autenticidade e garantia inclusos Nota fiscal eletrônica para sua segurança e tranquilidade Acompanha sacola personalizada e caixa estojo da Morelli – perfeito para presentear Por que escolher a Corrente Groumet Morelli? Prata 925 legítima: qualidade e durabilidade superiores Design clássico e fácil de combinar com diferentes estilos e pingentes Excelente opção para uso diário ou ocasiões especiais Presente sofisticado para aniversários, conquistas ou para renovar o visual O que acompanha seu pedido: 1 Corrente Groumet Prata 925 Masculina (60cm x 2mm) Certificado de autenticidade e garantia vitalícia Nota fiscal eletrônica Caixa estojo e sacola personalizada Morelli Compre com total confiança! Produto original, envio rápido e atendimento especializado. Garanta já a sua corrente de prata 925 e destaque-se com estilo, elegância e autenticidade!', 419.0, 419.0, NULL, 'Fashion Accessories > Necklaces', 'https://cf.shopee.com.br/file/sg-11134201-7rat4-ma1xfg8zjvx581', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333642032%2F6484538947', NULL, NULL, '2026-07-