INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '3992596676', 'Livro - A ilha misteriosa - Capa comum - Principis', 'Depois de sequestrar um balão de um campo confederado, um grupo de cinco abolicionistas americanos cai das nuvens em uma ilha vulcânica desconhecida no oceano Pacífico. Agora, precisam lutar pela própria sobrevivência. Juntos eles se empenham em construir uma colônia do zero, mas a ilha de recursos abundantes tem segredos inimagináveis que somente a mente criativa de Júlio Verne é capaz de descrever. Editora: Principis Edição: 1, 2021 Autor: Júlio Verne Idioma: Português Páginas: 416 Dimensões: L 15.50 x A 22.60 x E 4.00 ISBN: 9786555521740', 39.9, 39.9, NULL, 'Books & Magazines > Books > Action, Crime & Thrillers', 'https://cf.shopee.com.br/file/fc81c77da2e2596e2e6f987c275c32dd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F3992596676', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
