INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53104974211', 'Glazy 5l Limpa Vidros 4 Em 1 Redutor Atrito Risco Vonixx', 'O Limpa Vidros 4 Em 1 Redutor de Atrito Risco Glazy 5L da marca Vonixx é a solução ideal para quem busca um cuidado especial com os vidros de veículos. Este inovador produto não apenas limpa, mas também protege e condiciona, proporcionando um acabamento de alto desempenho. Graças à sua fórmula com polímeros especiais, o Glazy reduz significativamente o atrito, prevenindo riscos indesejados causados por limpadores de para-brisas e o movimento dos vidros laterais. Apresentado em uma prática garrafa de 1,5 L, seu uso resulta em um toque liso e um aspecto de vidro impecável. Além disso, a linha é completamente nova e não voável, sendo perfeita para quem valoriza a qualidade e o cuidado com o automóvel. Adicione o Glazy à sua rotina de limpeza e experimente a diferença em seus vidros!', 133.46, 133.46, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-82635-mjpxsbwdx8uc70', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1151751638%2F53104974211', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19999849803', 'Minimanual de Português: Enem, vestibulares e concursos', 'CONHEÇA O PRODUTO Autor: Benedicta Aparecida Costa dos Reis, Júlia Rodrigues e Roxana Flores Condori Coordenação: Bruno Galelli Chieregatti e João de Sá Brasil Lima DESTAQUES: Abordagem teórica com linguagem simples para auxiliar os estudos de quem não quer perder tempo; Conteúdo didático dividido por assuntos, de acordo com os editais do Enem, vestibulares e concursos públicos; Questões comentadas das provas dos últimos concursos e principais vestibulares; A Coleção Minimanuais - ENEM, Vestibulares e Concursos constitui um instrumento valioso para estudo, pesquisa e consulta das mais variadas áreas do conhecimento humano. Com linguagem acessível, este livro da coleção contempla teoria simplificada e questões resolvidas. A teoria está de acordo com o conteúdo programático exigido em editais do Enem, vestibulares e concursos públicos. A apresentação da resolução da questão visa à sistematização didática dos conhecimentos adquiridos. Nela, o alunado acompanhará as etapas de resolução como se estivesse assistindo a uma aula. Neste livro você verá com que frequência os tópicos da disciplina foram abordados pelas principais bancas organizadoras nos últimos exames. Tomaram-se por base as questões presentes neste livro. É, portanto, uma ferramenta importante para que o aluno conheça o perfil da banca para a qual prestará o seu próximo exame. Os coordenadores', 39.9, 39.9, NULL, 'Books & Magazines > Books > Politics, Law & Social Sciences', 'https://cf.shopee.com.br/file/br-11134207-820ln-mpdn71uvn5s6e5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F626529639%2F19999849803', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
